WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[76362] = { title = "An Antlered Skull", description = "<Despite its surroundings, this skull does not appear to be fel-corrupted.\n\nAs you move your hand closer, you feel a sense of calm emanating from it. \n\nSoridormi will want to see this.>", objectives = "Bring the Antlered Skull to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", completion = "<Soridormi gingerly raises the skull to eye level.>\n\nYou said you found this by a fel-corrupted Illidan?\n\nI assume this is Malfurion.\n\nAnd we thought their family problems in our timeline were bad." }
WordHunterWoW_QuestEN[76364] = { title = "Twilight Terror", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76365] = { title = "Twilight Terror - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
