WordHunterWoW_QuestEN[76367] = { title = "Hibernation Heroes", description = "", objectives = "" }
WordHunterWoW_QuestEN[76368] = { title = "Ztest", description = "descriptionYou will receive:", objectives = "logdescriptionYou will receive:" }
WordHunterWoW_QuestEN[76379] = { title = "A Murloc and a Dragon Walk into a Time Rift...", description = "Grurguglg.\n\nGuuglrllghulgrgl grugll gur. Murgllgllrugl guglrllg murgu gruggullgl. Murglgurrrr gurgll Gurlgul, guruuuurllgr gurgull gurgllglrl  .\n\nArgurgulul?\n\n<You aren't certain what's being said. This world's version of Alexstrasza is handing you an hourglass and miming flipping it. It is probably of interest to Soridormi.>", objectives = "Bring the Azmerlothian Hourglass to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", completion = "<Soridormi looks at the hourglass you carry.>\n\nThis hourglass is of bronze dragon manufacture. It allows someone to temporarily leap to a different timeway. \n\nYou said that this was given to you by that timeway's iteration of Alexstrasza? \n\n<Soridormi glances at Alexstrasza.>\n\nWell, this should prove interesting.\n\n<Soridormi turns the hourglass over.>" }
WordHunterWoW_QuestEN[76380] = { title = "Deadwind Derby", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76381] = { title = "Deadwind Derby - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76382] = { title = "Deadwind Derby - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76384] = { title = "The Bloom Begins", description = "I sense a change on the wind. Like the dawning rays of the sun. Like petals before they unfurl. A great swelling energy, right at the heart of the Emerald Dream.\n\nThe Bloom. It has begun.", objectives = "Witness Amirdrassil begin to bloom.", progress = "A bloom so beautiful, yet it brings such dread. Can we truly prevail?", completion = "Amirdrassil is now at its most vulnerable. Whether it shall bloom within Azeroth as a beacon of hope... Or if it shall become a harbinger of doom.\n\nIts fate is ours to protect. And protect it we must." }
WordHunterWoW_QuestEN[76385] = { title = "Hazardous Horticulture", description = "We may be outnumbered, but this is my domain. And I have a way of evening our odds.\n\nTake this pouch of seeds. Plant them throughout Wildfire Canyon and the Dream's faerie dragons will transform them into treants.\n\nWith luck, they will draw attention from our front lines and bolster our ground forces.", objectives = "Plant 6 Dream Seeds across Wildfire Canyon.", progress = "Hopefully the faerie dragons are small enough to go unnoticed by Fyrakk's forces.", completion = "I did not expect the Prophet of the Flame to join the fray himself. We may have less time than I thought." }
WordHunterWoW_QuestEN[76386] = { title = "A Clash of Ice and Fire", description = "The Primalists have erected great flame wards throughout their encampment. Yet we know not why. I have asked our ground forces to investigate, but they are blocked at every turn.\n\nTwo fire elementals in particular stand against us, empowered by Fyrakk's shadowflame.\n\nYou must clear the area of enemies. I have imbued this scale with my magic. Use it to weaken the elementals and any other who stands in your way.", objectives = "Slay Calderamor, Ignarion, and 15 Wildfire enemies.", progress = "Even in the heat of battle, the Primalists continue to empower those flame wards. But to what end? We must clear the way so that our forces can investigate.", completion = "I am glad my scale was of use to you. Though I cannot take to the field, I can at least empower you to fight on my behalf.\n\nI will tell our ground forces to begin their investigations. We must find out why those flame wards are being empowered." }
WordHunterWoW_QuestEN[76387] = { title = "Defense of the Ancients", description = "Fyrakk's forces at Skystone Falls are already threatening to overwhelm us. I fear not even the combined might of the Sentinels and Ancients can hold out against them.\n\nThe Ancients are bearing the brunt of the offensive. We have reports of djaradin attempting to capture them for some unknown purpose.\n\nWe cannot allow Igira to succeed in whatever nefarious plan she has in mind. You must seek out the Ancients on the battlefield and free any who are captured.", objectives = "Free the Ancients at Skystone Falls.", progress = "The Ancients may be few, but they battle fiercely for our cause. Go, <name>. Help them.", completion = "Your aid has helped the Ancients stand against the djaradin, but for how long? How many more will be lost before this battle is done?\n\nSo much sacrificed for this war. So many fallen. Too many." }
WordHunterWoW_QuestEN[76388] = { title = "Fighting Fire With Fire", description = "The notes you found, combined with Merithra's reconnaissance, have revealed Ashendir's plan. The flame wards that surround the Wellspring Temple are blocking our reinforcements.\n\nOur allies will distract Fyrakk while you and I slip behind enemy lines to destroy the wards.\n\nThe skies are filled with drakes, and I must fend them off. Once you find a flame ward and thin out its defenses, signal me to destroy it.", objectives = "Clear out Skyfire Turrets and mark Primalist Flame Wards.", completion = "Fyrakk may have retreated, but he still aims to destroy the barrier protecting the Wellspring Temple. We must break through the enemy's ranks and stop him.\n\nIt is there we will put an end to his machinations, once and for all." }
WordHunterWoW_QuestEN[76389] = { title = "The Age of Mortals", description = "Once again, the mortal races have come together to defend a World Tree. It is only fitting then that we bolster their efforts with a relic from that past battle. The Horn of Cenarius.\n\nI entrust the horn to you, {name}. Use it to bestow the blessings of Cenarius to our allies. With luck, it will allow us to break through Fyrakk's forces and open a path to the temple.\n\nAnd do not forget to lend your strength as well. Every enemy felled is one fewer between us and Fyrakk.", objectives = "Blow the Horn of Cenarius while next to heroes of Azeroth and slay Fyrakk's forces.", completion = "Our allies fight with the blessing of Cenarius! It is only a matter of time until Fyrakk's forces break their ranks and flee before us." }
WordHunterWoW_QuestEN[76390] = { title = "Inconvenience Fee", description = "I have no idea how you managed to find me or what possessed you to douse a dead guy with holy water, but we can both agree that you owe me. That stuff hurts!\n\nFortunately for you, I like bribes more than my naps. I will happily overlook this horrible first impression you gave so you and I can be best pals; scratch my back and I'll scratch yours.\n\nWhat do you say?", objectives = "Zackett Skullsmash in the rafters of Naxxramas has offered to overlook your transgression in exchange for a variety of items.", progress = "Hey, that was quick! What did you forget?", completion = "Whoa, look at this haul! You even remembered my coffee. Nobody remembers the coffee...\n\nI like you. We're going to accomplish great things together. By that, I mean you are going to bring me Scourgestones, and I am going to trade you all of the spoils that dungeon delvers of old left behind when they ate dirt. Should have stood back up when they had the chance, like me!\n\nI'll pack my things and meet you in the center ring." }
WordHunterWoW_QuestEN[76394] = { title = "Shadows of Flavor", description = "I've set out to create a meal that transcends the ordinary, one that even the emperor wouldn't turn away.\n\nI require ingredients from the darkest of shadows to craft this extraordinary meal. Many consider these ingredients forbidden, but they will become a harmony of light and shadow in my hands.\n\nPlease assist me by harvesting the following ingredients: Shadowblind Grouper, Dark-Nurtured Scallions, and a Vial of Twilight Spice.", objectives = "Collect 10 Shadowblind Grouper, 5 Dark-Nurtured Scallions, and a Vial of Twilight Spice.", progress = "Have you found all of the ingredients?", completion = "Now the magic happens. Please sample this creation for yourself." }
WordHunterWoW_QuestEN[76395] = { title = "Corruptor's Scourgestones", description = "", objectives = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nCorruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", progress = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nCorruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, <name>! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
WordHunterWoW_QuestEN[76396] = { title = "Invader's Scourgestones", description = "", objectives = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nInvader's Scourgestones are rather common, so I ask you bring a decent haul.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", progress = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nInvader's Scourgestones are rather common, so I ask you bring a decent haul.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, <name>! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
WordHunterWoW_QuestEN[76397] = { title = "Elwynn Forest Flash", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76398] = { title = "Aerial Supremacy", description = "The dragonflights have arrived. The skies are ours to reclaim! And you shall help us tip the scales.\n\nMount your drake and target the enemies above. You need only swoop in and take their forces by surprise. Your drake shall handle the rest.", objectives = "Slay 15 enemy proto-drakes flying above the Field of Flames by striking them with your dragonriding mount.", progress = "The faster we can take down Fyrakk's aerial forces, the faster we can make our way to the temple and put a stop to this madness.", completion = "Excellent. Fyrakk's forces are reeling from our assault.\n\nLet us dragons handle the rest, <name>. This is our Dream, and I will not suffer these invaders any longer." }
WordHunterWoW_QuestEN[76399] = { title = "Elwynn Forest Flash - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76400] = { title = "Elwynn Forest Flash - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76401] = { title = "Echo of the Firelands", description = "We have finally broken through the enemy's ranks, yet the Prophet of the Flame now bars our path. And he has unleashed his full power.\n\nThe Prophet must be defeated if we have any hope of making our way to the temple. I ask you to face him, champion. We shall hold back his forces as you do so.\n\nThe end is in sight. Let us finally finish this war.", objectives = "Defeat the Prophet of the Flame.", completion = "Fyrakk has broken through the barrier! He must have become desperate once he saw our forces closing in. To use that much shadowflame all at once..." }
WordHunterWoW_QuestEN[76402] = { title = "Amirdrassil, the Dream's Hope: Fyrakk", description = "Fyrakk may have entered the temple, but our fight has not ended. Thanks to your efforts, we have broken through his forces. There is still time to stop him.\n\nYou must gather your allies and follow Fyrakk into the Wellspring Temple. We will cover your flank.\n\nKnow that it is not only Amirdrassil that you protect this day, {name}. All of Azeroth will burn if Fyrakk claims the World Tree. He must be stopped, here and now. This is our final stand.", objectives = "Enter Amirdrassil, the Dream's Hope, and defeat Fyrakk.", progress = "Once, Fyrakk sought to free dragonkind. He raged a war against us for that very ideal. What drove him to seek domination instead? Was it the need for revenge? The desire for power?\n\nThe same fire that burns can also renew. Yet Fyrakk's flames would swallow the whole world.", completion = "Amirdrassil is saved, and with it all of Azeroth. Fyrakk's defeat has ensured that.\n\nFrom the champion of the Dragon Isles to the savior of the Emerald Dream. All the dragonflights owe you a great debt, <name>. And we shall not soon forget it." }
WordHunterWoW_QuestEN[76403] = { title = "Mayhem Incarnate", description = "We need to uncover exactly what Fyrakk's plan is. He is holding his forces away from the tree, but we do not know why.\n\nI can do some scouting, but direct conflict with Fyrakk would not help our cause right now.\n\nFollow me further into the Dream. There is a Primalist encampment to the north. Let us start there, so we can put an end to this madness.", objectives = "Speak with Vyranoth near the Primalist encampment.", completion = "My claws are here?" }
WordHunterWoW_QuestEN[76404] = { title = "Cogs in a Machine", description = "<This cog spiraled out of a mechanized creature as you sent it back to its timeway.\n\nWhile its design is similar to Mechagnome technology, it's sleeker and more refined.\n\nIt bears a small inscription.\n\nSoridormi will want to see this.>", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", progress = "Hello again, <name>. What do you have there?", completion = "<Soridormi reads the inscription on the cog.>\n\n\"Mechanization is the only way to true peace\".\n\nAn interesting sentiment, but also a lie. This timeway clearly continued to develop weapons for war.\n\nI can't help but wonder: if they weren't fighting each other, what were they fighting?\n\nI'll put this on the tables if you want to look at it later." }
WordHunterWoW_QuestEN[76406] = { title = "The Sins of the Ashbringer", description = "<As you near this blade, you can feel necromantic power thrumming from it.\n\nPerhaps you should wrap the sword in cloth and avoid touching it directly.\n\nSoridormi will want to see this.>", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", completion = "<As you hold the item to Soridormi, she leans backwards.>\n\nI do not need to get a closer look at that, thank you very much.\n\nWe will put it with the rest of the items. The Ebon Blade can siphon off necromantic energy. That should make it easier to handle." }
WordHunterWoW_QuestEN[76407] = { title = "Not Today, Fate", description = "Eternus intends to show us what happened. I think she also seeks to change the past.\n\nNormally, I would not entertain this idea, but understanding the infinites is the only way forward.", objectives = "Enter the Time Rift to witness the past.", progress = "Eternus has something to show us--I expect we will learn a great deal about her.", completion = "Could it be possible to help Moraidormi? On the surface, it may seem like we can.\n\nBut I sense something is... off here. Why was Vexemia chasing her? What will happen if Vexemia does not move on?\n\nI fell like we are missing something." }
WordHunterWoW_QuestEN[76410] = { title = "A Dark Summons", description = "Denizens of Azeroth,\n\nDo you thirst for power? Do you wish to change your circumstances, to become... more? \n\nMore free.\n\nMore respected.\n\nMore feared.\n\nDo you wish to become a Warlock?\n\nIf your response to any of the above is \"yes\", then meet with my humble servant Phineas.\n\nIn temptation,\n\nMadam Shadow", objectives = "Talk to Assistant Phineas in the Mage Quarter in Stormwind.", completion = "Another taker, but wait! <name>? Well now...\n\n... you're just the <class> we've been looking for!" }
WordHunterWoW_QuestEN[76416] = { title = "Forward Unto Fire", description = "Amirdrassil draws power from the Wellspring Temple in preparation for its bloom. The barrier protecting the temple will not last much longer under Fyrakk's assault.\n\nI have sent messengers all across Azeroth asking for reinforcements, but none have yet arrived. Something blocks their path into the Dream. For now, we must rely on the forces we have.\n\nI ask you to travel to the Verdant Pass. If there is anyone I would have by my side, it is you.", objectives = "Meet Alexstrasza at the Verdant Pass.", completion = "We are thankful for your arrival, <name>.\n\nOur forces have assembled, but the odds are against us. We will only be able to hold on for so long without reinforcements. Let us hope we can draw Fyrakk's attention until the Bloom is complete." }
WordHunterWoW_QuestEN[76419] = { title = "Violence Will Solve It", description = "Do you not agree that Moraidormi can be saved? We infinites often save those we think suffered needlessly--worthy or not.\n\nSupposedly, Mori died too close to the Caverns of Time just east of us. Using too much time magic here could have... consequences.\n\nBut this should be quick. Chrono-Lord Deios was in possession of artifacts that could forcefully rewind time. The bronze dragonflight has them now. \n\nWe will rewind time and then destroy Vexemia.\n\nSimple.", objectives = "Rewind time and defend Moraidormi from Vexemia's attack.", progress = "This will be easy. Which makes one wonder why the bronze dragonflight did not do it before!", completion = "That... did not go as I had planned.\n\nBut I will not give up! We can just rewind again until we get it right." }
WordHunterWoW_QuestEN[76420] = { title = "Butterfly Effects", description = "We were overwhelmed by her companions. Moraidormi was still killed.\n\nI need another strategy, one that will actually protect her. She is what matters. Go rewind time, including our actions.\n\nAfter the rewind, I will hold time in place. Then we can try to make defenses for her.", objectives = "After rewinding time, create defenses for Moraidormi and test them.", progress = "What else can we do?", completion = "That was not any better.\n\nIt--it was clearly even worse...\n\nI am trying not to lose focus. What if we attacked again or..." }
WordHunterWoW_QuestEN[76421] = { title = "The Fate We Make", description = "We just need to be stronger and faster!\n\nWe cannot leave it like this, not with the eggs also destroyed.\n\nI will come up with another idea. Restart time, and...\n\n<Eternus sighs.>\n\nPerhaps I will listen to Nozdormu. He keeps telling me I have \"missed\" something...", objectives = "Rewind history again and see what Nozdormu has to say.", progress = "Doing nothing makes no sense to me, but I will be patient. For now.", completion = "Moraidormi. The whelp. I see now." }
WordHunterWoW_QuestEN[76422] = { title = "Infinity and Beyond", description = "If we continue to look into the past, we miss out on the present--or even the future.\n\nLet us return to Thaldraszus.\n\nDo not worry about these time fracture elementals. They too will heal with time.\n\nAs we all do.", objectives = "Return to the present to check in with Chromie.", progress = "I hope this experience can bring us together.", completion = "We all learned something new today.\n\nMyself included.\n\nTime never stops teaching. It falls to all of us to always listen and learn." }
WordHunterWoW_QuestEN[76423] = { title = "No Limits", description = "After confronting the infinites and, well, myself--we have had a lot to think about.\n\nEternus, one of the infinites, has apparently been thinking a lot too.\n\nThe infinites want to change Nozdormu into his infinite form, Murozond. We don't want that. And after learning about Nozdormu, I think Eternus may be persuaded to not want that either.\n\nI've set up a meeting between Nozdormu and Eternus to get them talking. But I want someone else there... in case something goes wrong.", objectives = "Check on Eternus and Nozdormu.", completion = "This will be a... delicate meeting. Allow me to do the talking." }
WordHunterWoW_QuestEN[76425] = { title = "Renowned with the Dream Wardens", description = "Champion! A moment of your time.\n\nWe wanted to recognize all your efforts. Meet me back at Central Encampment. We have a token of our appreciation that we'd like to give you.", objectives = "Speak with Keeper Amrymn at the Central Encampment.", completion = "Thank you so much for all that you have done." }
WordHunterWoW_QuestEN[76426] = { title = "The Kalimdor Cup Circuit", description = "The Riders of Azeroth have learned much from us, and now we test their mettle, as well as yours, skyrider!\n\nMy bronze colleagues have traveled to Kalimdor to create new challenges. They await you with many races across the continent.\n\nAre you up to the task?", objectives = "Fly through the Kalimdor Cup courses.", progress = "Have you taken wing today?", completion = "You lead the way among your fellow dragonriders! As the Kalimdor Cup continues, find other races there and prove you are a cut above the rest." }
WordHunterWoW_QuestEN[76427] = { title = "A Dark Summons", description = "Denizens of Azeroth,\n\nDo you thirst for power? Do you wish to change your circumstances, to become... more? \n\nMore free.\n\nMore respected.\n\nMore feared.\n\nDo you wish to become a Warlock?\n\nIf your response to any of the above is \"yes\", then meet with my humble servant Phineas.\n\nIn temptation,\n\nMadam Shadow", objectives = "Talk to Assistant Phineas in the Cleft of Shadow in Orgrimmar.", completion = "Another taker, but wait! <name>? Well now...\n\n... you're just the <class> we've been looking for!" }
WordHunterWoW_QuestEN[76429] = { title = "The Kalimdor Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Valdrakken.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[76430] = { title = "Beginning Impositions", description = "Darkest greetings, {race}. Ahem, yes. Yes! Darkest greetings indeed.\n\n<The lanky man seems to suddenly remember where he is.>\n\nOn behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes!\n\nAhem.\n\nShe requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows...\n\n...Madam Shadow.", objectives = "Travel to the Darkmoon Faire.", progress = "Everyone knows the way to the Faire...", completion = "You're... smaller, than I remember." }
WordHunterWoW_QuestEN[76433] = { title = "Ashen Soil", description = "It seems the Druids of the Flame wasted no time in seeking to expand their influence. \n\nDeep within these barrow dens, some manner of corruption has taken root. It will spread if left unchecked, consuming the entire den before expanding outwards to threaten the rest of the dream.\n\nTime is short, {name}. Delve into the barrow, seek out the sources of the spreading flame, and excise them before the smoldering embers can grow and spread.", objectives = "Find and excise the source of the barrow den's flame corruption.", progress = "Make haste. These flames grow brighter by the moment.", completion = "<Tyrande's expression wavers between sadness and conviction.>\n\nThese are not Fandral Staghelm's Druids of the Flame. To think that someone as kind and compassionate as Norana would count herself amongst them...\n\nWe may never truly understand the depth of the scars left by the fallen boughs of Teldrassil." }
WordHunterWoW_QuestEN[76434] = { title = "Not Yet Lost", description = "The flame did not take root here on a whim. \n\nNo doubt there are servants of the Firelands cloistered within, trying to spread their flame to the creatures that reside within these barrows. We must do what we can to save those who can still be saved, and mete out swift justice to the heretics that lurk within.", objectives = "Rescue the denizens of the Sor'theril Barrow Den.", progress = "If even one soul remains languishing within these dens, we must do everything we can to save them.", completion = "Not a day goes by where I do not mark the memories of those that fell at Teldrassil, consumed by a fire that I could not quell. \n\nBe they Kaldorei or Dryad, I will never again let the cries of the anguished go unanswered. Not while I still draw breath." }
WordHunterWoW_QuestEN[76435] = { title = "The Smoldering Copse", description = "Andi'thur tells me of smoke rising from a grove to the west. Norana's new allies are not exactly the subtle sort.\n\nI do not care what her motivations are. I will not allow her to set another inch of this land ablaze. Ride for the western groves. However the Druids of the Flame plan to seek their so-called rebirth, we will do all we can to stop them.", objectives = "Investigate the Smoldering Copse.", completion = "Norana... You were always such a kind and quiet soul. To think that you would help spur something so foul.\n\n<Tyrande sighs.>\n\nThere is much to be done." }
WordHunterWoW_QuestEN[76436] = { title = "A Scrap of Hope", description = "It is only a matter of time before Fyrakk's forces decimate our own. And then there will be nothing stopping him from entering the Wellspring Temple.\n\nIf the Prophet of the Flame is responsible for blocking our reinforcements from entering the Dream, there must be some record or communication of his plan. We just have to find it.\n\nSearch for any communications amongst Fyrakk's forces at Skystone Falls. If we can disrupt their efforts in some way, we might have a chance to turn the tide.", objectives = "Collect 8 Scraps of Parchment from Fyrakk's forces at Skystone Falls.", progress = "If Fyrakk enters the Wellspring Temple, it is not just Amirdrassil that will burn. All of Azeroth will burn with it.", completion = "Let us hope some knowledge can be gained from the communications you collected.\n\n<Alexstrasza pores over the notes you handed her. Her expression slowly changes from grim to hopeful.>\n\nYou might have just saved us all, <name>." }
WordHunterWoW_QuestEN[76437] = { title = "Burning Ground", description = "We allowed ourselves to be distracted. We thought the Druids of the Flame had followed us into the Dream, when clearly they arrived before we did.\n\nWith Amirdrassil so close at hand, we cannot allow them to plant their ashen roots here. Release their prisoners. Ransack their supplies. Do whatever you can to ensure that this burning corruption does not spread further.", objectives = "Disrupt the Smoldering Copse.", progress = "We must act quickly. The further this flame-blighted ground spreads, the more danger our allies will face in the days to come.", completion = "Even as warped by flame as they are, these druids have not forgotten the way to the dream. It will be difficult to keep them out entirely.\n\nStill, without a proper base of operations, they will struggle to expand their influence. Your deeds today will help ensure Amirdrassil's safety against this spreading fire." }
WordHunterWoW_QuestEN[76438] = { title = "Gurubashi Gala", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76439] = { title = "Gurubashi Gala - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76440] = { title = "Gurubashi Gala - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76441] = { title = "Grim Reprisal", description = "The Druids of the Flame will not allow you to proceed unfettered once your intentions here become clear.\n\nThey are my kin, my brothers and sisters under Elune... But they seek to undo all that we have toiled for. Their machinations would condemn countless lives to an all-consuming inferno.\n\nI won't allow it. We cannot allow it.\n\nDisrupt their rituals. Destroy their supplies. If they raise their blades against you, cut them down.", objectives = "Disrupt the Smoldering Copse.", progress = "Take heed. These druids' zealotry fuels their reckless ends. Should they identify you as an enemy, they will not show mercy.", completion = "To think, after all we have been through, that any druid would dare try to warp the Dream in such a way.\n\n<Tyrande scowls.>\n\nThese 'druids' are an affront to the suffering that the Kaldorei have endured." }
WordHunterWoW_QuestEN[76442] = { title = "Forlorn Hope", description = "You've arrived just in time. Norana lurks just beyond the ridge. She appears to be taking part in some manner of ritual - alongside a man who appears to be their leader.\n\nThese are powerful druids, and their strength is amplified by their ties to the Firelands. Taking the blade to all of them at once would be foolish.\n\nStill, the least we can do is disrupt their ritual. If we send them scattering, we buy ourselves time - and an opportunity to press the advance elsewhere.", objectives = "Interrupt the Flame Druids' ritual.", completion = "This so-called Prophet purports to represent the interests of the Kaldorei, but I see him plain enough. He craves power, and he exploits the fear and suffering of the Kaldorei to claim it.\n\nHis work must not continue. Not while I yet draw breath.\n\nWe've done all that we can here, for now. We must return to Amirdrassil." }
WordHunterWoW_QuestEN[76443] = { title = "The Looming Cinder", description = "The Druids of the Flame are nothing more than allies of convenience to Fyrakk and his ilk. Nevertheless, they present a dire threat to the well-being of Amirdrassil, to say nothing of the rest of the Dream.\n\nThe victory we earned here today was hard-fought, but it only served to stem the tide. No doubt the Prophet and the Priestess have already reunited with their erstwhile allies.\n\nWe should return to Merithra. She needs to know of this.", objectives = "Return to Merithra at Amirdrassil.", completion = "I am glad to see you return, <class>. Would that I could bid you a moment to rest for all of the hard work that you have done.\n\nUnfortunately, we've no such luxury. Where one flame falters, another flares in response. Amirdrassil remains in danger." }
WordHunterWoW_QuestEN[76445] = { title = "Ironforge Interceptor", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76446] = { title = "Ironforge Interceptor - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76447] = { title = "Ironforge Interceptor - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76448] = { title = "The Fate of Scalecommander Abereth", description = "According to our colleagues, this cave was used to test prospective scalecommanders.\n\nExcuse me. It either tested them or housed their remains. The trials were so difficult that it usually amounted to the same thing.\n\nWe're searching for an ancient scalecommander referenced in our records as \"The Cleaving Blade\": a promising young dracthyr whose future ended abruptly somewhere near this cave. Perhaps we'll discover how their story ends.", objectives = "Locate the three attunement relics.", progress = "Without those attunement relics we won't be able to solve this mystery, <name>.", completion = "Ah ha! Give them here and I'll calibrate your goggles." }
WordHunterWoW_QuestEN[76449] = { title = "The Endless Conflict", description = "<You notice a book beside the body of a Great Glorious Alliance soldier.\n\nQuickly flicking through the pages, you see that it's some type of journal. \n\nParts of it were ruined by a puddle of oil.\n\nSoridormi will want to see this.>", objectives = "Bring the Oil-Soaked Log Book to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", completion = "<As you hold the book out to Soridormi, she picks it up gingerly between two fingers as oil continues to leak from the book.>\n\nI'm not sure I want to look inside. You said there was legible text still left in this?\n\nWell... I suppose we can put it on the rest of the pile.\n\nAfter it has been cleaned." }
WordHunterWoW_QuestEN[76453] = { title = "A Stony Reception", description = "<This chipped stone tablet stands out from its surroundings.\n\nAs you go to pick it up, it weighs quite a lot more than you expected.\n\nSoridormi will want to see this.>", objectives = "Bring the Chipped Stone Tablet to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", completion = "<As you hold the item out to Soridormi, she nearly drops it, as the weight takes her by surprise.>\n\nThis is from the Black Empire? \n\nIt... does not look corrupted. Perhaps we should be careful nonetheless.\n\nI'll have someone come by and cleanse it, just to be sure." }
WordHunterWoW_QuestEN[76456] = { title = "Using the Idol", description = "Ah, the Idol of Ohn'ahra! Let's use it to find gems. I've hidden three gems nearby in Valdrakken, all outside.\n\nThe idol will reveal the gems when you're near.\n\nCome back when you've tracked them down.", objectives = "Use the Idol of Ohn'ahra to find 3 hidden gems, then speak with Preservationist Kathos.", progress = "Have you found the gems?", completion = "You have an eye for seeking lost objects, <name>. This skill will serve you well. \n\nOr should I say... serve US well." }
WordHunterWoW_QuestEN[76459] = { title = "The Resistance", description = "<The person in front of you is clearly an uncorrupted night elf, albeit significantly more feral and malnourished than usual.>\n\nNice world. No Legion. No fel.\n\nIf you can, send help. Suramar, ask for Tyrande.\n\n<Soridormi may want to see this.>", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", progress = "Hello again, <name>. What do you have there?", completion = "<Soridormi looks at you in a perplexed manner as you hand her a map to Suramar. Her expression changes as you explain the circumstances.>\n\nIncredible. This world has been under the rule of the Legion for ten thousand years, yet still there is a resistance. \n\nI wish we could help them, but we cannot interfere with another timeway.\n\nA horrible answer, I know." }
WordHunterWoW_QuestEN[76460] = { title = "A Dragon in Hand is Worth Two in the Roost", description = "Ah, {name}, so wonderful to see you!\n\nYou have arrived just in time. I was tasked with seeking out potential allies to aid with the protection of the world tree.\n\nYour accomplishments speak for themselves--your help in this matter would be greatly appreciated.\n\nWhat do you say, up for some diplomacy?", objectives = "Talk to Wrathion about his potential allies.", progress = "I'm quite excited to meet these new dragons.", completion = "Well then! We should go meet the representative of the netherwing. \n\nMordenaku is his name. Apparently, he is also a prince." }
WordHunterWoW_QuestEN[76461] = { title = "Draconic Diplomacy", description = "I suspect Vyranoth might also be interested in recruiting new dragons to our cause... but she'll need a little convincing. \n\nI just so happen to be very good at convincing. \n\nI'll speak with Vyranoth, and we'll meet you in Valdrakken once she's decided to join us.", objectives = "Talk to Prince Mordenaku at the Petitioners Concourse in Valdrakken.", progress = "The netherwing are a fascinating flight.", completion = "These seem like very reasonable requests. Nothing obscure, nothing secretive. \n\nI'm almost disappointed.\n\nI can handle one, but I may need your help with the rest." }
WordHunterWoW_QuestEN[76462] = { title = "Cavern Cleaning", description = "This cave is adequate. It has a commanding view of the surrounding land, and is highly defensible.\n\nBut the state of it is not acceptable. \n\nI will place an enchantment upon you. When you draw near to the smaller spiders, it will freeze them, allowing us to relocate them. The sacs and larger spider will need to be addressed with more... finality. \n\nSee that it is done.", objectives = "Clean out the spiders in the cave above the Sand-Lost Sanctum in Thaldraszus.", progress = "Have you finished?", completion = "Excellent, <class>. We can clean up the remainder and relocate them to another cave." }
WordHunterWoW_QuestEN[76463] = { title = "Delectable Delicacies", description = "Of course we will take care of the netherwhelps.\n\nHowever, we might run low on snacks. The beetles close by are a delicious treat for the little ones. \n\nCan you bring me back some juicy beetle bits? Only the best for the little darlings!", objectives = "Retrieve 10 Juicy Beetle Bits from Juicy Beetles in the Ruby Lifepools in Waking Shores.", progress = "The whelps just love to gobble up those beetle bits.", completion = "Thank you, <name>. The young ones will love these!\n\nMy goodness. First the obsidian whelps, now this?\n\nI cannot believe I am lucky enough to see this!" }
WordHunterWoW_QuestEN[76464] = { title = "The Thorignir", description = "The Thorignir of Stormheim have the strength and power to greatly aid us in defending Amirdrassil, but they have yet to come to the Dragon Isles. I suspect this... Odyn has interfered with their journey.\n\nWe will go and speak with their matriarch. Wrathion tells me her brood is amenable to your kind, and to assisting others. \n\nWe will investigate.", objectives = "Speak with the Thorignir Broodmother.", progress = "We will find out why this brood of storm drakes did not heed the call of the Isles.", completion = "How dare he deny any dragons the right to go anywhere!" }
WordHunterWoW_QuestEN[76465] = { title = "Dragon Keeping", description = "First he opposes dragonkind, then he enslaves them, denying them their birthrights.\n\nWe shall visit these so-called \"Halls of Valor,\" defeat any who oppose us, and liberate the storm drakes from that which binds them.\n\nCome along.", objectives = "Speak to Vyranoth and complete the Storm the Halls of Valor scenario.", progress = "These dragons will be freed.", completion = "The Thorignir are free of that wretched keeper's influence for now--and hopefully for good." }
WordHunterWoW_QuestEN[76469] = { title = "Blasted Lands Bolt", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76470] = { title = "Blasted Lands Bolt - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
