WordHunterWoW_QuestEN[76504] = { title = "The Tricked-Out Thinking Cap", description = "The cap has an amazing function: Put it on, and you'll know where you're going! Let's practice!\n\nThe arrow above me has a clue on it, to another arrow somewhere in Valdrakken. And THAT arrow leads to another...\n\nFollow the arrows until you find them all, and the prize at the end!", objectives = "Use the Tricked-Out Thinking Cap to find Fangli's clues, then return to Fangli Hoot.", progress = "You must wear your cap at all times while contemplating secrets. You never know what frequencies you might tap into, or who might tapping into yours.", completion = "Good work! Now you're a master of thinking!" }
WordHunterWoW_QuestEN[76506] = { title = "Dryad Fire Drill", description = "", objectives = "" }
WordHunterWoW_QuestEN[76509] = { title = "Into the Sands", description = "description", objectives = "log", completion = "The Idol of Ohn'ahra has interesting properties. I believe it can help recover another object I've been seeking.\n\nTake it south of Azim in the Shifting Sands and use it to search for fragments of the Time-Lost Tablet. \n\nIf fortune favors us, you will find all its pieces and make it whole." }
