WordHunterWoW_QuestEN[76530] = { title = "Unliving Summons", description = "We need you in Tirisfal, {name}. Come quickly.\n\nThere's a new situation brewing just outside the Ruins of Lordaeron, and it's not looking pretty. I'll get you up to speed when you arrive.", objectives = "Report to Lilian Voss in the Ruins of Lordaeron.", completion = "Thanks for being here. We've got a new problem." }
WordHunterWoW_QuestEN[76531] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[76532] = { title = "Assault on the Wellspring", description = "Terro gave his life to protect the Dream. Which means we must see it through.\n\nVyranoth should be able to handle Lethka, we must find Suzska.\n\nI hope Lethka did not attack her first. We should start looking near the Wellspring. \n\nMeet me there so we can continue our search.", objectives = "Spy on the Wellspring of Life with Buri.", progress = "Come on, let's head to the Wellspring.", completion = "Buri is here?" }
WordHunterWoW_QuestEN[76533] = { title = "Dangerous Documentation", description = "<The flickering of a hologram stands out among the surrounding greenery.>\n\nA quick investigation of the item reveals this is some sort of catalog left by a Watcher in its timeway. It details observations of the yaungol, ancestors of the tauren.\n\n<Soridormi will want to see this.>", objectives = "Return to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", completion = "<Soridormi swipes her hand through the holographic projection of the yaungol as you hand over the Watcher's Log up.>\n\nFascinating technology! So similar to that of our titans.\n\nI'm sure the log entries in it are interesting to read. I'll put it on the tables if you want to review them." }
WordHunterWoW_QuestEN[76536] = { title = "Redridge Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76537] = { title = "Redridge Rally - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76538] = { title = "Redridge Rally - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76544] = { title = "Wasteland Warriors", description = "<This book has what appears to be a modified Horde symbol on it. You recognize it as the Blood Horde symbol you have seen from timeway incursions.\n\nIt is odd it is still here, after the incursion has ended. \n\nThe book has been soaked in blood, though it has long since dried off.\n\nSoridormi might be interested in this.>", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", progress = "Hello again, <name>. What do you have there?", completion = "<Soridormi flips through the book after you hand it to her.>\n\nOur world has been at war for such a long time against one aggressor or another. \n\nSo has theirs, but they just fight each other, over and over again.\n\nIt would be easy to judge them, but our worlds are both drowned in blood.\n\n<Soridormi looks pensive.>\n\nI will put the book on the table in case you want to read it." }
WordHunterWoW_QuestEN[76545] = { title = "Brewfest in Valdrakken", description = "Have you heard? Brewfest has made its way here! You should speak to Bragdur Battlebrew in the Artisan's Market--he can tell you all about it.", objectives = "Speak to Bragdur Battlebrew.", completion = "Did ye come fer a brew? Hah! We got plenty." }
WordHunterWoW_QuestEN[76546] = { title = "Mantid Methodology", description = "<This amber sword was left behind as you knocked one of the Mantid back through a time rift.\n\nYou take a moment to ensure it's safe, then place it in your pack.\n\nPerhaps Soridormi would be interested in it.>", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", progress = "Hello again, <name>. What do you have there?", completion = "<Soridormi turns the blade over in her hands and holds it up to the light.>\n\nThis is the first time I've seen a blade made of pure amber.\n\nIt's a lot sturdier than I expected, and quite dense.\n\nGood find, <name>. I will put it on the table, in case you want to look at it later." }
WordHunterWoW_QuestEN[76547] = { title = "All That Glitters...", description = "<Having recently defeated the Time Anomaly in this timeway, you notice this golden vase glittering.\n\nIt is extremely worn, be it by time or something else. You can't make out the details of its carvings along the edges.\n\nBattered as it is, it still manages to give off a warm light, contrasting the chill here. \n\nIt looks very out of place. Soridormi may be interested in it.>", objectives = "Return to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", completion = "<Soridormi hefts the vase in her hands.>\n\nYou found this on the top of Icecrown?\n\nThat is... odd.\n\nOur Lich King, at least, was not known for his golden aesthetic, at least not in death.\n\nI will put it on the tables. Thank you, <name>." }
WordHunterWoW_QuestEN[76548] = { title = "A Fishy Gift", description = "Murglgalgul!\n\nGlulmual, rluu glua ffrl wawawamual. Lalala!\n\nMowua ha mwaaay.\n\n<Murloc You raises a fish up in both of his hands towards you. It seems very officious. Soridormi may want to see this.>", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", progress = "Hello again, <name>. What do you have there?", completion = "<Soridormi looks at you flatly as you hand her the fish.>\n\nA fish. Why thank you, <name>, I did not think you cared.\n\n\n\nI will put the fish with the other items, after temporally locking it. \n\nRemember this for later: I do not enjoy the smell of rotting fish." }
WordHunterWoW_QuestEN[76549] = { title = "Dreaming in the Dream", description = "", objectives = "" }
WordHunterWoW_QuestEN[76550] = { title = "True Sight", description = "", objectives = "" }
WordHunterWoW_QuestEN[76551] = { title = "Treasure Diving", description = "", objectives = "" }
WordHunterWoW_QuestEN[76552] = { title = "In Sync", description = "While Pedgi had you out killing slimes, I asked the investigators here how we can actually help.\n\nSeems quite a few of them are stuck in time anomalies. Luckily, I've just finished giving the metronographer a few temporal upgrades. It should now help the investigators get back in sync.\n\nBut we need to test it out first. Looks like there's someone nearby who will do the trick.", objectives = "Test the upgraded Metronographer.", progress = "Oh, I saw that Pedgi had you collect time slime grime for me. I did not ask for it and I do not need it.\n\n<Melly sighs a long suffering sigh.>\n\nAt least he's trying to be helpful.", completion = "Seems the metronographer worked just as intended! \n\nHow interesting that temporal energies are so similar to music. I wonder if the bronze dragonflight has ever conducted research on the subject...\n\nSorry, rambling. Let's get back to helping Tempo. My next paycheck depends on it." }
WordHunterWoW_QuestEN[76554] = { title = "Torch - 01", description = "descriptionYou will receive:", objectives = "logdescriptionYou will receive:" }
WordHunterWoW_QuestEN[76557] = { title = "Without Honor", description = "Ok, the goggles should be calibrated. Looks like the confluence point is right here on the ledge. I wonder what happened to him?", objectives = "Observe the Scene from the past.", progress = "I wonder what we'll find?", completion = "<Zenata frowns somberly into the distance.> \n\nThe Earth Warder's forces, going after one of their own... what do you think they meant by that?" }
WordHunterWoW_QuestEN[76558] = { title = "Base Control", description = "", objectives = "" }
WordHunterWoW_QuestEN[76559] = { title = "Our Owllies", description = "", objectives = "" }
WordHunterWoW_QuestEN[76560] = { title = "[PH] Cogs Breadcrumb", description = "Talk to the thinking cap guy. A gnome.", objectives = "" }
WordHunterWoW_QuestEN[76562] = { title = "Moat Maintenance", description = "", objectives = "" }
WordHunterWoW_QuestEN[76564] = { title = "The Tools of the Dragonkillers", description = "If you're going to go after a dragon, who better to employ than the Djaradin?\n\nLet's see what we can find, {name}.", objectives = "Locate the three attunement relics.", progress = "Without those attunement relics we won't be able to solve this mystery, <name>.", completion = "Ah ha! Give them here and I'll calibrate your goggles." }
WordHunterWoW_QuestEN[76566] = { title = "The Dryad Garden", description = "{name}, there is a situation I am personally concerned about. \n\nA garden cared for by my kin, the dryads, has suffered from growing pains amidst Amirdrassil's growth.\n\nAn overwrought druid currently tends the garden, but I suspect he will need more assistance than he has requested. \n\nPlease assist him in his task on my behalf.", objectives = "Speak with Ethidris Creekward in the Root-Bound Sanctuary.", completion = "Cenarius himself sent you? Wonderful. We need the help.\n\nWe must find that dryad acorn!" }
WordHunterWoW_QuestEN[76567] = { title = "Grousing Garden", description = "The sanctuary has been overrun!\n\nThe roots of the World Tree have grown alongside this garden, but it seems the wildlife have grown uncomfortable with the change.\n\nPlease help them get out their restless energy. Perhaps tired out, they will relax in this space again.", objectives = "Tire out 8 wildlife in the Root-Bound Sanctuary.", progress = "<Ethidris winces and rubs his shoulder.>\n\nYou would think being a bear would lend oneself resistance to being knocked around by deer.", completion = "Thank you, <name>. I can see you've calmed them down for now.\n\nThis is not the first time this has happened, and likely will not be the last. Is it simply the roots of Amirdrassil? This behavior is so strange..." }
WordHunterWoW_QuestEN[76568] = { title = "Pineshrew Panic", description = "With the garden in such disarray, the pineshrews here are hoarding seeds. Important seeds. Seeds we've spent a lot of time caring for and teaching.\n\nA gentle shake will release the seeds properly. Please hurry before they run off with any more!", objectives = "Shake out 20 Pineshrew seeds in the Root-Bound Sanctuary.", progress = "Ordinarily, pineshrews shake out collected seeds across the Dream to promote variety and growth. It's a beautiful cycle.\n\nIf you have a few hours, I have a lesson prepared about pineshrew migration habits.", completion = "It seems Dionaessa has chosen you to train her. \n\n<Ethidris's face tightens.>\n\nSplendid. Just perfect." }
WordHunterWoW_QuestEN[76569] = { title = "Druid-Guardian Conference", description = "Typically, the druid assigned to a dryad sanctuary would guide a newborn dryad until they were ready to take on a position of their own.\n\nUnfortunately, it is difficult to separate a dryad from whoever she imprints on.\n\n<Ethidris sighs and rubs his eyes.>\n\nWhich she has made very clear. Regardless, tell me about yourself. Perhaps you will be just as apt a caretaker as I would have been.", objectives = "Speak with Ethidris Creekward about raising a dryad in the Root-Bound Sanctuary.", progress = "<Ethidris furrows his brow at Dionaessa.>\n\nAmong so many other things happening right now, there's a new dryad to raise.", completion = "You regularly engage in combat and you solve problems. Sometimes for yourself, sometimes for others.\n\nThat honestly does not sound too far off from my experience with dryads.\n\nI think Dionaessa will be fine." }
WordHunterWoW_QuestEN[76570] = { title = "The Family Business", description = "I was charged with imparting knowledge on every dryad seed. Dionaessa will have retained all of my teachings, but she will be unpracticed in implementing them.\n\nSince it seems you are practiced at completing tasks, you will show Dionaessa the ropes.\n\nA group of lashers have grown strangely restless in the Twisting Wood just outside the garden. Collect some of their hearts so we can discern what has happened.", objectives = "Collect 6 Lasher Hearts in the Twisting Wood near the Root-Bound Sanctuary.", progress = "The druid Creekward told me lashers tend to lie in wait for their prey.\n\nI'm glad these are not. Makes the fight more interesting!", completion = "These hearts smell awful! Almost as awful as those podlings with the sharp little teeth..." }
WordHunterWoW_QuestEN[76571] = { title = "Growth Experience", description = "Dionaessa's connection to Cenarius gives her the ability to grow plants, but she needs space to practice.\n\nThe stirred-up wildlife here will be in your way. The Twisting Wood nearby will have plenty of space with far fewer hooves.\n\n<Melyrine smiles. Her eyes shine with intensity.>\n\nIf she gets poisoned by a podling, don't worry. Dryads are immune to poison. You are not.", objectives = "Have Dionaessa grow 3 flowers in the Twisting Wood.", progress = "Do you smell that?\n\n<Dionaessa scrunches up her face.>\n\nThe druid Creekward did not describe lashers and podlings as smelling so foul. I have been misled!", completion = "Guardian. If the podlings are poisoning the ground here, then that large growth with the incredible stench over there needs pruning!" }
WordHunterWoW_QuestEN[76572] = { title = "A Poisonous Promotion", description = "Guardian! These podlings have been poisoning the lashers, and now they have twisted that mandragora!\n\nIf we do not stop it, it will spread the poison to the garden. This must be what had the wildlife in the garden so disturbed. They were on the verge of invasion!\n\nLet us kill it. This is what you have prepared me for--a dire quest!", objectives = "Defeat the Sickened Growth in the Twisting Wood.", completion = "Hey-ah, Guardian! I have never felt more alive than with a spear in hand!\n\n<Dionaessa smiles in a way that bares all of her teeth.>\n\nThank you for your guardianship!" }
WordHunterWoW_QuestEN[76576] = { title = "An Unlikely Proposal", description = "Tuskarr artifacts, underground, deep in Djaradin territory?\n\nIf we didn't find it ourselves I wouldn't believe it. What do you think they were doing down here?\n\nOk looks like the nexus point is right here in this cave. Let's get to the bottom of this!", objectives = "Observe the Scene from the past.", progress = "I wonder what we'll find?", completion = "Tuskarr and Djaradin trading? I wonder how long that lasted." }
WordHunterWoW_QuestEN[76577] = { title = "Brewfest in Valdrakken", description = "We've sent some Brewfest shipments off to the Dragon Isles. I've heard they've started some of their own celebrations! Of course ye can't beat the festivities here, but it may be worth paying the dragons a visit!", objectives = "Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.", completion = "Did ye come fer a brew? Hah! We got plenty." }
WordHunterWoW_QuestEN[76578] = { title = "Khaz Algar Rally", description = "Race through the checkpoint rings marking the course.", objectives = "Race through the rings." }
WordHunterWoW_QuestEN[76579] = { title = "Brewfest in Valdrakken", description = "Seems the dracthyr have decided to host their own Brewfest festivities this year! Once you've finished celebrating here, you should venture to the Dragon Isles and see what they've put together.", objectives = "Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.", completion = "Did ye come fer a brew? Hah! We got plenty." }
WordHunterWoW_QuestEN[76586] = { title = "Spreading the Light", description = "", objectives = "" }
WordHunterWoW_QuestEN[76587] = { title = "Research: Centaur of Ohn'ahran Plains", description = "", objectives = "" }
WordHunterWoW_QuestEN[76588] = { title = "Defender of the Flame", description = "The Expedition forces face formidable adversaries.\n\nDrawn like moths to our keyflames, creatures of all types are intent on snuffing out the light and thwarting our rebuilding efforts.\n\nPlease help us defeat two of the most menacing denizens that threaten our keyflames. Together, we can drive back this darkness.", objectives = "Eliminate two rare creatures within the areas controlled by the keyflames.", progress = "Have you eliminated the threats?", completion = "Excellent work, that is two less threats to deal with!" }
WordHunterWoW_QuestEN[76591] = { title = "Bubbling Brews", description = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews through the city and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it!\n\nTake a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", objectives = "Collect brew bubbles in Valdrakken.", progress = "Have ye filled up the barrel?", completion = "Thank ye kindly for the help. Now if I can just convince the dracthyr to simply fly the barrels here instead of rolling 'em..." }
WordHunterWoW_QuestEN[76592] = { title = "A Single Wing", description = "Amythora has returned with grave news. The Sundered Flame live on!\n\nWe have been trying to locate and repatriate independent bands of dracthyr here in Valdrakken. I sent Amythora and Marithos to talk to the last of them, but Amythora reports they are a remnant of the Sundered Flame. \n\nAnd they have captured Marithos!\n\nGiven that he used to be one of them, Marithos could be in grave danger. We must investigate and ensure his safety.", objectives = "Look for Marithos in the Azure Span.", completion = "He is badly injured. <name>, we must help him!" }
WordHunterWoW_QuestEN[76593] = { title = "The Best Intentions", description = "Not only did they beat him--they put him in shackles too!\n\nWhat's worse is... I probably would have done the same...\n\nWe will not be able to carry Marithos out of here with this weight chained to him. The key must be around the camp somewhere. Try to find it, {name}, while I keep him comfortable.", objectives = "Look for a key to Marithos's shackles in the Lonely Falls.", progress = "We must free Marithos from his bonds.", completion = "Is that the key, <name>? Good. Let's get these shackles off of Marithos. Then we can start thinking about what to do next." }
WordHunterWoW_QuestEN[76594] = { title = "Dracthyr Down", description = "What was done to Marithos goes beyond what simple healing can fix. If we expect him to fly out of here, he will need extra care.\n\nThankfully, there are herbs nearby that may give his healing a boost--enough to get him standing, anyway.\n\nLook around and collect some of the Wingfoil nearby, {name}.", objectives = "Look for Wingfoil herbs in the Lonely Falls.", progress = "Have you found that Wingfoil? Marithos cannot fly without it.", completion = "Thank you, <name>. Now let's hope for the best..." }
WordHunterWoW_QuestEN[76595] = { title = "Urgent Exfiltration", description = "The Sundered Flame here are not going to take Quartermaster Doros's death well...\n\nThey are going to come looking for me. Marithos and Amythora are vulnerable. We cannot let them find us.\n\nSecure the perimeter and keep the Sundered Flame away from Amythora and Marithos.", objectives = "Keep the Sundered Flame away from Amythora and Marithos.", progress = "If they find us, I do not think the Sundered Flame loyalists will take prisoners.", completion = "I think they are gone. We need to get out of here--now." }
WordHunterWoW_QuestEN[76597] = { title = "On New Wings", description = "I am glad that Winglord Dezran arrived when he did. If he had not, this would have gone... very differently.\n\nWe must take Marithos back to Valdrakken so he can recuperate, but once I have debriefed Dezran, we will send an envoy to help re-introduce them to our people.\n\nThey have suffered. We have suffered. Perhaps now we can all heal.\n\nFollow me back to Valdrakken. We have much to discuss.", objectives = "Talk to Emberthal in Valdrakken.", completion = "Thank you for your help, <name>. Now that Dezran has returned, we can work to finally bring the dracthyr together." }
WordHunterWoW_QuestEN[76598] = { title = "Rough Edges", description = "I apologize for not meeting you in person, {name}, but this method seemed most timely.\n\nOur war against the Primalists has always troubled our queen, but recently she has grown increasingly upset. Something weighs on her. I know how heavy the burdens of the mind can become.\n\nShe left Valdrakken some time ago, saying she needed to find a quiet place to think, but... I am concerned.\n\nPlease--seek her out, and make sure she is all right. She does not need to know I sent you.", objectives = "Find Alexstrasza and check on her.", completion = "It grieves me to see Vyranoth in such a dark place, but I still have hope that we will stand together as we once did.\n\nI have warned her about Iridikron. That is all I can do.\n\nThe rest is up to her." }
WordHunterWoW_QuestEN[76599] = { title = "Right Between Gyro-Optics - Activate", description = "", objectives = "" }
WordHunterWoW_QuestEN[76600] = { title = "Right Between the Gyro-Optics", description = "My husband Ezgi loves those harvesters, but I don't trust them, and now you can see why!\n\nThe lights go out, and they all start trying to kill us!\n\nYou want to help me sort this out?\n\nI'm a crack shot with a rifle. You mark the target, and I'll start shooting!", objectives = "With Auebry's help, eliminate 8 Dark-Crazed Harvesters.", completion = "Ezgi is going to be upset, but you and I did what needed to be done." }
WordHunterWoW_QuestEN[76733] = { title = "Tater Trawl", description = "Harvesting in this area has become a challenge, with crazed Harvesters destroying most of our crops. There are potatoes to be found if you look closely.\n\nIf you light the harvest torches, you might uncover some potatoes hiding in the shadows. \n\nUsing those lights, gather as many potatoes as you can. Every bit helps in these trying times.", objectives = "Light 5 Harvest Torches and gather 15 Firelight Spuds.", progress = "Have you found any spuds?", completion = "This is perfect. We love fried potato fingers, we're going to cook up some of those tonight!" }
WordHunterWoW_QuestEN[76734] = { title = "Research: Djaradin of Zaralek Cavern", description = "", objectives = "" }
WordHunterWoW_QuestEN[76735] = { title = "Rise in Relic Theft", description = "", objectives = "The inns are abuzz with rumors of aspiring criminals pilfering sacred relics.\n\nI'm overseeing the return of stolen goods to their rightful owners. I hear you can be trusted to help.\n\nPlease take this ceremonial tuskarr spear back to Iskaara. And watch out for looters!" }
WordHunterWoW_QuestEN[76738] = { title = "Repeatable Aura Remove", description = "", objectives = "" }
WordHunterWoW_QuestEN[76739] = { title = "Research: Niffen of Zaralek Cavern", description = "", objectives = "" }
WordHunterWoW_QuestEN[76911] = { title = "Research: Drakonid of Waking Shores", description = "", objectives = "" }
WordHunterWoW_QuestEN[76982] = { title = "A Sentinel's Summon", description = "Shandris has sent word that she wishes to meet you in Valdrakken.\n\nSeek her out.", objectives = "Report to Shandris in Valdrakken.", completion = "Thank you for coming, <name>.\n\nI will explain the situation." }
