WordHunterWoW_QuestEN[76989] = { title = "Trashing the Camp", description = "", objectives = "" }
WordHunterWoW_QuestEN[76990] = { title = "Portal Panic", description = "", objectives = "" }
WordHunterWoW_QuestEN[76991] = { title = "Carpe Diem", description = "", objectives = "" }
WordHunterWoW_QuestEN[76992] = { title = "Fickle Judgment", description = "", objectives = "" }
WordHunterWoW_QuestEN[76993] = { title = "Turtle Power", description = "", objectives = "" }
WordHunterWoW_QuestEN[76997] = { title = "Lost in Shadows", description = "Greetings, {name}. I find myself in a dire situation. \n\nSome fresh recruits and I were on patrol in these lands when our torches went out, leaving us utterly lost and disoriented.\n\nI found safety in this house, but most of the recruits fled, confused into the darkness. \n\nWill you help me locate them? I have a spare Patrol Torch. The mere sight of it should rally them to your side.", objectives = "Find and rally 3 Demoralized Recruits using the Patrol Torch.", progress = "Have you found the recruits?", completion = "The time spent with you is much greater training than I could ever provide these recruits. One of them will remain here to aid you further." }
WordHunterWoW_QuestEN[77092] = { title = "Test Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[77093] = { title = "The Shadowflame Axe", description = "The moment you attempted to wield  Fyrakk's axe, Fyr'alath, its flames consumed you. Clearly the weapon's shadowflame was too intense.\n\nPerhaps you should consult an expert on shadowflame and ancient artifacts. Maybe one of the scholars at the Azerothian Archives can deduce a method for handling it safely.", objectives = "Visit the Azerothian Archives to find an expert on Shadowflame", completion = "I say! What do we have here? How curious!\n\nWait a minute..." }
WordHunterWoW_QuestEN[77094] = { title = "Basic Kill Quest [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[77095] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[77096] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[77097] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[77098] = { title = "Getting to Ground", description = "He needs to be healed--now. \n\nWe're too out in the open here. Sundered Flame loyalists could ambush us at any time. \n\nLet's find cover somewhere so we can assess his wounds.\n\nCover me!", objectives = "Get Marithos to safety in the Azure Span.", completion = "You moved Marithos on your own?\n\nThat was very risky.\n\nBut you were right. Marithos is gravely injured, and we do not have much time." }
WordHunterWoW_QuestEN[77099] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[77100] = { title = "Surveying the Cliffside", description = "Nothing like brisk ocean air to get you in the mood to dig!\n\nWe're standing in the rubble of an ancient dragonkin fishing village. These dragonkin were ancestors of the blue dragonkin that live on the island today. Humble as it is, the remote location means it's gone relatively undisturbed by treasure hunters.\n\nIf there's anything left that hasn't fallen into the sea, we'll find it!", objectives = "Speak with Roska to start the dig then excavate artifacts from the cliffside.", completion = "<Roska lets out a low whistle.>\n\nWe got to this bad boy just in time, huh? Another hundred years, and it woulda been fish food!" }
WordHunterWoW_QuestEN[77101] = { title = "Ingredient Quest Template", description = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research.\n\nI had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em!\n\nHelp me wrangle everyone's ideas into one perfect weapon!", objectives = "Help Rocket-Chief Fuselage build the perfect weapon." }
WordHunterWoW_QuestEN[77102] = { title = "Hellfire Hustle", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77103] = { title = "Hellfire Hustle - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77104] = { title = "Hellfire Hustle - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77151] = { title = "The Cache in the Crag", description = "<This barrel is salt-encrusted and buried amongst the rubble but remarkably intact.\n\nIt looks like the sort of mundane cache that villagers would use to store goods, but no one has lived here for thousands of years. Could there still be something inside?\n\nRoska will want to have a look at this!>", objectives = "Speak to Roska to begin carefully excavating the dragonkin cache.", progress = "Nothing like a crag, eh <name>? Never know what you'll find!", completion = "Wow, <name>! Not only is this cache intact, but it's full of something other than seawater!\n\nImagine finding great-great-great grandma's jam recipe that'd been lost for thousands of years. Yep, the locals are gonna love this!" }
WordHunterWoW_QuestEN[77152] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[77153] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[77154] = { title = "A Taste of the Past", description = "Usually, we go to great lengths to avoid busting artifacts open, but I think in this case we'll learn more about the past from what's inside than just staring at a sealed barrel.\n\nThat said, there's someone we should get permission from first. It's her history, after all. In fact, I think she's the only person still around who might have a personal stake in this find.\n\nI'll see to getting this up the cliff. Ask if Atrenosh Hailstone wants to watch us crack 'er open, eh?", objectives = "Find Atrenosh Hailstone and see if she would like to open the cache with you.", progress = "<Roska looks proud of your hard work.>", completion = "That's what this is all about, eh?\n\nConnecting folks with their pasts, making them feel like they're a part of something. It's easier to know where you're going when you know where you came from." }
WordHunterWoW_QuestEN[77155] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across the Dragon Isles to cover the tab!" }
WordHunterWoW_QuestEN[77156] = { title = "Botanical Redistribution", description = "", objectives = "" }
WordHunterWoW_QuestEN[77159] = { title = "No Mushroom for Error", description = "", objectives = "" }
WordHunterWoW_QuestEN[77163] = { title = "Seeing Reason", description = "They seem to know that Sarkareth is gone, but because their missions were so far from Zaralek Cavern, it looks like they never heard how he met his demise. \n\nWe should talk to them. Maybe if they knew why so many of their brethren now follow me they would become Ebon Scales again. Or not...\n\n<Emberthal sighs.>\n\nThis could backfire catastrophically, but I feel like we must try. Quartermaster Doros seems to be in command here. Go and speak to him, {name}. I do not think he would listen to me...", objectives = "Confront Quartermaster Doros in the Lonely Falls.", progress = "Find Quartermaster Doros. If you can talk to him, we might be able to avoid a conflict.", completion = "That... did not go as I had hoped." }
WordHunterWoW_QuestEN[77164] = { title = "Scarab Test One", description = "", objectives = "" }
WordHunterWoW_QuestEN[77165] = { title = "A Secretive Contact", description = "", objectives = "Hey there, I'm a reporter for the Eye of Azeroth.\n\nI'm investigating some strange activity in Valdrakken. Want to help?\n\nI've got a source, but they'll only speak to someone wearing a 'Thinking Cap'. It's supposed to focus thoughts or some such. Anyway, I made a list of the components needed and who you can get them from. \n\nTrack them down, then we'll talk more." }
WordHunterWoW_QuestEN[77166] = { title = "A Practical Test", description = "Now that you know how to use the device, we will put your skills to the test.\n\nI have attuned your Technoscryers to a valuable item hidden somewhere on this island. Provided you can find it, we will use it to view a scene from the past and deduce how it got there.\n\nIt is time for science! Put... the goggles... on! Resume your scrying!", objectives = "Use the Technoscryers to find the hidden object.", progress = "Have you found that hidden object, <name>?", completion = "Eureka! Success! \n\nQuickly, hand the Technoscryers back to me. We will readjust them for the next test." }
WordHunterWoW_QuestEN[77169] = { title = "Coilfang Caper", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77170] = { title = "Coilfang Caper - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77171] = { title = "Coilfang Caper - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77176] = { title = "I Can See Through Time!", description = "Okay, the Technoscryers should be calibrated. I have made the same adjustments to my own pair, so we can view the same phenomena.\n\nAre you ready? Put... them on... again! This time, we will use the Observation mode.", objectives = "Observe events from the past.", progress = "I wonder what we will find?", completion = "Oh, my. Ha ha ha ha ha! \n\nI... conveniently forgot about that. You are not going to tell Nirobin about this, are you?\n\nAcademic rivalry takes many forms. It is all perfectly innocent, I assure you!" }
WordHunterWoW_QuestEN[77178] = { title = "Tactical Withdrawal", description = "We have stopped this attack on the barrier, but Fyrakk will find a way through.\n\n{name}, we need to return to Alexstrasza and Merithra and tell them his plans for the Wellspring.\n\nReturn as soon as possible. It is more urgent than ever to stop Fyrakk.", objectives = "Return to Alexstrasza in the Central Encampment.", completion = "So Fyrakk is after the Wellspring." }
WordHunterWoW_QuestEN[77191] = { title = "Handling It", description = "If you want to wield Fyr'alath safely, you'll need to modify the weapon's haft with three components.\n\nFirst, you'll need a fireproof hide that can handle intense heat. Next, acquire enchanted vellum that can contain the weapon's volatile magic. Finally, a scribe must apply the proper runes, so you can bind the first two materials to the axe.\n\nMy journal over there includes a few recommendations of crafters who can help you. You might also know a few!", objectives = "Obtain a Symbiotic Glowspore Grip, a Rune of Shadowbinding, and a Concentrated Sophic Vellum.", progress = "Please collect the necessary materials quickly. I'm excited to begin.", completion = "Excellent! I knew my instructions would prove sufficient!\n\nOh, and congratulations to you, as well. I commend your diligence." }
WordHunterWoW_QuestEN[77192] = { title = "An Axe Tempered", description = "Exemplary. Some of the components can be wrapped and attached by hand, but for the last step, you'll need a powerful forge to unify all three in flame.\n\nI've been speaking to Wrathion. He can direct you to a suitable forge in the Obsidian Citadel. I'll meet you both there! I can't wait to see what happens as a result of my ingenious plan!", objectives = "Head to the Obsidian Citadel and ask the smith to forge the handle onto the axe.", progress = "We need to attach the modified handle to the axe head. That's more perilous than it sounds...", completion = "Let's prove you can withstand your weapon's corruption.\n\nThe ritual awaits. I can lead you into Aberrus. Are you ready to go?" }
WordHunterWoW_QuestEN[77193] = { title = "The Power of Temptation", description = "Just to be clear: if the axe defeats you, I will be obligated to step in. \n\nBut that's not going to happen, is it? You're not going to be corrupted by shadowflame. You won't devolve into a monstrous, murderous shadow of your former self. I'm not going to have to... intervene.\n\nAs long as we're clear on this, no one is going to have to kill anyone. All right, let's get this done.", objectives = "Talk to Wrathion to travel to Aberrus, and complete the scenario \"A Hero's Resolve.\"", progress = "What an intimidating axe!", completion = "We now have something in common: we both share the burden of making something positive out of my father's legacy.\n\nLucky you. Misery loves company. Wield that axe wisely." }
WordHunterWoW_QuestEN[77194] = { title = "Free Knot!", description = "", objectives = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it. I think any of the ogres might have it, but I'm not sure if any specific ones do. Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?! Is that it there??!", progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it. I think any of the ogres might have it, but I'm not sure if any specific ones do. Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?! Is that it there??!", completion = "Oh, thank you for freeing me! You - ranked number one. Everyone else - ranked number two or lower.\n\nI knew my life was destined for more than just being an appetizer to some ogre!" }
WordHunterWoW_QuestEN[77195] = { title = "A Dragon's Eye View", description = "I believe I know just the location for the Netherwing to roost.\n\nIt has a wonderful view and is quite secluded.\n\nI'd like to show our guest some of the sights of Valdrakken before we go. Meet you there?", objectives = "Travel to the cave above the Sand-Lost Sanctum in Thaldraszus.", progress = "Really, the view from the cave is quite remarkable.", completion = "There seem to be far more spiders here than the last time I visited.\n\nBut it seems as if Vyranoth has a plan of action." }
WordHunterWoW_QuestEN[77197] = { title = "A Whelping Hand", description = "Well done, {name}.\n\nNow we must ensure the whelps of the netherwing have the best opportunities to grow and flourish. \n\nLet us speak to Mother Elion. I know she would relish the opportunity to care for the young of a new flight. \n\nCan you meet us at the Ruby Lifeshrine?", objectives = "Meet Mother Elion at the Ruby Lifeshrine in the Waking Shores.", completion = "Wrathion says there are new whelps on the way?\n\nOf a new flight? Are you certain this is not a joke?\n\nVery well. Let us get started." }
WordHunterWoW_QuestEN[77198] = { title = "Home in Time for Tea", description = "I must admit, I did not expect to be altering the future of my flight when I arrived. But it feels as though we belong here. Perhaps this is the call they spoke of...\n\nRegardless, I am looking forward to some rest. \n\nWrathion mentioned retiring to the Roasted Ram Inn. \n\nCan you meet us there?", objectives = "Meet Wrathion, Mordenaku, and Vyranoth in the Roasted Ram Inn in Valdrakken.", progress = "I am looking forward to some rest.", completion = "Thanks to you, my flight's safety and future has been secured.\n\nTraveling from Outland to Azeroth has been overwhelming, but in the best of ways.\n\nThe netherwing look forward to exploring this world." }
WordHunterWoW_QuestEN[77200] = { title = "Offerings for the Well", description = "Amirdrassil has been ushered into this world by the denizens of the Dream. Now we must ensure its roots are bathed in the waters of Elune by creating a new moonwell.\n\nSo many of my people have brought us to this moment. Each should have a part in this dedication. \n\nGo, speak to the kaldorei gathered here, and see if they have offerings for the ceremony.", objectives = "Gather offerings from night elves in the Central Encampment.", progress = "Have you collected all the offerings for the ceremony?", completion = "Every kaldorei understands the grief and elation of a moment such as this. The pain we have endured and the hope we have for the future.\n\nThese offerings are profound and appreciated." }
WordHunterWoW_QuestEN[77201] = { title = "A Personal Offering", description = "{name}. You have done so much for our people. I would have you participate in this ceremony and provide an offering of your own, should you wish it.\n\nLet me know what it is that you would like to put forward and it will be done.", objectives = "Speak with Tyrande Whisperwind in Central Encampment to choose an offering.", progress = "Are you certain of your offering?", completion = "An admirable choice. May Elune light your path, <name>." }
WordHunterWoW_QuestEN[77202] = { title = "The Preservationists", description = "Welcome, adventurer. Have you heard the news?\n\nThere's been a rash of artifact thefts as rumors of treasures and secret locations are being exposed.\n\nIf you'd like to learn more, seek out Preservationist Kathos. Your skills at deciphering secrets might help reveal who's behind this chaos.", objectives = "Speak with Preservationist Kathos at the Roasted Ram in Valdrakken.", completion = "A new recruit? Splendid! There's much work to be done, and many secrets to uncover.\n\nReady to get started?" }
WordHunterWoW_QuestEN[77203] = { title = "Preserving Rarities", description = "Let's unravel a secret! Prepare your mind for puzzles...\n\nSpeak to me again when you're ready to start down the path of the preservationists.", objectives = "Speak with Preservationist Kathos to begin a secret, then let her know when it's solved.", progress = "That mystery isn't going to solve itself!", completion = "You unraveled the \"mystery\" and preserved the artifact!\n\nA good preservationist is always looking to get better at preserving artifacts. If you find anything new, we'll figure out how we can employ it in the field." }
WordHunterWoW_QuestEN[77205] = { title = "Blade's Edge Brawl", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77206] = { title = "Blade's Edge Brawl - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77207] = { title = "Blade's Edge Brawl - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77208] = { title = "Barreling Down", description = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the Valdrakken folk would hurry up and bring the rest of the barrels down here.\n\nWe've shipped our Brewfest brews here so they can celebrate--and wouldn't ye know it, they've already started their own traditions! Rolling barrels through the city? That's no way to treat a good brew!\n\nMind lending a hand to bring those barrels down here? And try not to break 'em!", objectives = "Deliver barrels to the Artisan's Market in Valdrakken.", progress = "Careful with the barrels! Ye shouldn't jostle a good ale.", completion = "Glad to see that delivery in one piece!" }
WordHunterWoW_QuestEN[77209] = { title = "Seed Legacy", description = "For years I worked with Denalan in Teldrassil. His research will be the foundation of how we will restore these seeds.\n\nThe first step: we must coax them back to life, allowing them to grow into vibrant blossoming plants. I have located suitable patches of soil where the plants can take root and grow, revealing their true potential. \n\nWe will plant one small, one plump, and one gigantic seed to observe how the quality of the seed can sprout different growth.", objectives = "Plant a seed at each of the Dreamsoil patches.", progress = "Have you planted the seeds?", completion = "Denalan would be proud to see his work continued by one such as you!" }
WordHunterWoW_QuestEN[77231] = { title = "Technoscrying 101", description = "Through a near-perfect blend of technology and arcane enchantment, I have developed a way to analyze the psychometric properties of objects. Wearing these goggles, you can see the data as dynamic simulacra!\n\nSimple, yes? I call it... the Psychometric Visuo-Auditory Discrete Waveform Analysis and Viewing Device! For the layperson, we're calling them \"Technoscryers.\" Trademark and patent pending.\n\nHere, try them on!", objectives = "Learn to use the Technoscryers.", progress = "I have given you the Technoscryers. Please! Put them on!", completion = "Well done! \n\nI admit, the bar for putting on a pair of goggles is super low, but still! You did it!" }
WordHunterWoW_QuestEN[77236] = { title = "When Time Needs Mending", description = "We need to close rifts. We need to fix timeways. Honestly, we need all the help we can get.\n\nThere's always more work to do. Are you ready for the next challenge?", objectives = "Close a Time Rift by defeating a Fractured Causality.", progress = "Come now, these rifts aren't going to close themselves.", completion = "Good work out there. \n\nTake a moment and catch your breath, but keep your weapons close at hand. It's been one surprise after another.\n\nFortunately, all this hard work is worth it. Each time rift we close gets us one step closer to fixing the timeways." }
WordHunterWoW_QuestEN[77237] = { title = "Unfinished Thinking Cap", description = "<Take the Unfinished Thinking Cap to Fangli Hoot near the Barber Shop in Valdrakken.>", objectives = "Take the Unfinished Thinking Cap to Fangli Hoot in Valdrakken.", progress = "<Fangli looks at you, but doesn't speak.>", completion = "<Fangli points to your head, then to hers. She gestures for your Unfinished Thinking Cap.\n\nShe uses an arclight spanner to adjust some wires and lenses, then flips a switch. The Thinking Cap whirs to life.\n\nFangli hands it back to you.>" }
WordHunterWoW_QuestEN[77238] = { title = "Telaar Tear", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77239] = { title = "Telaar Tear - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77240] = { title = "Telaar Tear - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77241] = { title = "A Foreseeable Friendship", description = "Thank you for your timely intervention. You've been a valuable ally in our campaign.", objectives = "I expect great things from you. In fact, I know you have greatness in you.\n\nKeep up the good work." }
WordHunterWoW_QuestEN[77242] = { title = "Many Invader's Scourgestones", description = "", objectives = "An Invader's Scourgestone was the insignia of the Scourge's elite troops. These were sometimes found on the stronger of the troops positioned in Stratholme and Scholomance.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", progress = "An Invader's Scourgestone was the insignia of the Scourge's elite troops. These were sometimes found on the stronger of the troops positioned in Stratholme and Scholomance.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", completion = "More and more scourgestones pile up by the day, <name>, from yourself and a growing number of other adventurers.\n\nFortunately, none of our soldiers have mysteriously disappeared nor have I heard more bloodcurdling screams than what is normal for this region.\n\nI would rather not ask questions. Here is your reward." }
WordHunterWoW_QuestEN[77243] = { title = "Many Corruptor's Scourgestones", description = "", objectives = "A Corruptor's Scourgestone was the insignia of the Scourge's overlords. Powerful beings that once held a position of authority over the Scourge always possessed one.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", progress = "A Corruptor's Scourgestone was the insignia of the Scourge's overlords. Powerful beings that once held a position of authority over the Scourge always possessed one.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", completion = "More and more scourgestones pile up by the day, <name>, from yourself and a growing number of other adventurers.\n\nFortunately, none of our soldiers have mysteriously disappeared nor have I heard more bloodcurdling screams than what is normal for this region.\n\nI would rather not ask questions. Here is your reward." }
WordHunterWoW_QuestEN[77244] = { title = "Many Corruptor's Scourgestones", description = "", objectives = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nCorruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", progress = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nCorruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, <name>! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
WordHunterWoW_QuestEN[77245] = { title = "Many Invader's Scourgestones", description = "", objectives = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nInvader's Scourgestones are rather common, so I ask you bring a decent haul.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", progress = "I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nInvader's Scourgestones are rather common, so I ask you bring a decent haul.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, <name>! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
WordHunterWoW_QuestEN[77248] = { title = "A Recognition of Skill", description = "Impressive work. With champions like you on our side, the odds are in our favor.", objectives = "Your accomplishments are impressive. \n\nPlease take this as a token of our esteem. Don our colors as you continue mending the timeways." }
WordHunterWoW_QuestEN[77249] = { title = "One of Us", description = "{name}, you've returned. I trust you have everything well in hand.", objectives = "Perhaps you can now see the big picture. Reckless time travel can have consequences, and the damage to the timeways is extensive. \n\nAs you can see, time is a tangled skein. You've untangled many threads, and we all benefit from your diligence. You've proven you're a hero, not just on this world but on many others." }
WordHunterWoW_QuestEN[77250] = { title = "Realized Potential", description = "I salute you, {name}. Would you care to chat?", objectives = "I've heard the inhabitants of other timeways are singing your praises. You're not just a hero in this world. Your name is spoken with reverence in other dimensions.\n\nAre you sure you aren't a bronze dragon?\n\nI jest. Thank you <name>. We couldn't do this without you." }
WordHunterWoW_QuestEN[77251] = { title = "Shaping the Dreamsurge", description = "The Emerald Dream is thrumming with energies not felt in ages. \n\nSome of that energy is even slipping through the barrier between the dream and Azeroth, coalescing into a glimmering, pollen-like powder. \n\nGather as much as you can. This is not like any event we have seen before!", objectives = "Gather Dreamsurge Coalescence from around the Dreamsurge.", progress = "The winds sparkle with motes of dreaming essence, spreading it over the land.", completion = "Thank you, <name>. This will aid us greatly in understanding what marvels we are witnessing." }
WordHunterWoW_QuestEN[77254] = { title = "Aiding the Accord: Time Rift", description = "The Bronze Dragonflight have long labored in secret, dealing with temporal anomalies nearly as quickly as they're able to manifest. It would appear, however, that the anomalies have gotten a bit too big as of late.\n\nThat's where you come in.\n\nYou can find Soridormi leading an effort against a particularly nasty set of Time Rifts just to the east of Valdrakken. Aid her in whatever way she deems necessary.", objectives = "Travel to the Tyrhold Reservoir and assist Soridormi in dispelling a Time Rift. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "Do you bring news of your success?", completion = "The work of the Bronze is never complete, is it?\n\nPlease accept this humble gift, along with our gratitude." }
WordHunterWoW_QuestEN[77260] = { title = "Razorthorn Rise Rush", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77261] = { title = "Razorthorn Rise Rush - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77262] = { title = "Razorthorn Rise Rush - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77263] = { title = "The Torch of Pyrreth", description = "Let's begin with a simple test.\n\nI have hidden an artifact somewhere in the Ruby Enclave.\n\nIf you have the torch out, it should illuminate when you get close to the target. And if my theory is correct, it should interact with a lock I put on the artifact.\n\nBring me back what's inside. Got it?", objectives = "Use the Torch of Opening to unlock Kathos' artifact, hidden somewhere in The Ruby Enclave.", progress = "Return when you have retrieved what I ask.", completion = "Ah yes, my field glasses. I must have set them inside it by accident.\n\nI couldn't figure out how to open it again. But you could!\n\nThank you, <name>." }
WordHunterWoW_QuestEN[77264] = { title = "Auchindoun Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77265] = { title = "Auchindoun Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77266] = { title = "Auchindoun Coaster - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77267] = { title = "Excavation 101", description = "So, you want to learn how to excavate artifacts? You came to the right orc!\n\nTurns out being able to shape the earth is useful when you're trying to get stuff out of the ground. And given how much the elements affect our work, it helps having an elemental to lend a hand.\n\nBut you don't have to be a shaman to master excavation. I've got the elements covered. I'll just walk you through the detail work.", objectives = "Meet with Roska outside to learn about excavation.", progress = "What do you think? Having fun yet?", completion = "That's a find, all right! Look at you. You're a natural at this!" }
WordHunterWoW_QuestEN[77268] = { title = "Hands-On Experience", description = "Great job on that small find! Now, are you ready for something big?\n\nMore often than not, shaking up the small stuff will shake up something even BIGGER just below the surface. Another little rumble, and we'll have a major find on our hands, I can feel it.\n\nA major find works almost the same as the smaller ones with a couple extra steps. Why don't you tackle this one too? It'll be good practice for ya.\n\nDon't worry! I can guide you through it.", objectives = "Unearth the major find, then speak to Roska to begin excavating it.", progress = "Rare to find big stuff like that up here! Zenata might be up to her tricks again.", completion = "Look at you, master excavator! I reckon you're about ready to get into the field.\n\nSee you out in the dirt!" }
WordHunterWoW_QuestEN[77276] = { title = "An Inside Job?", description = "Fangli Hoot says they have a theory on who might be stealing the artifacts.\n\nSeek her out again near the Barber Shop.", objectives = "Speak with Fangli Hoot near the Valdrakken Barber Shop.", completion = "I have a theory. What if this so-called \"Preservationist\" is stealing the artifacts, then having you return fakes instead?\n\nI'll give you the location of a box where the Preservationist is keeping artifacts. Grab one, then follow these coordinates to an appraiser who can verify if what you find is legit." }
WordHunterWoW_QuestEN[77277] = { title = "Preservationist Cleared", description = "Ya better return the item before the Preservationist notices it's missing.\n\nThen let Fangli know that her theory didn't pan out.", objectives = "Return the Burial Banner to the Preservationist's Locker in the Roasted Ram.", progress = "What did you discover?", completion = "Really? I was pretty sure they were the perpetrator... \n\nOh well, I've got other leads to follow. I'll let you know when I'm ready to move on 'em. \n\nI'll take that key back, too." }
WordHunterWoW_QuestEN[77278] = { title = "Tempest Keep Sweep", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77279] = { title = "Tempest Keep Sweep - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77280] = { title = "Tempest Keep Sweep - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77281] = { title = "Securing an Artifact", description = "", objectives = "One of the Preservationist's colleagues left this note.  \n\nIt says the Primalists are threatening the Life-Binder Conservatory and an important artifact is at risk. I need you to locate and secure it before the looters do. \n\nThe coordinates on the note should work with that funny looking \"Thinking Cap\" you have." }
WordHunterWoW_QuestEN[77282] = { title = "Artifact Secured", description = "<Returning the torch to Preservationist Kathos might give insight into how it was used.>", objectives = "Return the Torch of Pyrreth to Preservationist Kathos in Valdrakken.", progress = "Welcome back adventurer, have you found something?", completion = "You found the Torch of Pyrreth! There are stories about this in the archives. You say the Preservationists sent a dispatch on it? \n\nIt's said that the torch can enable ancient devices and illuminates when near other artifacts. I have a way for us to test it out.\n\nHere, you take the torch and keep it safe." }
WordHunterWoW_QuestEN[77283] = { title = "A Multi-Front Battle", description = "The kaldorei have set up a temporary base beneath the boughs of Amirdrassil.\n\nWith hope and hard work, this encampment will become permanent when the tree enters our world. \n\nFeel free to acquaint yourself with the provisions available. Then return to me.", objectives = "Meet Saelienne in the Central Encampment.", progress = "Have you found what you needed here in camp?", completion = "Tyrande has gone to investigate the Druids of the Flame, learn more about their purpose in the Emerald Dream, and identify their leaders.\n\nHow could night elves and Dream denizens turn to the flame?\n\nI am confident that you and Tyrande can find the answer." }
WordHunterWoW_QuestEN[77284] = { title = "A Chilling Ascent", description = "", objectives = "There's a clerk at General Supplies who's been one of my sources for juicy rumors.\n\nThey told me about an expedition to Vakthros in the Azure Span. Sounds like someone was looking for that torch you found.\n\nThe clerk saw their map and wrote down some coordinates. Hopefully they'll get you close." }
WordHunterWoW_QuestEN[77286] = { title = "A Knowledgeable Descent", description = "<The rubbing is in an ancient language. Perhaps Bobby Carlisle can get the text translated.>", objectives = "Take the Unveiled Tablet Rubbing to Bobby Carlisle in Valdrakken.", progress = "Did you find anything?", completion = "You found someone trapped up there? And others were dead? Good thing you had that torch! \n\n<Bobby peers at the etching.>\n\nI don't recognize this text. I'll show it to Preservationist Kathos. Hopefully whatever it says can help us figure out what this group is after." }
WordHunterWoW_QuestEN[77303] = { title = "Idol Searching", description = "", objectives = "Another note from Kathos' order just arrived.\n\nIt says that a Maruuk artifact hidden within one of the burial mounds of the Eternal Kurgans is at risk. The note mentions ancient incense concealing the artifact from outsiders.\n\nThe rest of the info is in this note. Best of luck, adventurer!" }
WordHunterWoW_QuestEN[77304] = { title = "An Idol in Hand", description = "<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples.\n\nPreservationist Kathos would surely be interested in this.>", objectives = "Return the Idol of Ohn'ahra to Preservationist Kathos in Valdrakken.", progress = "What have you found?", completion = "You found the Idol of Ohn'ahra! I suppose I shouldn't be surprised.\n\nWe need to get artifacts like this back to their rightful places. But if my superiors are right, we can't risk letting them fall into the wrong hands. \n\nLet me examine the idol." }
WordHunterWoW_QuestEN[77305] = { title = "Out of the Sands", description = "<The Time-Lost fragments are now joined to form a stone tablet, but many of its inscriptions are worn and incomplete.\n\nPreservationist Kathos will want to see this.>", objectives = "Return the Incomplete Tablet to Preservationist Kathos.", progress = "XENO! How was your luck in the Shifting Sands? Did you find the tablet fragments?", completion = "Ah yes, I can see a portion of the tablet's inscriptions. Many, but not quite all...\n\nI'll pore over these symbols. With luck, I may complete the puzzle and tease out its meaning." }
WordHunterWoW_QuestEN[77310] = { title = "Memory of the Dreamer", description = "In the Dream, memories can live on in unusual ways. Memories are not always linear. And memories that are not of your own can become yours.\n\nPerhaps you were drawn to this place by the presence of the once-Dreamer. Or perhaps you were drawn to this place because of my great friend. Come, won't you see?\n\nRest here and let the magic of the Dream wash over you.", objectives = "Rest at the Eye of Ysera.", completion = "Good that you are here, <name>. Perhaps you can lend your assistance?" }
WordHunterWoW_QuestEN[77311] = { title = "Healing Helper", description = "Gracus sent word for Ysera to come and see him. We arrived and found him in a dire condition. \n\nOur efforts to heal him so far have proved fruitless. But now that you are here, you can assist.\n\nGracus is of the Dream. Perhaps infusing his roots with something grown here will be the final thing we need to restore him.", objectives = "Use the Root Restoration Fruit to help heal Gracus.", progress = "Gracus' condition is dire. We must do what we can to try to help.", completion = "I was so certain we could help.\n\nYsera seems to be sensing something here that I cannot. After all she has been through, it seems her magic has indeed changed beyond my recognition." }
WordHunterWoW_QuestEN[77312] = { title = "Nature Persists", description = "Admittedly, I do not know what to do next.\n\nIf he is to rest here... flowers would be lovely.\n\nThe podlings in this area have been hiding among the flowers. Retrieve seeds from them, Champion, and I will make them bloom.\n\nI think Gracus will like the flowers.", objectives = "Collect 6 Sprouted Seedlings from Sneaky Podlings.", progress = "There must be something more that we...\n\nNo. Ysera seems certain.", completion = "Encouraging new growth on an occasion such as this feels right." }
WordHunterWoW_QuestEN[77313] = { title = "A Solemn Summons", description = "It is as I feared. It is Gracus' time. \n\nHealing him would never have worked. The world beyond already calls to him. \n\nAlthough he has such peace, those that care for him will still grieve. He will still be dearly missed. \n\nNot everyone is granted a chance to say goodbye. \n\nWe must ensure that in this case, they are.", objectives = "Inform Gracus' loved ones.", progress = "I am grateful we can give them this opportunity to say goodbye.", completion = "There is a sense of peace in this place.\n\nGracus summoned me here for a reason. He knew." }
WordHunterWoW_QuestEN[77314] = { title = "Requiem in a Dream", description = "As one life ends so too will a life begin. \n\nWe must remind those that love Gracus of this, {name}. \n\nPlant seeds around Gracus. My sister can handle the rest. \n\nThis place will not only represent an end but also a beginning of new life.", objectives = "Plant 6 flowers around Gracus.", progress = "These flowers will bloom around Gracus and serve as a reminder of all he helped to grow during his life.", completion = "Those memories... Gracus suffers. We should aid him." }
WordHunterWoW_QuestEN[77315] = { title = "Ancient Memories", description = "Those dark memories cannot be allowed to fester in the Dream.\n\nUnleashing them was necessary. Gracus needed to let go. But if they linger, they may become malevolent.\n\nDefeat the memory that haunts him most so that Gracus can slumber at last.", objectives = "Kill the Lingering Torment.", progress = "Грак не может в полной мере обрести покой, пока его терзают воспоминания.", completion = "Thank you, <name>. Gracus will be at peace now.\n\nAs will those who cared for him, it seems. It is not often people get a second chance to say goodbye." }
WordHunterWoW_QuestEN[77316] = { title = "Trouble at the Tree", description = "{name}! Merithra needs your help. \n\nSome nasty trickster spriggans followed us into the Dream and now they're causing all sorts of havoc!\n\nLike the most important thing of all, stealing top secret super important supplies. \n\nIt's urgent you stop them and get the supplies back.", objectives = "Retrieve 6 Very Important Tree Supplies from Spriggans.", progress = "If we don't get those supplies back from those pesky spriggans, we'll be so behind schedule!", completion = "What a relief!\n\nNow that we got those very important supplies back, we can get back to work around here." }
WordHunterWoW_QuestEN[77317] = { title = "Hatted Hibernation", description = "I'll let you in on a secret, these crates? They're prank supplies! \n\nPeople are so serious around here. What's better than a little prank to lift everyone's spirits?\n\nYou could put some of these fun hats on some of the sleeping druids because what's more fun than a surprise hat?\n\nBe careful though, their connection to the dream could make anything happen!", objectives = "Put 6 silly hats on Dreaming Druids.", progress = "Napping in the Dream... I wonder what they're dreaming about!", completion = "I'm impressed. I thought I was pranking you too!\n\nBut looks like you're better at this than I expected... \n\nMaybe it's time for a real challenge." }
WordHunterWoW_QuestEN[77318] = { title = "Merithra Says", description = "Some druids are volunteering to help tend to the tree and set up camp.  \n\nBut they're so sad! \n\n<Lady Moonberry grows a mischievous grin.> \n\nWe have to give them a reason to smile. You can give them some orders that remind them to have fun. \n\nBut there's no way they'll take orders from you. \n\nThat's why I got this costume for you. With this and a little spell they'll for sure listen to you!", objectives = "Give instructions to 5 druids while disguised as Merithra.", progress = "You're clearly a master prankster but you'll have to be a master actor as well.  \n\nA costume and a spell can only do so much.", completion = "Your performance as Merithra was unmatched.\n\n<Lady Moonberry bursts into laughter.> \n\nI can hardly tell you two apart!" }
WordHunterWoW_QuestEN[77322] = { title = "Shattrath City Sashay", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77323] = { title = "Shattrath City Sashay - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77324] = { title = "Shattrath City Sashay - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77325] = { title = "To the Archives!", description = "Are you a scholar, historian, or a high-minded intellectual? Do you enjoy heavy, mindless labor in exchange for gold?\n\nThen take hold of your future, and join the newly budding ranks of the Azerothian Archives!*\n\n<Your eyes move to the fine print near the parchment's edge.>\n\n*Temporary offices are located at the Algeth'ar Academy in northern Thaldraszus.", objectives = "Speak with Lead Archivist Eadweard Dalyngrigge at Algeth'ar Academy.", completion = "Finally! The delivery <class> is here with our meal orders!\n\nOh... you're here to join the Archives? Of course! My mistake.\n\nBut if you do see a delivery person around, please point them my way, would you?" }
WordHunterWoW_QuestEN[77327] = { title = "Nirobin and the Office", description = "Perhaps there is more to investigate, but I need time to go over our findings here first.\n\nOur colleague, Nirobin, the one arcane projecting himself into the headquarters, should be ready for your assistance by now. He's got his own office at the Academy in Thaldraszus that he tends to squirrel himself away in.\n\nI'm positive he'll be there... Mostly because he never leaves it.", objectives = "Speak with Nirobin at his office in Thaldraszus.", completion = "Are you the new recruit? \n\nSince you're late, I simply assumed you had been swallowed up by the outside... like I am in my ever-reoccurring nightmares.\n\nIt's nice to meet you in person, I suppose." }
WordHunterWoW_QuestEN[77328] = { title = "Back to Headquarters!", description = "Eadweard called for your return to the main office after I'd finished with you... er, this experiment, I mean.\n\nI'm sure it has to do with pomp, circumstance, reward, and what have you. If any of that entices you, then best hurry before his bag of goodies runs dry to all the other recent recruits.", objectives = "Meet with Eadweard Dalyngrigge at Algeth'ar Academy in Thaldraszus.", completion = "Good show, <name>!\n\nI had heard high praise of you from Roska and Zenata, but hearing from Nirobin as well... Well! You must be truly exceptional. He has, shall we say, discerning taste!\n\nBut enough about that. You've done more than enough to consider yourself a premier Azerothian Archivist.\n\nWelcome to the team!" }
WordHunterWoW_QuestEN[77329] = { title = "Auspicious Gathering", description = "As you know, Amirdrassil is no ordinary tree. Tyrande Whisperwind and the rest of the kaldorei have been preparing to properly welcome it with a ceremony of their own, and establish a new moonwell. \n\nI am certain that Tyrande would want you there for the dedication.\n\nLet us join them at the Central Encampment.", objectives = "Speak with Tyrande Whisperwind in the Central Encampment.", completion = "Amirdrassil is everything we had hoped for. Let us properly honor its arrival." }
WordHunterWoW_QuestEN[77331] = { title = "Graduation Day", description = "You've turned out to be quite a fine member of our high-skilled crew of rag tags and diggers of dirt.\n\nBetween the sites you've broken ground on with Roska, Zenata, and Nirobin, as well as the larger one in Traitor's Rest, the varied histories collected by these Dragon Isles have never been more ripe for the harvest.\n\nThere will always be work and companionship here when you desire it. We hope you'll join us on other continents as well.\n\n...When we receive appropriate funding, that is.", objectives = "Receive congratulations from your Azerothian Archivist peers.", progress = "Worry not. I've already written to our benefactors of your efforts.", completion = "To you, <name>! \n\nTo your supportive efforts, to your spirit of discovery, and to your care for history!\n\nMay all those with joyfully voracious appetites for learning find homes and friends like these!" }
WordHunterWoW_QuestEN[77339] = { title = "Data Recovery", description = "After a lot of rigorous training, the time has come! Travard believes the Tyr's Guard is ready to recover the disc of Tyr from the Nighthold. \n\nMeet us at Tyr's Rest, the new Tyr's Guard headquarters. It's just south of Tyrhold. \n\nWe will finally make Tyr whole again!", objectives = "Meet Travard at the Tyr's Guard headquarters.", completion = "There you are, <name>. Ready to finally get that disc?" }
WordHunterWoW_QuestEN[77340] = { title = "Infiltrating the Nighthold", description = "The information from our beacons suggests that Elisande has locked the disc away in Astromancer's Rise.\n\nIt is a place of learning, and the inside will have minimal protection. I have opened a portal where you and the Tyr's Guard will have the least resistance... except for Elisande and whatever guards are under her employ.\n\nAll of you are on your own once you get there, so try not to muck it up.", objectives = "Retrieve the Disc of Tyr from Elisande in the Nighthold.", progress = "I wonder what Tyr is like? I bet he's super nice!", completion = "Glad everyone made it, <name>! We have the disc, the Silver Scale, and Tyr is reforged. Amazing, let's bring Tyr back!" }
WordHunterWoW_QuestEN[77341] = { title = "Logotyrapy", description = "Dear {name},\n\nIt seems wrong to say this of someone as mighty as Tyr, but I am worried about him. When he arrived at Tyr's Rest, he spent many days talking with us. We all asked him many questions, learning about the titans, ancient history, and his philosophy.\n\nBut recently, Tyr has been speaking less, and the answers he does give are shorter and some have an edge to them.\n\nI'm not sure what's wrong, but something is different. Will you come speak with him?\n\nFor Tyr,\nValunei", objectives = "Speak with Tyr at Tyr's Rest.", progress = "Tyr seems restless. Perhaps you could talk to him, <name>?", completion = "I hope, <name>, that we can find the greater purpose for which we've been reforged. For both Tyr, and the Tyr's Guard.\n\nPerhaps that search is the next step of our journey." }
WordHunterWoW_QuestEN[77342] = { title = "Disc Delivery", description = "You have recovered the disc? \n\nGood. At last, we can awake Tyr.\n\nThe disc must be placed in the console so it can attune to the Silver Scale and pass on to Tyr.\n\nI believe you should do the honors, {name}.", objectives = "Insert the Disc of Tyr into the titan console.", progress = "Did you place the disc in the titan console?", completion = "Tyr is with us once more. I can hardly believe it. Thank you, <name>." }
WordHunterWoW_QuestEN[77343] = { title = "A Tyrful Reunion", description = "This is incredible, seeing our friend back after so many thousands of years. So much has happened since we last spoke.\n\nThe world has changed. Our loss of Tyr was before even the Sundering. But there will be time to discuss all those things later. For now, it's simply good to be with our friend. Stay with us, will you, {name}, while we reconnect?", objectives = "Listen to the Aspects' conversation with Tyr.", progress = "One moment, <name>--I want to hear what Tyr and the aspects are saying!", completion = "I almost can't believe we've arrived at this moment, <name>. So many years spent serving the Tyr's Guard, seeing those watching Tyr's tomb die out--and now both he and the Guard are alive again!" }
WordHunterWoW_QuestEN[77344] = { title = "Time to Process", description = "Tyr is back after thousands of years. I don't even know how many thousands. His world has changed more than we can even imagine. He's going to have many questions and need answers. \n\nMeanwhile, there's nothing any of the Tyr's Guard would rather do than talk with Tyr. Tyr's Rest seems like the perfect place to give him time, answer questions, and process those answers. Would you ask him to join us there?", objectives = "Invite Tyr to join the Tyr's Guard at Tyr's Rest.", progress = "We certainly live in interesting times, <name>...", completion = "It is so good to be able to talk with Tyr directly. We have so much to tell him, and I know we all want to ask him questions. \n\nThank you for making this possible, <name>!" }
WordHunterWoW_QuestEN[77345] = { title = "The Need For Higher Velocities", description = "Sometimes you'll need to travel longer distances.\n\nIf you don't need to travel up and over any obstacles using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky.\n\nFollow the rings again to your destination and use Surge Forward when prompted to maintain your speed.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Fly through the rings and land in the target area.", progress = "Well done, <name>.", completion = "Well done. The rest is now a matter of practice." }
WordHunterWoW_QuestEN[77346] = { title = "Shadowmoon Slam", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77347] = { title = "Shadowmoon Slam - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77348] = { title = "Shadowmoon Slam - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77362] = { title = "Research: Drakonid of Forbidden Reach", description = "", objectives = "" }
WordHunterWoW_QuestEN[77377] = { title = "To Tyrhold! For Tyr!", description = "We recovered. We trained. And now it's time to face Elisande. \n\nCome with us to Tyrhold where Nozdormu, Chromie, and Eternus are waiting to send us to the Nighthold.\n\nWe will get that disc, and Tyr will finally be with us once more.", objectives = "Speak with Eternus in Tyrhold.", completion = "Are you sure you are ready to go to the Nighthold?\n\nAre you sure you know what you are up against with this \"Elisande\"?" }
WordHunterWoW_QuestEN[77398] = { title = "Eco-Dome Excursion", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77399] = { title = "Eco-Dome Excursion - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77400] = { title = "Eco-Dome Excursion - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77408] = { title = "Prophecy Stirs", description = "Prophet Velen has roused from meditation and he requests your immediate presence.\n\nA matter of great import has come to his attention. He would value both your wisdom and strength in addressing it.\n\nThe Prophet awaits you aboard the Vindicaar.\n\nTake this crystal. Our artificers have attuned it to the ship's teleportation matrix.", objectives = "Use the Teleportation Crystal to meet Prophet Velen aboard the Vindicaar.", progress = "I am thankful that you could make this journey.", completion = "Fear not, <name>. For once, the situation is not dire.\n\nIn fact, I am... tentatively hopeful. Though that hope is tempered with concern." }
WordHunterWoW_QuestEN[77409] = { title = "Uncertainty", description = "Scattered visions came to me as I meditated. Yellow and red. Shattering glass. A rush of warmth. I see my own hand, but I am afraid to grasp it. The scent of fel--of Argus.\n\nWhen I awoke, a message had been delivered. Hatuun wishes to meet.\n\nAfter the defeat of the Legion, I offered to help Hatuun and his people rejoin us. However, they chose to remain on Argus. \n\nHatuun has seldom reached out to us since then. Perhaps he has reconsidered.\n\nI will make the journey to Krokuun. Please, join me.", objectives = "Speak to Chieftain Hatuun in Krokuun.", progress = "I did not expect Velen to come. He has surprised me.", completion = "Let us see if Velen delivers the aid he once promised.\n\nThere is nothing preventing him this time." }
WordHunterWoW_QuestEN[77410] = { title = "Opening Wounds", description = "My hunters were the ones who found Arzal'kal. They said he helped them fight off several Legion ambushes.\n\nDuring our endless vigil on Argus, we had seen nothing like it. He was not as powerful as some demons, but he was persistent.\n\nHe said he wished to speak with Velen and knew that we had been in contact with him. So, I have fulfilled his request.\n\nIf Velen is all he claims to be, then he would not turn away even the least worthy of his people.\n\nWe will see. I expect little.", objectives = "Speak to Arzal'kal and listen to what he has to say.", progress = "If Hatuun called me here to listen, then I will.\n\nI owe Hatuun that respect.", completion = "Whatever it is that Arzal'kal wishes to show you, please accompany him.\n\nI must stay here and speak with Hatuun in private." }
WordHunterWoW_QuestEN[77411] = { title = "Contrition", description = "The man'ari have grown desperate since the Legion fell. Some grasp for power. Some isolate themselves. Others have formed cults awaiting the return of Sargeras. They have faith that he will lead them again one day.\n\nNalridun is the leader of one such cult. They are reclusive, but it is rumored that he has seized an ancient relic that Kil'jaeden kept until his death. Nalridun claims to use it to commune with Sargeras.\n\nI believe I know what this relic is. If I am correct, it must be returned to Velen.", objectives = "Meet Arzal'kal in the Grove of Naroua, then slay Speaker Nalridun and retrieve the ancient draenic relic.", progress = "Even if I die here, at least it will not be at the Legion's whim.", completion = "It is done. \n\nOne evil rectified. \n\nIt is all I allowed myself to hope for." }
WordHunterWoW_QuestEN[77412] = { title = "Proof and Promise", description = "Reinforcements are unlikely, but the relic is too important to risk. You should return to Prophet Velen with it immediately.\n\nThere is a teleporter just ahead that I can attune to a sigil of my own. It will provide you swift passage.\n\nI will rejoin you later.", objectives = "Deliver the Brilliant Star to Prophet Velen in Krokuun.", progress = "I sense something of great power in your possession.\n\nIt feels... familiar. But placing the memory feels like grasping at sunlight.\n\nDid Arzal'kal lead you to something?", completion = "Is this...?" }
WordHunterWoW_QuestEN[77414] = { title = "Dreamsurge Investigation", description = "The Emerald Dream bleeding over into Azeroth is unprecedented, {name}. We need to understand exactly what is being affected by this phenomenon if we're to prepare ourselves for what is to come.\n\nPerhaps we can even turn this to our advantage.\n\nHead out into the affected area and see what you can learn. Bring back anything of interest and we will see what can be done.", objectives = "Complete activities in the Dreamsurge.", progress = "How fares the Dreamsurge?", completion = "With this information, <name>, we should be able to shape the Dreamsurge to our advantage. Thank you." }
WordHunterWoW_QuestEN[77415] = { title = "The Hidden Hand", description = "Catching him at the very moment he's alone? They must've been watching somewhere nearby but just out of sight. Can you check that cave across the water?\n\nThose hornswogs are known hoarders. If those drakonid left something behind, it may still be there.", objectives = "Search hornswog treasure piles for Neltharion agent items.", progress = "Did you check that cave?", completion = "What did you find?" }
WordHunterWoW_QuestEN[77417] = { title = "What Makes an Infinite", description = "Eternus clearly has something she wishes to impart to us. I am unsure where this conversation will lead. \n\nBut I trust Chromie. If she believes that Eternus can be swayed, I trust her judgment.\n\nWhen you are ready, I will see what she has to say.", objectives = "See what Eternus has to reveal.", progress = "I am interested in learning what Eternus wishes to say.", completion = "So the loss of her sister, Moraidormi, is at the root of everything..." }
WordHunterWoW_QuestEN[77423] = { title = "Surging Dreams", description = "Change is coming, {name}. Those attuned to the Emerald Dream can feel it on the wind.\n\nWe need your aid in uncovering what this change entails.\n\nLet us reconvene in the affected area and formulate a plan.", objectives = "Meet the druids investigating the Dreamsurge.", completion = "This nascent \"Dreamsurge\" is affecting us all. We have much to investigate." }
WordHunterWoW_QuestEN[77424] = { title = "Research: Dracthyr of Forbidden Reach", description = "", objectives = "" }
WordHunterWoW_QuestEN[77425] = { title = "The Scale of it All", description = "The Djaradin were trading harpoons with the Tuskarr? I suppose fish harpoons don't cut it when you're dealing with a dragon.\n\nHow big was this shipment do you think? Check around the Zaqali Quartermaster and see if they held onto any ancestral records.", objectives = "Search near the Zaqali Quartermaster for any record of Tuskarr trading.", progress = "I know Djaradin aren't normally known for their record-keeping, but there must be something...", completion = "You're back! With good news, I hope?" }
WordHunterWoW_QuestEN[77426] = { title = "Practice Makes Perfect: Rusziona", description = "Interested in trying to get a faster time?\n\n: Dash forward.\n: Stops forward movement.\n: Restores all Vigor. Must be grounded.", objectives = "Help Rusziona glide through the rings." }
WordHunterWoW_QuestEN[77427] = { title = "Practice Makes Perfect: Zhusadormu", description = "Interested in trying to get a faster time?\n\n: Tranform into an adult and gain improved speed.\n: Restore 1 Vigor until all Vigor has been recovered.\n: Resets cooldowns.", objectives = "Help Zhusadormu glide through the rings." }
WordHunterWoW_QuestEN[77428] = { title = "Practice Makes Perfect: Zalethgos", description = "Interested in trying to get a faster time?\n\n: Blink forward and dash.\n: Increases forward acceleration.\n: Consumes Arcane Acceleration and restores Vigor.", objectives = "Help Zalthgos glide through the rings." }
WordHunterWoW_QuestEN[77429] = { title = "Practice Makes Perfect: Posidriss", description = "Interested in trying to get a faster time?\n\n: Fly up then restore 1 Vigor.\n: Adds 5 sec to Winds of Life's duration.\n: Anytime you restore Vigor, dash forward.", objectives = "Help Posidriss glide through the rings." }
WordHunterWoW_QuestEN[77430] = { title = "Practice Makes Perfect: Belastrasza", description = "Interested in trying to get a faster time?\n\n: Consumes all Vigor over time.\n: Restore all Vigor, boosting forward each time.\n: Consumes Crimson Flight, resets cooldowns.", objectives = "Help Belastrasza glide through the rings." }
WordHunterWoW_QuestEN[77432] = { title = "Pedgi the Parched", description = "Pedgi's being dramatic. Again.\n\nI know it seems childish, and that's because it is childish, but he responds well to little treats when he's in a mood.\n\nCould you get him a coffee from the bar downstairs?", objectives = "Get Pedgi a drink from the inn's bartender.", progress = "Pedgi's treat should get him to stop moping. By the titans, I can't believe I had to say that...", completion = "I knew musicians were a temperamental sort, but this is ridiculous. At least he's up." }
WordHunterWoW_QuestEN[77433] = { title = "Excavation: Riverbed", description = "There's a Riverbed near Maruukai in Ohn'ahran Plains that's teeming with local lore about a lost caravan!\n\nMeet me there as quick as you can! And wear your best, old, mud-ready boots!", objectives = "Meet Roska Rocktooth at the Riverbed dig site in Ohn'ahran Plains.", completion = "We'll shake up the centaur world with this find!" }
WordHunterWoW_QuestEN[77434] = { title = "Technoscrying: Observatory", description = "My dowsing rods have been pointing towards a set of Drakonid ruins atop a cliff in Waking Shores.\n\nI know not what we'll find, but it's never wise to question the whims of my inventions. They're always 97% correct. \n\nAlways.", objectives = "Meet Zenata at the Concord Observatory in Waking Shores.", completion = "Shall we peek into the past of these crumbling stones?" }
WordHunterWoW_QuestEN[77436] = { title = "The Burning Barrow", description = "Fyrakk's forces have already set their plans in motion. We are one step behind, and we need to catch up quickly if we are to properly protect Amirdrassil.\n\nWhile you were on your way here, we received word of suspicious-looking figures entering one of the nearby barrow dens. Tyrande already went to investigate. Seek her out and lend her your aid.", objectives = "Find Tyrande near the Sor'theril Barrow Den.", completion = "Your arrival is timely, <class>. I require another set of hands." }
WordHunterWoW_QuestEN[77437] = { title = "Eon's Fringe", description = "Timewalker Tempo and their team finally unfroze Eon's Fringe!\n\nEr... mostly. The Timewalkers have things more or less under control but Eon's Fringe has some problems the people of the town wouldn't mind a hand with. \n\nTell Bob I sent ya!", objectives = "Find Bartender Bob in Eon's Fringe.", completion = "I'm glad Zera sent you! We have some folks who could use a hand around here." }
WordHunterWoW_QuestEN[77483] = { title = "Technoscrying: Dragonskull Island", description = "I tuned my various sensors for Dracthyr relics, and they've triangulated a new location for us to investigate off the eastern coast of the Forbidden Reach.\n\nThe local Drakonid tell me it's named Dragonskull Island. Ominous, no?  You're not easily frightened, are you?", objectives = "Meet Zenata at Dragonskull Cave in Forbidden Reach.", completion = "My preliminary sensors are peaking when near the cave entrances. What we're looking for is most certainly inside." }
WordHunterWoW_QuestEN[77484] = { title = "Technoscrying: Igira's Watch", description = "Of all places, my sensors are indicating a site of interest beneath the surface in Zaralek Cavern. \n\nBest bring a weapon for this excursion. My preliminary scouting indicated a elevated  presence of both lava and djaradin.", objectives = "Meet Zenata at Igira's Watch in Zaralek Cavern.", completion = "They seem willing to leave this cave well enough alone, don't they..." }
WordHunterWoW_QuestEN[77485] = { title = "Technoscrying: Back to Eadweard!", description = "Thanks for all your help!\n\nLet's head back to Eadward and the others back at the Academy to go over all the new information we've uncovered.", objectives = "Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.Thanks for all your help!\n\nLet's head back to Eadward and the others back at the Academy to go over all the new information we've uncovered.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[77486] = { title = "Excavation: Gaze of Neltharion", description = "A Niffen colleague of mine gave me the underground info about an underground tower. It's decrepit and smack-dab in the middle of Zaralek between Loamm, the Djaradin, and that ghastly lab of Neltharion's.\n\nGrab your favorite shovel and meet me there!", objectives = "Meet Roska Rocktooth at the Gaze of Neltharion in Zaralek Cavern.", completion = "Let's do as the Niffen do and sniff out these hidden histories." }
WordHunterWoW_QuestEN[77487] = { title = "Excavation: Winglord's Perch", description = "We've discovered an ancient fishing village in the Forbidden Reach! It's this humble isle off the northwest coast with its own crumbling bridge and everything!\n\nI'll be there if you're looking for more dirt to dig up!", objectives = "Meet Roska Rocktooth at Winglord's Perch in Forbidden Reach.", completion = "<name>! You made it!\n\nThat sea air really wakes you up!" }
WordHunterWoW_QuestEN[77488] = { title = "Excavation: Back to Eadweard!", description = "Great job, {name}!\n\nWe've got plenty of history to report back to Eadweard with. Let's meet back at the Academy!", objectives = "Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.Great job, <name>!\n\nWe've got plenty of history to report back to Eadweard with. Let's meet back at the Academy!You will receive:\n\nUpon completion of this quest you will gain:" }
