WordHunterWoW_QuestEN[77644] = { title = "The Scarlet Key", description = "<Though dirt and rust have accumulated on these keys, the one you currently possess looks no different otherwise.>", objectives = "<Though dirt and rust have accumulated on these keys, the one you currently possess looks no different otherwise.>", progress = "<Though dirt and rust have accumulated on these keys, the one you currently possess looks no different otherwise.>", completion = "<As you return the key to its rightful place, it may prove difficult to ignore the passing curiosity of what it may unlock. Given the evident abandonment of those already present, surely no one would be the wiser if you chose to borrow it in the future.>" }
