WordHunterWoW_QuestEN[77697] = { title = "The Right Food...", description = "<The plant is now a promising sapling and has thrived with the attention you've given.\n\nPeering closely at the plant's leaves, you see its exterior brimming with dew. Perhaps the right food will help the plant even further.>", objectives = "Bring some fertilizer for the plant.", progress = "<The plant is hydrated, but remains severely underfed.>", completion = "<The soil around the sapling glows faintly.>" }
WordHunterWoW_QuestEN[77698] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[77711] = { title = "And a Pinch of Magic", description = "The diligence you've shown here is astounding, {name}. I never suspected that someone who couldn't even find their own bucket, could do something like this.\n\nI think the sapling is almost there, and with my help we can bring it the rest of the way.\n\nTake this totem and place it near some of the weakened, flame-corrupted Roottenders found in the Singing Fen. This should siphon the unstable magical energies out of their bodies and transform it into something we can use.", objectives = "Defeat Roottenders while they are under the effects of the Druidic Totem.", progress = "Is the totem charged?", completion = "Perfect!\n\nHand it here and I'll release the stored energy into the surrounding soil." }
