WordHunterWoW_QuestEN[77739] = { title = "Smother the Flames", description = "Lilian and I have been shadowing Raelas Firewind and have uncovered his plan. He has manipulated the Sisters of the Flame to bind spirits from the Dream to magical spirit stones.\n\nWith Raelas's blessing, these stones became powerful tools of corruption, allowing these fallen dryads to twist the Dream and its denizens.\n\nWe will start our purge with the dryads--they have the stones. Then we will end Raelas.\n\nThe hunt begins, {name}.", objectives = "Help Shandris and Lilian retrieve the spirit stones from the Sisters of Flame dryads.", progress = "Bring me all four spirit stones. We must keep them close so they do not fall into the wrong hands.", completion = "Good!\n\n<Shandris stashes the spirit stones in a small, leather pouch.>\n\nNow, let us put an end to Raelas's madness." }
