WordHunterWoW_QuestEN[77760] = { title = "Curious Find: Dragonhorn Flute", description = "<This flute is inexpertly hewn out of the horn of a dragon. The cracking around the base suggests the dragon was long gone by the time the flute was made.\n\nThe mouthpiece is strange. It's almost like it isn't designed to be played with the mouth at all but the nose. Could this flute have been crafted by the niffen?\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", objectives = "Bring the Dragonhorn Flute to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", completion = "Aha! A curious find. I shall reach out to the appropriate parties immediately, and we can have it documented and returned to its home post-haste." }
WordHunterWoW_QuestEN[77761] = { title = "Documenting a Dream", description = "", objectives = "" }
WordHunterWoW_QuestEN[77762] = { title = "A Little Hope is Never Without Worth", description = "The plant has matured and is thriving. And with this little corner of our ecosystem restored, we've seen something I've been wishing for since I learned what you were up to: the dreamtalons have returned with their kits!\n\nOne of the grateful mature dreamtalons has offered their services to you, if you wish it.", objectives = "Speak to Professor Ash.", completion = "If you treat this Dreamtalon like you've treated this plant, they're very lucky indeed." }
WordHunterWoW_QuestEN[77763] = { title = "Curious Find: Waterlogged Ledger", description = "<This leather-bound ledger is so waterlogged it's nearly falling apart.\n\nMost of it is illegible, but the text that has survived is in an ancient draconic dialect. It appears to be lists and lists of ordinary items, with numbers assigned to them-- perhaps a household accounting book?\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", objectives = "Bring the Waterlogged Ledger to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", completion = "Aha! A curious find. I shall reach out to the appropriate parties immediately, and we can have it documented and returned to its home post-haste." }
WordHunterWoW_QuestEN[77765] = { title = "Documenting a Dream", description = "", objectives = "" }
WordHunterWoW_QuestEN[77766] = { title = "Curious Find: Hole-Punched Bakar Tooth", description = "<This milk-tooth came from a young bakar, though the way the bone has yellowed suggests it's thousands of years old.\n\nSomeone has carefully drilled a hole at the top of this tooth to turn it into a bead. Upon closer examination, the tattered remains of a woolen cord can still be seen threaded through it.\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", objectives = "Bring the Hole-Punched Bakar Tooth to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", completion = "Aha! A curious find. I shall reach out to the appropriate parties immediately, and we can have it documented and returned to its home post-haste." }
WordHunterWoW_QuestEN[77777] = { title = "Ruby Lifeshrine Loop - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77779] = { title = "The Tale of Sir Thomas", description = "Suzannah... I never thought I would find her. Now we can return to our children, and rest at last. All thanks to you, {name}.\n\nDo you still have my tome? My story has reached its end, and I would see it penned by my own hand.\n\n<Thomas glides his finger across a blank page, spectral ink marking his words.>\n\nPlease return this to the Orphan Matron. And... please apologize on my behalf for frightening her, would you?", objectives = "Return to the Orphan Matron.\n\nProvided item:", completion = "It is over, then? The Headless Horseman is defeated once more, and the fallen paladin is free and at rest.\n\nWhat happened to the people of Lordaeron was horrifying. The least they deserve is peace in death. The tale of Sir Thomas is a harrowing one--a reminder and a warning of what horrors blind zealotry brings. \n\nI am glad that you helped him find his peace, <name>." }
WordHunterWoW_QuestEN[77780] = { title = "A Blossom Witnessed", description = "Amirdrassil has bloomed beyond the confines of the Dream.\n\nLet us venture to the Dragon Isles and see where this new World Tree has taken root.", objectives = "Speak with Merithra at the Ancient Bough in the Ohn'ahran Plains.", progress = "It is magnificent!", completion = "<Merithra's face lights up.>\n\nChampion, we are among the very first to see Amirdrassil here on Azeroth. This is truly a precious moment." }
WordHunterWoW_QuestEN[77781] = { title = "A Different Enthusiasm", description = "I noticed the festivities have drawn the attention of a few spriggans from Ardenweald. They are curious creatures with... interesting tastes.\n\nTheir pranks have been more than disruptive. Please root them out so the celebration may continue in peace.", objectives = "Reveal 6 Spriggan Pranksters in Bel'ameth.", progress = "Have you discovered all of them? I have already heard a middling rumor that I suspect they spun up.", completion = "Thank you, <name>. I appreciate their liveliness, but they are not on our guest list tonight." }
WordHunterWoW_QuestEN[77784] = { title = "Tyrhold Trial - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77785] = { title = "Fen Flythrough - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77786] = { title = "Vakthros Ascent - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77787] = { title = "Stormsunder Crater Circuit - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77788] = { title = "Ashphodel Research Notes", description = "<You find some singed research notes on the slain druid. \n \nThe notes detail experiments being carried out by the Druids of the Flame.  \n\nYou learn that they have created an unusual pollen capable of infusing dream flora with their flame-imbued magic. The next stage targets the local wildlife with the same pollen. \n \nQ'onzu would definitely be interested in a sample of the pollen and these notes.>", objectives = "Collect the Sample of Cinderpollen.", progress = "<Q'onzu blinks slowly as they stare down at you.>", completion = "That...was devastatingly mundane. Soot and ash, forever unchanged? \n \n<Q'onzu shakes their enormous head.> \n \nNo. I do not like." }
WordHunterWoW_QuestEN[77789] = { title = "Severing Ties", description = "Nalridun has recruited a small army of cultists. They believe he speaks for Sargeras through the relic, clinging to every word he says. The same way we clung to our leaders when Sargeras came to Argus. It was a comfort. A hope.\n\nAnd, in the end, empty deception.\n\nBut his followers do not believe they are deceived. They have constructed their own conduits in the area to try to tap into the relic's power. To hear the voice themselves.\n\nThey will try to stop us. We must cut a path through them.", objectives = "Slay 10 man'ari cultists and overload 5 Sargerei Conduits.", progress = "May their delusions die with them.\n\nWe cannot risk any power they might be adding to Nalridun's rituals.", completion = "I know what it is to be scared. But they had a choice, and they chose to stay on the path that we built atop the smoldering remains of countless worlds. \n\nWhy, when our home was the first of the worlds we destroyed?" }
WordHunterWoW_QuestEN[77791] = { title = "Handling It: Symbiotic Glowspore Grip", description = "I know a crafter who could help temper Fyr'alath. Erden of Clan Shikaar is extremely resourceful. He's performed many experiments with various reagents throughout the Dragon Isles.\n\nHunters are only as good as their weapons. Erden is known for crafting exquisite weaponry with exotic materials. His expertise in various flora and fauna should prove quite informative.", objectives = "Seek out Erden in the Ohn'ahran Plains.", completion = "I see. \n\nThat axe would certainly be painful to wield. Let me think for a moment." }
WordHunterWoW_QuestEN[77793] = { title = "Crystal Circuit - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77794] = { title = "Waking Dream Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[77795] = { title = "Scavenged Artifacts", description = "", objectives = "If you have supplies, I have wares. Old things. Some sacred things." }
WordHunterWoW_QuestEN[77802] = { title = "What Do I Call You?", description = "Guardian! Or... teacher! Parent?\n\nI want you to tell me what to call you. The other dryads will ask me who my druid is now that I am working in the garden on my own.\n\nI want to tell them that I do not have a druid. I have you!\n\nTell me what title you prefer.", objectives = "Speak with Dionaessa to choose a title in the Root-Bound Sanctuary.", progress = "I have heard so many titles from the druid Creekward. I am certain we can come up with something far more interesting.", completion = "What an excellent title! I will use it as often as I can.\n\nThank you." }
WordHunterWoW_QuestEN[77813] = { title = "Lightning Strikes", description = "<Flaps does a spin and deposits a drool-soaked note into your hand.>\n\nAh, {name}. I am told you have acquired a fine new mount. A gryphon that soars upon the very storm itself!\n\nI would very much like to see how this wondrous creature flies. I will await you at Skytop Observatory.", objectives = "Meet Lord Andestrasz at the Skytop Observatory.", completion = "Hello again, <name>. Now, let us see about this gryphon!" }
WordHunterWoW_QuestEN[77815] = { title = "The Storm Race Tour", description = "This storm gryphon is intriguing! Whatever land gave rise to such a creature merits further exploration.\n\nBut since you are here, let us test its training--and your riding skills.\n\nMy colleagues in the bronze flight have laid out new courses to put the mount through its paces. When a timekeeper sees you upon your gryphon, they will offer you the chance to fly these \"storm races\".\n\nFortune favors the bold, {name}. Good luck!", objectives = "Fly each of the Storm Race courses around the Dragon Isles.", completion = "Well done! This storm gryphon is indeed an impressive creature. May you share many wondrous adventures!\n\nFair skies and strong winds, <name>." }
WordHunterWoW_QuestEN[77818] = { title = "The Cruel", description = "Primalists, djaradin, and Druids of the Flame all work together against us.\n\nBut I can sense that this is not the last of them. Something powerful is trying to come through this portal. Let us try to seal them out for as long as we can.", objectives = "Help Merithra close the flaming portal.", completion = "I am glad you made it out. We have no choice but to retreat to the tree, before Fyrakk's forces arrive.\n\nAnd Elder Cassaphine... I fear that she has already been lost to this prophecy of flame." }
WordHunterWoW_QuestEN[77822] = { title = "A Titanic Mold", description = "<The Titan Key Mold was at the location referenced in the story. Weaponsmith Koref will be so excited to see the mold!>", objectives = "Return the Titan Key Mold to Weaponsmith Koref in Valdrakken.", progress = "By the forge, did you actually do it? Did you find the Titan Key mold?", completion = "I cannot believe it, <name>! We simply must reforge the key now that we have the mold.\n\nI'll need to make preparations. The tome that Tithris gave me described an involved process. Magical rituals, special components, that sort of thing. I may need you help once I have all my irons in a row.\n\nI'll send word when I'm ready for the next step." }
WordHunterWoW_QuestEN[77829] = { title = "Reforging a Legend", description = "There you are! Weaponsmith Koref was just looking for you. Left me with a note asking you to meet him in the Obsidian Conclave.\n\nSounds like you're helping him reforge an ancient titan key? Let me know how it goes! That's headline news if I ever heard it.", objectives = "Seek out Weaponsmith Koref in the Obsidian Enclave.", completion = "We'll need rare materials for the key. Some special gold dust and flux. You'll find them both in the Waking Shores.\n\nAfter you find the materials, meet me at the Earth-Warder's Forge in the Obsidian Citadel. That's where I'll forge the Titan Key. And take my place amongst blacksmith legends, should my anvil strike true.\n\nHere, this note that has all the details. We're so close, <class>!" }
WordHunterWoW_QuestEN[77831] = { title = "A Key To Reforg(ing)", description = "You have the final materials! Perfect.\n\nI prepared the forge and the mold. I just need you to add the ingredients when I say.\n\nOh, and be ready to use that Torch of Pyrreth. Seems the relic is crucial to the forging process. I'll tell you when!", objectives = "Assist Weaponsmith Koref in reforging the Titan Key.", progress = "The Titan Key. By the forge... Let me have a look.", completion = "This is amazing! And it's already cool to the touch? What incredible magic.\n\nHmm. There's writing on the shaft. I don't recognize most of it, but this is Tyr's symbol. I'll create a quick sketch of the rest of the entire message and see what I can find out.\n\nI'd say the key is safest with you. Besides, what's a key without a lock? And if anyone can find a titan lock in need of opening, it would be you." }
WordHunterWoW_QuestEN[77832] = { title = "Shadows upon shadows", description = "I need to save him.", objectives = "Slay the Shadows." }
WordHunterWoW_QuestEN[77833] = { title = "Handling It: Concentrated Sophic Vellum", description = "I know of a sage who can help temper Fyr'alath. Shalasar Glimmerdusk is an expert in intellectual matters, often pondering theories for controlling volatile magics. Few understand sophic matters as well as she does.\n\nSeek her guidance in managing shadowflame. I suspect her solution may include a sprinkle of Chromatic Dust!", objectives = "Seek out Shalasar Glimmerdusk in the Ohn'ahran Plains.", completion = "Ah, yes! Thank you for making the journey here. \n\nOthers warned me not to isolate myself from academia, but I knew being sequestered in this remote natural locale would come in handy someday." }
WordHunterWoW_QuestEN[77835] = { title = "Handling It: Rune of Shadowbinding", description = "Lydiara Whisperfeather is an academic who recognizes the rigidity of the rules that govern our world. She also likes bending them.\n\nIf there is anyone who can assist in binding Fyr'alath's power, it's her.", objectives = "Seek out Lydiara Whisperfeather in the Azure Span.", completion = "You want to bind shadowflame? How dangerous! How daring! Let's do it.\n\nI've been studying flora in the Emerald Dream. Studying the realm's exotic and dreamlike plants is quite distracting, but I've seen one in particular that could help us find some answers." }
WordHunterWoW_QuestEN[77838] = { title = "Tattered Dreamleaf", description = "The properties of Dreamleaf are foreign to you. \n\nCompleting events during the Superbloom will give you the knowledge necessary to help your ally.", objectives = "Complete events during the Superbloom.", completion = "Shadowed Dreamleaf still remains perplexing but hopefully your ally could still use this knowledge." }
WordHunterWoW_QuestEN[77839] = { title = "The Eastern Kingdoms Cup Circuit", description = "It is once again time to test your mettle.\n\nMy bronze colleagues have traveled to the Eastern Kingdoms to create new racing challenges. Many racecourses await you across the continent.\n\nAre you up to the task?", objectives = "Fly through the introductory Eastern Kingdoms Cup courses.", progress = "Have you taken wing today?", completion = "You lead the way among your fellow skyriders! As the Eastern Kingdom Cup continues, find other races there and prove you are a cut above the rest." }
WordHunterWoW_QuestEN[77840] = { title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Valdrakken.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[77841] = { title = "Ysera Invitational", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77842] = { title = "Ysera Invitational - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77843] = { title = "Ysera Invitational - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77844] = { title = "Ysera Invitational - Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77845] = { title = "Ysera Invitational - Reverse Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[77865] = { title = "A Proper Burial", description = "", objectives = "Today you'll be returning a Maruuk Burial Banner. Truth be told, I almost feared that someone had stolen it. Again! But after searching the entire tavern, I went to double-check my locker and found it safe and sound!\n\nThe stress of these recent events seem to be getting to me... \n\nPlease, speak with Sansok Khan in Maruukai and return the banner to where it belongs." }
WordHunterWoW_QuestEN[77867] = { title = "Moruud", description = "", objectives = "" }
WordHunterWoW_QuestEN[77869] = { title = "Return to the Echo Isles", description = "{name}, there appears to be trouble in the Echo Isles.\n\nRokhan has requested your help.", objectives = "Meet with Rokhan in the Echo Isles.", completion = "It is good you be here, <name>. Trouble is brewin'." }
WordHunterWoW_QuestEN[77871] = { title = "De Old Loa", description = "Bwonsamdi does not be visiting in person without a good reason. Listen to all he has to say. \n\nDen we think, den we act.", objectives = "Hear Bwonsamdi's message to the Darkspear trolls and find a solution.", progress = "What Bwonsamdi be saying is very serious. Mueh'zala worship is a bloody one.", completion = "De Darkspear always be worshipping multiple loa, but Mueh'zala? We can do better.\n\nOur path is obvious." }
WordHunterWoW_QuestEN[77874] = { title = "De Loa of de Past", description = "We need to be findin' de old loa and call dem back. There must be a way to find where dey went. \n\nIf we can find de old loa, we can host a Trial of the Loa to reconnect with their power.\n\nBwonsamdi said dey are still out there. I think he be dropping a hint for us...", objectives = "Find a guide to one of the lost loa by making a proper effigy, and follow the guide.", completion = "I be feelin' somethings eyes on us. Judgin'. Dis loa be clever, but so are we.\n\nLet's continue." }
WordHunterWoW_QuestEN[77877] = { title = "One with the Loa", description = "Pieces of Lukou be scattered.\n\nBut her heart be deep inside the ogre mound.\n\nDe shadows can take us there. Quietly. Quickly. Speak to me when you are ready.", objectives = "Talk to Kevo to be taken inside the Mosh'Ogg Ogre Mound.", progress = "Kevo ya Siti wants to bring us inside the mound.", completion = "Dat was... somethin' else. Feels like my stomach still be outside!\n\nBut we be having work to do." }
WordHunterWoW_QuestEN[77878] = { title = "Envoy of Winter", description = "", objectives = "" }
WordHunterWoW_QuestEN[77879] = { title = "Stalking the Stalker", description = "If dis loa be huntin' here, he may have seen us already. Since we don't know for sure, let's split up.\n\nI be hunting for him, while ya get his attention. Jani says the loa has been taking the offerings meant for Hakkar, the loa of blood. \n\nBut we don't know WHY. Collect some and see if he wants them. If his motive is something else... we be knowin' soon enough.", objectives = "Collect 6 Offerings to Hakkar to attract the loa.", progress = "<Kevo ya Siti examines your offerings.>", completion = "<Kevo ya Siti accepts the offerings silently.>\n\nI don't be wanting dese offerings myself. Slowing Hakkar's return benefits us all.\n\nIt will take more than just remembering. Your hunt is just beginning." }
WordHunterWoW_QuestEN[77880] = { title = "Looking for Lukou", description = "Dis be the last place Kevo ya Siti sensed Lukou.\n\nWe be needing to ask around, see who knows where she might have gone.", objectives = "Ask about Lukou and follow the trail to find her.", progress = "With enough information, we can track Lukou down.", completion = "It be time to find Lukou." }
WordHunterWoW_QuestEN[77881] = { title = "There is Another", description = "If Mueh'zala be involved... I will help. But for a loa trial fit to push Mueh'zala out, we will need another.\n\nOur sister loa is also lost. We were a team, her and I, until disagreement pushed us apart. Lukou is the loa of regeneration. She be the ideal loa to balance against death.\n\nI owe her an apology. You are here, and it be time.\n\nI last sensed her presence near the small settlement of Bambala. I be meeting you there.", objectives = "Go to Bambala to seek out Lukou.", completion = "This place is not how I remember it.\n\nAnd I do not feel our sister. I will need to get closer to where she is." }
WordHunterWoW_QuestEN[77882] = { title = "Stolen but Not Forgotten", description = "There be many pieces missin' from dis altar. We be needing to repair it so dat Lukou is not angered when she returns, Lukou must see dat we are on her side.", objectives = "Collect 8 altar fragments from around the Mosh'Ogg Ogre Mound.", progress = "We need all the pieces you can find.", completion = "Got dem all?" }
WordHunterWoW_QuestEN[77885] = { title = "Dream Wardens", description = "", objectives = "" }
WordHunterWoW_QuestEN[77886] = { title = "Handling It: Shadowed Dreamleaf", description = "When Fyr'alath's power is at its limit, you will need a grip that can cool itself. It is like standing your ground when a beast charges you: as the battle heats up, you need a way to stay focused.\n\nVarious leathers throughout the Dragon Isles have that cooling property, but I know of something better. Foliage that is routinely exposed to shadowflame would be the best choice for binding the components together. Let us gather what you need.", objectives = "Collect Shadowed Dreamleaf from completing objectives in the Superbloom.", progress = "Did you find what we need?", completion = "Excellent.\n\nYou hunt for something long enough, you will always find it. I am glad we found precisely what you needed." }
WordHunterWoW_QuestEN[77889] = { title = "A Fiery Proposal", description = "Ah hello!\n\nI have been working with some inscribers recently. We've been making a new type of ink. It's like fire ink, but even fierier! \n\nWe need fiery essence from fire elementals, and fire elementals are currently attacking the dream. I believe this is what is called a \"win win\" scenario.\n\nPlease drop their essence off at my associate in Amirdrassil.", objectives = "Collect 10 Fiery Essence from fire elementals in the Emerald Dream.", progress = "New knowledge can come from the strangest sources!", completion = "Ah, wonderful. I will pass these on. \n\nThank you, <name>." }
WordHunterWoW_QuestEN[77891] = { title = "Fixing The Dream", description = "Engineering is an exact science! When something explodes, engineers plan it that way. \n\nDreams are not exact, especially emerald ones! Someday, someone will want engineers to fix the Dream, and we won't know how to do it. We need a lot more information to understand what we're dealing with!\n\nGo to the Dream and place research beacons at my designated points. They will gather the information needed for any future repairs. Use this handy teleport device if you want to find the locations quickly.", objectives = "Activate 8 Research Beacons", progress = "I wonder if we'll ever truly understand the dream.", completion = "So much useful data about the dream, it will keep the engineers busy for years." }
WordHunterWoW_QuestEN[77892] = { title = "Pearls Of Great Value", description = "When Amirdrassil's roots spread to the water, many rare creatures arose from the ocean's depths and now flourish around the dreams.\n\nOne such rare creature is the Sandsparkle Clam, which can contain magical pearls!\n\nSee if you can locate these clams and find some pearls within.", objectives = "Collect 10 Sandsparkle Pearls", progress = "Have you found any pearls?", completion = "Fascinating, <name>, there is great potential in the power of these pearls." }
WordHunterWoW_QuestEN[77894] = { title = "Heart of Lukou", description = "I was hoping we'd be getting more pieces than dis, but we make do with what we got, eh?\n\nCall Lukou to de altar. Hopefully she will answer.", objectives = "Summon and speak with Lukou at the altar.", progress = "We're close!", completion = "Thanks for the help, <name>. I was not harmed badly." }
WordHunterWoW_QuestEN[77896] = { title = "A Sleepy Search", description = "In our fight against Fyrakk's forces, a group of my fellow druids went out in search for a quiet and safe place to rest. But with Fyrakk's forces closing in on their location...\n\nI have to start planning for another assault, I can't split my time as much as I wish. \n\nI last saw them heading south to a cave by the shore. Please, I just need to make sure they're safe.", objectives = "Check up with the sleeping druids.", completion = "Have Fyrakk's forces attacked us? \n\nAs you can see, there is no issue with that here. \n\nHowever, I do have a much bigger problem on my hands." }
WordHunterWoW_QuestEN[77897] = { title = "A Special Book", description = "", objectives = "Well, if it isn't my trusty investigator. \n\nThere's a contact in the Kirin Tor who owes me a favor. They gave me a tip about a book in Karazhan that might help us decipher those tablets you recovered. You know, the ones from the Azure Span and Shifting Sands?\n\nBut we both know you're the one with the securing skills here. Here's the note my contact left. Should help you find the book!" }
WordHunterWoW_QuestEN[77898] = { title = "Honor and Tribute", description = "It be time to return home. Let us welcome dese loa to the Echo Isles. Their positive influence should make short work of Mueh'zala's presence.\n\nGo ahead, I be right behind ya.", objectives = "Set up the loa altars at Darkspear Hold.", progress = "The offerings need to be set exactly right.", completion = "All de offerings be set. Let's do de next step." }
WordHunterWoW_QuestEN[77899] = { title = "The Rush'kah", description = "When we make de rush'kah, we recreate de shape of the loa as we be seein' dem in our mind. By knowing the shape of de loa, we better understand who dey are. But de mask be shaped by our hands, so when de loa sees it, dey know what we expect dem to be. \n\nIf the loa don't bless the mask, we expect dem to be something dey will not be. If de loa bless de mask, dey like what we see in dem and a bargain can be struck. \n\nWe could just write a contract, but it is easier to lie with words than with your hands.", objectives = "Make a rush'kah.", progress = "De rush'kah be important in bonding with the loa.", completion = "Good work, <name>!\n\nAlmost done with mine here." }
WordHunterWoW_QuestEN[77900] = { title = "The Loa Trials", description = "When de loa bless the rush'kah, de trials will begin. Loa be giving tasks to teach us. Once de trials start, dey don't stop for nobody!\n\nLet's go to de altar together. Witch Doctor Tzadah will lead us in de ritual. She be Master Gadrin's apprentice, but be showin' real initiative in helping out on the trial.", objectives = "Start the trial at the Altar of Darkspear Loa.", progress = "It is time to begin de trial.", completion = "Dis trial be... something different, now. Normally, de loa grant visions or give tasks to teach and connect with us.\n\nInstead, we work together to stop Mueh'zala." }
WordHunterWoW_QuestEN[77901] = { title = "Retraining the Trainees", description = "Your witch doctor is trying to twist the trial to empower Mueh'zala. Many will be enthralled by this power, but we still stand with the Darkspear.\n\nI had a different trial in mind. Now, we adapt. Free your fellow trolls from his sacrificial magic. Dis charm will help them, but you must weaken them first.\n\nTry not to sacrifice dem.", objectives = "Extract 8 shadows from lost trainees after weakening them.", progress = "Use the charm on the trainees after you weaken them!", completion = "This will reduce the ritual's power. Mueh'zala does not get to claim more Darkspear!" }
WordHunterWoW_QuestEN[77902] = { title = "Ritual Recovery", description = "Dat witch doctor has stolen de trial. She mocks us, trying to eat de life of living things to free Mueh'zala. We still have influence over it, though. \n\nTogether, we will overwhelm her evil circles. When you find a circle, call upon me, and we will push death aside.", objectives = "Remove 3 ritual circles with Lukou's aid.", completion = "When you are fighting death, Lukou is a good ally." }
WordHunterWoW_QuestEN[77903] = { title = "De Power of Death", description = "De trial can't be stopped after it starts, but we won't let Tzadah use our people or our loa to aid Mueh'zala.\n\nIf we be doing nothing, even more Darkspear could be swayed to find power in Mueh'zala. I'll look for a way to breach Tzadah's protective energy, you stop the spirits from taking over our home!", objectives = "Kill Mueh'zala's summoned spirits.", completion = "Good work with those minions. Dat will keep them off our backs for what be ahead." }
WordHunterWoW_QuestEN[77905] = { title = "Avatar of Mueh'zala", description = "It be down to dis moment: working with our loa to save de soul of de Darkspear.\n\nSee if Jani has found anything. Hopefully, his item will let you get close enough to Tzadah's effigies to destroy dem. That should give us a chance to strike the Witch Doctor herself. I'll occupy her attention with Kevo ya Siti's aid, but watch out for her guardians. Dey won't let you destroy her effigies without a fight.", objectives = "Collect Jani's blessing and then travel with Lukou to the top of the pillars to defeat Tzadah's protection totems.", progress = "Tzadah is a disgrace to the Darkspear.", completion = "We defeated Tzadah. She can no longer aid Mueh'zala's attempts to escape his prison. \n\nWe could not have done this without de aid of de loa. Lukou, Kevo ya Siti, and even Jani." }
WordHunterWoW_QuestEN[77906] = { title = "De Darkspear Loa", description = "Dat was not a traditional trial, but we only keep tradition if it be helping de tribe.\n\nIt be our strength: to adapt to what comes.\n\nIt be time to shed de past and honor those most important to us. De Darkspear was never de largest tribe, nor de strongest. We endure because we choose our path, and our allies, well.\n\nDese loa and you all worked and sacrificed not just to help Bwonsamdi, but to protect de souls of de Darkspear. Dat be why we honor our loa... and you.", objectives = "Destroy Mueh'zala's altar and add Jani's.", progress = "The effigies need to reflect our favored loa.", completion = "De Darkspear don't just serve a loa because dat loa be strong. De Darkspear serve loa who serve de tribe. \nDat be what Lukou, Kevo ya Siti, and Jani did. So we honor them now.\n\nDe mask you made was not just for de ceremony. Take it, and de raiment of our tribe. \n\nWear them and know you are Darkspear." }
WordHunterWoW_QuestEN[77908] = { title = "A Legacy of Secrets", description = "<Return the book to Bobby Carlisle in Valdrakken to assist with deciphering the tablet text!>", objectives = "Return the book, Tyr's Legacy, to Bobby Carlisle in Valdrakken.", progress = "Was my source any good? Were you able to find the book?", completion = "Of course you found it! You know, you could have a real future as a field investigator.\n\nTyr's Legacy, huh? Interesting. I'll start working with Kathos to see if we can decipher any of the text on those tablets. I'm sure this book is the key.\n\nWe're getting so close! I can already see the headlines." }
WordHunterWoW_QuestEN[77910] = { title = "Enchanted Shrubbery", description = "Certain plants from the Emerald Dream could contain ingredients that would be helpful in our work here, but we need a lot of them, and I'm not hiring some herbalist to collect them.\n\nI've enchanted a water pot to help solve the problem. \nTravel to the Emerald Dream and use it on the plants I require. The plants should then deliver themselves.", objectives = "Use the Watering Pot on 12 Enchanted Shrubs.", progress = "Have you found the plants?", completion = "Excellent work, these plants certainly do spruce up the place!" }
WordHunterWoW_QuestEN[77911] = { title = "Build-a-Blanket", description = "I am unable to rest! I have spent all my energy in battle, but there is too much noise and the ground is too hard for me to sleep...\n\nI know! It pains me to ask this, but I need to rest so I can go back out and fight.\n\nCould you feed two birds with one seed for me? Take out the enraged lashers and retrieve their leaves so I can make a blanket to rest on.", objectives = "Collect 6 Velvety Lasher Leaves from lashers.", progress = "For the Emerald Dream, it sure is quite chaotic here.", completion = "Thanks for the leaves. Hopefully this will help me fall asleep." }
WordHunterWoW_QuestEN[77912] = { title = "Unmodern Jewelry", description = "Some of the local Jewelcrafters are looking to study examples of the Zaqali tribes adornments.\n\nGiven they are currently attacking my home, we may take advantage of the situation.\n\nI thought you might take them violently, yes?\n\nArgonax waits once you have collected them.", objectives = "Collect 10 Zaqali Adornments.", progress = "New knowledge can come from the strangest sources.", completion = "I was not expecting these so soon. \n\nYou do work fast, <name>." }
WordHunterWoW_QuestEN[77914] = { title = "Burning Runes", description = "I am told that the Druids of the Flame help to stabilize their portals into the dream through the use of a unique sort of inscription! While their ends are abhorrent, I cannot help but be curious as to their means.\n\nIf we can better understand their methods, then perhaps we can better equip our allies to stem the tide of their arrival. If you get your hands on any burning runes, could you bring them to my colleague for further study?", objectives = "Collect 10 Burning Runes from druids of the flame in the Emerald Dream.", progress = "Take care, friend. I doubt the Druids of the Flame will part with their runework willingly.", completion = "You have my thanks. We will endeavor to decipher these forthwith.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[77922] = { title = "Fluffy Filler Retrieval", description = "There is no way I could rest without something soft to sleep on. Luckily, the dream has some sage so plush, that it would even put roc feathers to shame! It would be a perfect filling! \n\nCould you collect some sage around the area for me to rest on?", objectives = "Collect 8 Silky Sage.", progress = "The sage should be soft enough to make a comfortable place to sleep. Thank you for your assistance.", completion = "Thanks for bringing back the bed filling." }
WordHunterWoW_QuestEN[77928] = { title = "They Are Always Listening", description = "Remember my contact, Fangli Hoot? Seems she has another theory about the one behind these artifact thefts.\n\nI'm a bit weary after the last tip went nowhere, but we can't turn down a lead. Journalistic integrity demands we at least hear her out.\n\nYou'll find her by the barber shop.", objectives = "Speak with Fangli Hoot near the Valdrakken barber shop.", completion = "Ok, this time I'm sure. I tracked everyone, yes everyone, even you.\n\nTithris is behind everything. He's been meeting with shady characters all over the city to secure supplies for something big. My guess is an expedition. \n\nYou need to investigate several caches of his purchases. I noted coordinates for the general locations. Put that thinking cap to work! And that idol of yours can help you narrow in on their exact location." }
WordHunterWoW_QuestEN[77932] = { title = "Warmth of Life", description = "The Druids of the Flame practice virulent magics that warp and burn all they touch. They do, however, have excellent taste in alchemical reagents.\n\nIf you should happen across any of their metamorphic ash, could you gather it up for me? One of my contacts within the Dream has been asking after the stuff.", objectives = "Collect eight samples of Metamorphic Ash from Druids of the Flame in the Smoldering Copse.", progress = "Ah, there you are! Have you managed to get your hands on any of that ash, yet? Its alchemical properties are truly wondrous.", completion = "Ah, wonderful! The things I will be able to accomplish with this... One does not simply walk into the Firelands, after all!" }
WordHunterWoW_QuestEN[77933] = { title = "Bubbling Discoveries", description = "The rise of Amirdrassil has unlocked various geological wonders in the dream. Among these are a variety of magical springs, bubbling water from deep within Azeroth.\n\nTravel the dream and gather samples from these springs.", objectives = "Collect 8 samples from Bubbling Springs.", progress = "Have you gathered the samples?", completion = "I shall share these with the others here, after sampling them myself." }
WordHunterWoW_QuestEN[77934] = { title = "A Complete Inventory", description = "<Compile your notes on the caches for Fangli Hoot in Valdrakken.>", objectives = "Report your findings to Fangli Hoot near the barber shop in Valdrakken.\n\nProvided item:", completion = "Hmm, nothing unusual. Still, I'm convinced this is our drakonid. Why would a simple innkeeper be meeting up with so many shady characters?\n\nI need to recheck my data and look through what you brought me. Maybe something will pop up.\n\nWatch yourself, <name>. I may be paranoid, but I'm not blind. We're running out of time." }
WordHunterWoW_QuestEN[77935] = { title = "A-Sword-ed Needs", description = "Swords!\n\nSorry, I saw you and I did not want to forget.\n\nYes. We need swords. In the Dream. You can provide, yes?\n\nPlease deliver them to Cylania.", objectives = "Deliver 3 Draconium Swords to Cylania in the Emerald Dream", progress = "Can I help you?", completion = "We will put these to good use. \n\nThank you, <name>." }
WordHunterWoW_QuestEN[77936] = { title = "A Warm Harvest", description = "Everyone knows heat plays a critical role in blacksmithing.\n\nI hear the Emerald Dream is still heavily under attack by allies of the flame. There must be a way to harvest fuel from those eternally fiery creatures.\n\nIf you do secure anything, I'm sure one of the local blacksmiths in the Dream will be very interested.", objectives = "Collect 10 Essence of Endless Flame in the Emerald Dream.", progress = "Hmm. Yes?", completion = "You've faced dangerous enemies to acquire these materials. Thank you. This will prove mightily useful for crafting our own devices." }
WordHunterWoW_QuestEN[77937] = { title = "Forbidden Sugar", description = "During this very unique time of bloom, a new flower has been discovered in the Dream. These stunning flowers produce a marvelous pollen. Its aroma is a delight, just like fresh baked cookies.\n\nTo the dismay of chefs, even eating a tiny bit will result in rapid, severe poisoning of the liver.\n\nHowever, it is an incredible all-purpose addition to enchanting. Early tests demonstrate potency as high as quadruple that of Chromatic Dust. Traders from Valdrakken are very interested in its acquisition.", objectives = "Collect 8 Glowdrop Sugar from Shaded Glowdrops in the Emerald Dream.", progress = "The enchanters would love to have more for testing. They must use and test it wisely. We hope the flower will persist even after the great bloom, but no one can know for sure.", completion = "Ahh--I thought you had brought me fresh baked cookies! But this is even better." }
WordHunterWoW_QuestEN[77938] = { title = "An Unlikely Engineer", description = "I hear there is a legendary engineer in the Dream who crafts the most beautiful dream catchers.\n\nThis engineer, Nyla Bushtail, enjoys acorn-flavored morels and relies on them to fuel her work. Acorn-flavored mushrooms... certainly strange, but perhaps not unheard of.\n\nThere's a coastal area close to the Eye of Ysera where these morels grow abundantly. Do tread carefully around any wildlife in the area. If these morels are as tasty as I hear, they will be guarded greedily.", objectives = "Collect 8 Whiteburr Morels for Nyla Bushtail in the Emerald Dream.", completion = "<Nyla Bushtail, a fluffy, bright-eyed Fol'ya, accepts the morels with small paws. She tucks them away into a stash nearby, her movements fluid and tidy.\n\nThis must be the legendary engineer who loves acorn-flavored mushrooms. It all makes sense now.>" }
WordHunterWoW_QuestEN[77945] = { title = "Boots on the Ground", description = "Just who I wanted to see.\n\nI have a requisition script for items of leather from some of the denizens of the Dream. Shoes, of course. Bipeds tend to go through them like a bird through the forest, yes?\n\nOnce you have acquired them, please take them to Cylania.", objectives = "Deliver 3 Pioneer's Leather Boots to Cylania in the Emerald Dream.", progress = "Can I help you?", completion = "Wonderful, thank you, <name>. \n\nYou can never have enough boots." }
WordHunterWoW_QuestEN[77946] = { title = "Fibrous Thread", description = "Fine thread may conjure images of tailory, but it can serve a vital role in leatherwork as well.\n\nSome of the Dream's hardier flora can be processed into a thread strong enough to secure even the thickest of hides and scales. If you happen upon any dense fiber during your travels, you would be well-served by bringing it to my colleague in the Dream.", objectives = "Bring 1 Emerald Fiber from Enchanted Thickets in the Emerald Dream.", progress = "You needn't worry about the plants themselves. They are nigh impossible to harm, and so long as they are treated respectfully, they will be more than happy to share their bounty with you.", completion = "Ah! This is precisely what I needed. You have my thanks, <name>." }
WordHunterWoW_QuestEN[77947] = { title = "Primalist Fashion", description = "Ah, {name}, there you are!\n\nThe robes of the primalists make for interesting study for the local tailors. If you could retrieve some from the primalists assaulting the dream, I would be pleased, yes?\n\nNo rips or tears please. Blood stains optional. They can be washed out.", objectives = "Collect 10 Intact Primalist Garb from the Emerald Dream.", progress = "Can I help you?", completion = "Magnolia mentioned you would be dropping off some robes.\n\nAh, she also mentioned they may need to be washed.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[77948] = { title = "Burning Out", description = "Please, I know how this looks, but we are on the same side!\n\nMy siblings and I intended to defect from the Flame together. However, none of them have escaped or met up with me since I left, and it's been days! I fear the worst.\n\nDo you think I would be begging for aid, alone and unarmed, if I was not honest? Please, find them. They are all I have left.", objectives = "Find Solarys's siblings in the Smoldering Copse.", completion = "<Solarys's face falls, clouding with grief at your explanation.> \n\nFinite moments with my family are worth more than an eternity of regrets. Life itself is worth more than that, but my pleas fell on deaf ears.\n\nThank you for saving what little of my family is left.\n\nOne of the little creatures Kery'nael helped saved seems to have taken a liking to you. Please take them. It's the least we can offer the poor thing." }
WordHunterWoW_QuestEN[77949] = { title = "Fashion Feathers", description = "Much of the Dream's wildlife is feathered or furred. Their shed, whether it be down fur or feathers, is reputed to be extremely durable, soft, and fashionable.\n\nThe great somnowls' feathers are particularly desirable. They don't shed often, and feathers are quickly retrieved by local wildlife for nest building.\n\nI've heard that your best chance is scouring the Meandering Rootlands in the Dream.", objectives = "Collect 10 Shed Great Feathers in the Emerald Dream.", progress = "Have you found any feathers? They're easy to identify. As large as two hands lengthwise, often snowy in color, and buttery soft.", completion = "Tailors from all over the world will be delighted to have these!" }
WordHunterWoW_QuestEN[77953] = { title = "A Sphere in Danger", description = "", objectives = "Here's the note they sent. Something to do with an orb? \n\nKathos had to run out to check on something, so you can bring the orb back to me. I'll make sure to hand it over upon her return.\n\nStay safe out there. Oh, and don't forget all of your useful tools!" }
WordHunterWoW_QuestEN[77954] = { title = "A Curious Orb", description = "<Tithris told you to return the orb to him in Valdrakken. He will pass it to Preservationist Kathos.>", objectives = "Return the Orb of Rathmus to Tithris in Valdrakken.", progress = "You got that orb for me? For Kathos, I mean.", completion = "Perfect. I'm sure Kathos will be mighty glad to see this. She said the orb will help your investigations.\n\nWhy, there she is right now! Glad to see her back safe. I'll hand over the orb soon as I'm done with getting something from the back.\n\nThanks for the hard work, <name>!" }
WordHunterWoW_QuestEN[77955] = { title = "Heated Hearthstone Hustle", description = "Wait, my hearthstone! I can't sleep without my hearthstone. \n\nA djaradin stole it during our last battle. It stays warm perpetually and I always sleep with it. \n\nI hate that I must ask more of you, but could you get my hearthstone? \n\nThe djaradin that stole it should be near Fyrakk's army, just north of here.", objectives = "Retrieve the Heated Hearthstone from the Stonewarmer.", progress = "My eyes grow tired, but my body is still awake...", completion = "Gah! I still can not fall asleep! I am embarrassed to ask but there is only one option left." }
WordHunterWoW_QuestEN[77957] = { title = "A Treacherous Race", description = "", objectives = "Bobby and I finally deciphered the tablets. They tell of an artifact of immense power that was locked away in Tyrhold. And I fear Tithris is after whatever that artifact is. \n\nYou must secure whatever the tablets speak of before Tithris. Bobby and I will find a guard and join you as soon as we can.\n\nTake our notes. There are many safeguards that you will need to get through to find the artifact's vault." }
WordHunterWoW_QuestEN[77958] = { title = "Sleepy Druid in Emerald Dream", description = "Why can I still not fall asleep, even with a heated blanket? \n\n<Thaalean curses the air then sighs.>\n\nThis is embarrassing to request, but my mother used to sing me a lullaby before I slept back in Teldrassil, may I ask you to do the same?\n\nAny lullaby will do, I just want to rest peacefully.", objectives = "Sing a lullaby for sleepy druid.", completion = "Thank you so much for checking on my friends. \n\nWhen they reawake, we will be ready to fight Fyrakk's forces once more." }
WordHunterWoW_QuestEN[77976] = { title = "Aiding the Accord: Dreamsurge", description = "A group of druids from across Azeroth have gathered to investigate a sudden surge in energies coming from the Emerald Dream.\n\nThis has the potential to affect us all, {name}. Please aid them in their endeavor to understand this new phenomena.", objectives = "Meet the druids investigating the Dreamsurge and gather one hundred Dreamsurge Coalescence. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", completion = "Thank you, <name>, for your assistance. We will have to keep a close eye on this Dreamsurge as it develops." }
WordHunterWoW_QuestEN[77977] = { title = "An Ominous Artifact", description = "<An orb would fit perfectly atop the console.>", objectives = "Secure the Orb of Rathmus as well as the artifact it is hiding.", progress = "A chest! Locked away in Tyrhold all this time. Can I examine it?", completion = "The text on top of this chest is definitely titan. But here, this is a language used by the Burning Legion! And this text is used by servants of the Old Gods. I've never seen these three languages being intermingled like this.\n\nI'm not fluent, but the titan text speaks of a danger within the chest. An item? Or perhaps just... knowledge.\n\nMy order will see that the chest is secured and studied. Thank you again, <name>. In my eyes, you're an honorary Preservationist at this point." }
WordHunterWoW_QuestEN[77978] = { title = "A Passed Torch", description = "<Strategic documents are scattered around Lyandris. Notes detailing experiments and future assault locations covering many of them.> \n\n<It would be of great use to your allies to find more of these documents. Thinning out the Flame's numbers wouldn't hurt either.>", objectives = "Collect documents and kill Druids of the Flame within the Smoldering Copse.", progress = "What is it?", completion = "Lyandris saved all this? And you... you finished what she started.\n\nThank you for returning her journal to me. Keep the documents. They will provide valuable information to you and your allies. \n\nThey would only be a grim reminder to me." }
WordHunterWoW_QuestEN[77982] = { title = "Greedy Gessie", description = "", objectives = "" }
