WordHunterWoW_QuestEN[77988] = { title = "Test", description = "Bronze whelps can be careless when trying to win, so be careful with the timeways!\n\n[Growth Spurt]: Tranform into an adult and gain improved speed.\n[Bedtime Rewind]: Restore 1 Vigor until all Vigor has been recovered.\n[Sacred Timeline]: Resets cooldowns.", objectives = "Help Zhusadormu glide through the rings." }
