WordHunterWoW_QuestEN[78002] = { title = "To The Test: Concentrated Sophic Vellum", description = "The Order and shadowflame magics are competing with each other. The enchantment will never be able to funnel Fyr'alath's power if we can't channel the excess Order magic being forced away from it.\n\nIf you can channel the enchantment, your allies can catch any excess Order magic.", objectives = "Return the excess Order magic to Shalasar's Sophic Vellum.", progress = "Don't give up. I know this is tough, but keep your goal in mind.", completion = "Hard work, but well worth it. Use this vellum well." }
WordHunterWoW_QuestEN[78003] = { title = "Handling It: Taut Tethercoil", description = "I've read of a root in the Emerald Dream known for its defensive qualities. It binds its tendrils to powerful foes as a way to protect surrounding flora and fauna. A friendly scribe might be able to help you adapt its properties.\n\nIf I could just get my hands on some of that root, I'm sure I could dissect its properties and mold it into something capable of harnessing Fyr'alath's power.\n\nHere are my notes. You should be able to find powerful creatures guarding patches of wild tethercoil. Good hunting.", objectives = "Collect Taut Tethercoil from powerful foes throughout the Emerald Dream.", progress = "Ah, thank you for bringing these to me.", completion = "I'm impressed! You're certainly tenacious.\n\nNow we can craft the base of our binding rune." }
WordHunterWoW_QuestEN[78015] = { title = "Firebrand Fystia", description = "", objectives = "" }
