WordHunterWoW_QuestEN[78033] = { title = "Magical Bloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[78040] = { title = "The Outland Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Valdrakken.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[78041] = { title = "Sky Mother's Ire", description = "We received reports that the Druids of the Flame have established another staging ground just south of the Eye of Ysera.\n\nUnfortunately for them, their incursion point has disrupted the local winged wildlife and drawn the ire of the Mother of Flight.\n\nSpeak with Aviana and lend her your aid. We will need her eyes and wings in the battle to come.", objectives = "Seek out Aviana.", completion = "I expected Cenarius would send some support eventually.\n \nBut this foolish, ground dwelling loa?\n\n<Aviana taps her talon in annoyance as she gives Q'onzu a side-eyed glare.>" }
WordHunterWoW_QuestEN[78042] = { title = "Aviana's Assessment", description = "<Aviana's eyes narrow as she watches the Druids of the Flame far below.>\n\nQ'onzu may be content with letting these heretics destroy the very fabric of the Dream, but I am not.\n\nBring me scraps of their armor stained with blood as proof of your deed.\n\nDo not hold back, {name}. Remember what these heathens are capable of.", objectives = "Collect 20 Bloodied Armor Scraps.", progress = "Every minute they are left uncontested, another portion of the Dream is lost to their heinous acts.", completion = "Actions speak louder than inquiries, champion.  \n\nRemember that the next time your prey invades your homeland.  \n\n<Aviana shoots a cruel side-eye towards Q'onzu. >" }
WordHunterWoW_QuestEN[78043] = { title = "Q'onzu's Quandary", description = "You again! Well, you must be here to help, correct? \n\nAbsolutely you are. Why would you not? This development is so exciting. What could these desolating druids be up to?\n\nFortunately, a few of my friends have infiltrated the druids. I'm sure they have quite the story to tell. \n\nGo forth, my curious companion and bring back exciting news!", objectives = "Speak to the Flame-Disguised Dreamkin to gather intel on the Druids of the Flame.", progress = "Change has come to the dream and yet we are so quick to snuff it out.\n\nHow unnaturally boring.", completion = "Well now, this IS interesting, isn't it?\n\n<Q'onzu shudders as they tap their feet rapidly in excitement.>\n\nYou must be fascinated by this too, <name>? \n\nOh, how silly of me. Of course you are!" }
WordHunterWoW_QuestEN[78044] = { title = "Appalling Pollen", description = "This cinder pollen doesn't evoke interesting change. It consumes all until nothing, but ash remains. It brings... uniformity.  \n\nAnd I find that to be tragically stale. \n\nI'm all for change, no matter the origin. But if THIS change stymies all future possibilities for further change, then it must be stopped. \n  \nIf creatures of the dream have been infected by this pollen, then they must be extinguished. This is not a flame that can be allowed to grow.", objectives = "Reveal and kill 10 Cinderpollen Beasts.", progress = "Bringing about change to the dream through fire is a fascinating concept - life and fire can coexist! \n\n<Q'onzu's expression hardens as they shudder.> \n\nBut this change is not that.", completion = "Imagine the lengths these agents of monotony had to go to in order to get me -- ME, THE LOA OF CHANGE -- to interfere with their dream-changing plot? \n \nThe absolute gall!" }
WordHunterWoW_QuestEN[78045] = { title = "Uproot the Cause", description = "<Aviana's gaze remains locked on Q'onzu for a moment, her brow furrowed.> \n \nWhile I don't see eye to eye with Q'onzu's fascination for change, their incessant inquiry has unveiled a more deep-seated plot than originally suspected. \n\nPutting down the wildlife won't mean much if we don't tear out the root of the cause.  \n \nLocate the burning ashphodels in the glade below and tear them out.", objectives = "Collect 8 Uprooted Ashphodels.", progress = "If the ashphodels are allowed to spread their foul pollen unchecked, then the rest of the dream is in grave danger. \n\n<Aviana grimaces.>", completion = "Well done, <name>.  \n \nI'll ensure Cenarius is made aware of the damage these weeds have inflicted. A few dryads should be able to clear up any remaining pollen or flowers you might have missed. \n \n \n \nAll but one task remains now, Champion." }
WordHunterWoW_QuestEN[78046] = { title = "Overseer Oversight", description = "Those research notes you brought Q'onzu made mention of the ones behind these foul experiments.  \n \nThe overseer, the one named Chardryn, has been under our noses this whole time. \n\nHe oversees their research station below us.  \n \nIf we are to permanently end their terrible experiments and disrupt their progress, then he must be made an example of.", objectives = "Slay Overseer Chardryn.", progress = "If Chardryn and his insane herbologists are allowed to carry out biological warfare here in the dream, then Amirdrassil and all of Azeroth is at risk.\n\nWe cannot allow these sycophants of fire to remain alive.", completion = "Their overseer is dead then? \n \n<Aviana gives you a curt nod of approval.> \n \nGood. \n\nWith Chardryn gone, their experiments destroyed and their research brought to a halt, let us hope this is the end of their twisted schemes." }
WordHunterWoW_QuestEN[78047] = { title = "The Outland Cup Circuit", description = "It is time once again to test your mettle.\n\nMy bronze colleagues have traveled to Outland to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit!\n\nAre you up to the task?", objectives = "Fly through Outland Cup courses.", progress = "Have you taken wing today?", completion = "You lead the way among your fellow dragonriders! If you haven't already, see if you can improve your times in the Outland Cup and earn the colors of the Riders of Azeroth." }
WordHunterWoW_QuestEN[78064] = { title = "Q'onzu's Perception", description = "You have many questions and I have many worries. \n\nSuch pressing worries. An interloper, a rude disrupter of our joyous day. How I worry so. If only someone could confront this trespasser.\n\nWait, you could do it for me! It's a win-win, you go confront the trespasser and I answer your questions. I've tracked them down to a cave in the north. Surely you can handle them.", objectives = "Find and confront the interloper in Q'onzu's nest.", progress = "I can sense the interloper causing a disturbance in my nest!", completion = "Ha! Oh, come now. That was funny. Don't look so cross." }
WordHunterWoW_QuestEN[78065] = { title = "The Q'onzu Query", description = "Champion, I understand we were unable to convince Q'onzu to join us. However, we need all the aid we can gather.   \n\nYou must discover why they refuse to aid us and convince them of the right path. Q'onzu and I have a rather strained relationship. Your efforts could bear more fruit. \n\nI hear Q'onzu has built a nest near Shiversnap Grove. Would you go and approach them?", objectives = "Approach Q'onzu again and ask what they've been up to.", completion = "Q'onzu said a visitor would come. Baring offerings, I hope?" }
WordHunterWoW_QuestEN[78066] = { title = "The Answers You've Earned", description = "Ah, that's much better. Now I can think.\n\nWhat did you want, again? Oh yes! Questions. \n\nAsk away, if you must.", objectives = "Get answers about Q'onzu.", completion = "<Q'onzu and their followers have gone. This must be the answer they deemed you deserved.\n\nFor now, at least.>" }
WordHunterWoW_QuestEN[78068] = { title = "An Artificer's Appeal", description = "{name}, I received an item for you from Grand Artificer Romuul.\n\nRomuul wished for you to listen to the message before proceeding to the Exodar.", objectives = "Meet Grand Artificer Romuul in the Exodar.", completion = "My apologies for bringing you here on such short notice, <name>, but your help right now would be most appreciated.\n\nI have found myself with many surprise deadlines.\n\n\"Surprise\" and \"deadlines\" are not words I like together in the same sentence." }
WordHunterWoW_QuestEN[78069] = { title = "Reviving Tradition", description = "The Prophet wished to personally ask for your help with the Tishamaat. But since he is working elsewhere, I asked you first to jumpstart our task.\n\nMy colleague and I have been working on a special project. And since the Prophet has declared today the Tishamaat, we will unveil it at the celebration!\n\nFor this, I need the emitter, but it needs an overhaul. We only have time for a hot wiring.\n\nGet some filament and a soldering tool from the crates nearby, {name}. Then maybe I can wire it to an array.", objectives = "Help Romuul finish repairing the Holographic Emitter.", progress = "I regret not having apprentices in times like this.", completion = "<Romuul gives the newly seated crystal a test wiggle.>\n\nNot my finest work, but it will do.\n\nLight willing, it will remain functional until our project is revealed and the celebration is over." }
WordHunterWoW_QuestEN[78070] = { title = "Pressing Deadlines", description = "During this Tishamaat, Ataanya and I will present our project's schematics.\n\nAtaanya is High Artificer of Shattrath. Her father was my late mentor, the famed Exarch Hataaru.\n\nHataaru's hoofplates are hard to fill, but Ataanya has more than done so.\n\nShe has the schematics, and she should be here when they are presented. But she is not responding to my messages.\n\nAtaanya seldom leaves the city, but surely she can make an exception for the Tishamaat. Perhaps you can reason with her.", objectives = "Speak to Ataanya in Shattrath City.", completion = "I have a data crystal prepared. The schematics are on it.\n\nMy apprentice can find it for you.\n\nI have no time to leave Shattrath." }
WordHunterWoW_QuestEN[78071] = { title = "Rush Order", description = "My schematics speak for themselves.\n\nEach calculation has been verified. It is respectful of all building codes. I even included a layout of the channels that the power grid must follow.\n\nRomuul knows the project. He already signed off on everything. He can explain it to the masses himself.\n\nI do not need to waste my valuable time traveling to the Exodar for this ridiculous holiday.\n\nMy apprentice will give you the schematics on a data crystal. Take it and leave.", objectives = "Speak to Beruun. Perhaps he knows a way to convince Ataanya to leave Shattrath.", progress = "We will do what we can for Ataanya.", completion = "Hm, it was worth a try.\n\nIt seems it will be difficult to get her to the Tishamaat...\n\nBut I have another idea." }
WordHunterWoW_QuestEN[78072] = { title = "An Old Wound", description = "<Beruun whispers to you.>\n\nThere are ways, I'm sure you know, for the draenei to speak to the dead.\n\nIt's not the same as having a loved one back but...\n\nHataaru's ashes were taken to Auchindoun after the soulpriests reclaimed the temple. Maybe they might know a way to help Ataanya with her loss?", objectives = "Speak to the soulpriests at Auchindoun.", completion = "It is good to have visitors!\n\nThe honored dead here are well-cared for, but not many travel to commune with them.\n\nTheir deaths can be a painful reminder of what the <race> have endured." }
WordHunterWoW_QuestEN[78073] = { title = "Lingering Scars", description = "I believe we may be able to help.\n\nBut perhaps you could aid me first...\n\nWhen we received word that the Tishamaat was upon us, we hurried to prepare our most tortured spirits for the journey to the Exodar. The celebration's sacraments may help them rest peacefully.\n\nHowever, they must consent to being moved. So, we must commune with and soothe them first.\n\nWill you help calm these spirits? Afterward, I will take you to where Hataaru is entombed and give you what you seek.", objectives = "Help Exarch Maladaar commune and soothe the spirits of Auchindoun.", progress = "Your kindness may help these spirits find peace in death.", completion = "Thank you for what you have done, <name>.\n\nMoving a spirit's remains can disturb them greatly, so they must be calmed as much as possible so the journey can be made safely." }
WordHunterWoW_QuestEN[78074] = { title = "To See Clearly", description = "Fortunately, not all of the fallen entombed here in Auchindoun suffer as these three do. Some ease gracefully into death, like soil settling after a rainfall.\n\nExarch Hataaru is one such soul. Thanks be to the Light that he rests easy.\n\nCome, I will show you to his tomb.", objectives = "Visit Exarch Hataaru's tomb and then return to Ataanya in Shattrath.", progress = "<Ataanya crosses her arms tightly, not looking at you or Beruun.>", completion = "... Fine.\n\n<For a moment, she looks like she might snatch the lens from you. Instead, she takes it from you gently.>" }
WordHunterWoW_QuestEN[78075] = { title = "Moving Past", description = "My mother died on a colony planet. My father and I helped each other move past that, but when he died in the siege of Shattrath, watching the walls of his greatest accomplishment crumble to dust... \n\nThere was no one left for me.\n\nSo I worked. And now I have the schematics of my own Shattrath. A better Shattrath.\n\n<Ataanya clenches the lens in her fist then exhales in resignation.>\n\nI'll go to the Exodar--but if Romuul says one word about it, I will make him eat his soldering tool.", objectives = "Return to Grand Artificer Romuul in the Exodar.", completion = "In some ways, getting Ataanya here was a more difficult victory than the fall of Antorus.\n\nLevity aside, I am glad she is here. I knew the Tishamaat would be hard for her. Her father was a great man, and we all mourn his passing.\n\nThis Tishamaat is gearing up to be one for our holo-records! \n\n<Romuul lowers his voice confidingly.>\n\nEven Hatuun is here!" }
WordHunterWoW_QuestEN[78076] = { title = "Emergency Efforts", description = "{name}! Velen told me I may find you here. He needs your assistance.\n\nThe satyr that infest a nearby island have been ambushing draenei traveling for the Tishamaat.\n\nVelen and I have been attempting to solve the problem quietly. He does not wish to mobilize the vindicators and alarm his people on a day of sacrament.\n\nBut, despite our efforts, the attacks have continued. The event may need to be canceled if we cannot get the demons under control.\n\nCome with me so we may end this threat.", objectives = "Use the Argussian Mana Ray to fly to Bloodmyst Isle with Chieftain Hatuun.", completion = "I was hoping to resolve the sudden satyr attacks before I formally announced the Tishamaat to all...\n\nAlas, I am grateful Romuul called you to the Exodar early.\n\nI assume Hatuun has explained the situation to you?" }
WordHunterWoW_QuestEN[78077] = { title = "Beneath the Skin", description = "Arzaal and I are of the same mind. We must know the strength of these satyr before we attempt to drive them back with force. Else we may be walking into a fight we cannot win.\n\nI can learn much about my enemies by observing what damage they leave in their wake. \n\nThe wildlife here was corrupted by the Exodar's lingering energies, but I suspect the demons' presence made it worse.\n\nCollect bones from the local wildlife for me. Studying them may give us some clues.", objectives = "Collect 8 Pitted Bones from corrupted wildlife.", progress = "Remember, you are putting them out of their misery.", completion = "<Hatuun snaps one of the bones, then sniffs the frothing marrow tentatively and frowns.>\n\nLesser demons do not corrupt creatures this deeply. Their fel disease can barely spread beneath the skin, much less the bones or the soul.\n\nThese are no weak imps we are dealing with." }
WordHunterWoW_QuestEN[78078] = { title = "Assessing the Enemy", description = "The Legion may be one entity, but it is vast. The demons that comprise it are as varied as the innumerable worlds they have conquered.\n\nBut I have had no dealings with satyr. From what the Prophet has told me, they seem disorganized. Intelligent certainly, but feral in their malevolence.\n\nI am inclined to believe their recent attacks are random, but perhaps not. Bring me the totems they have scattered across Bloodmyst. I may be able to ascertain what, if anything, their end goal is.", objectives = "Collect 6 Satyr Totems.", progress = "I would prefer to know the capabilities of the satyr before engaging them.", completion = "Curious.\n\nThese crystals appear similar to the others erupting from Bloodmyst, but their placement on these totems seems deliberate.\n\nI will study them further." }
WordHunterWoW_QuestEN[78079] = { title = "Excision", description = "I cannot in good conscience gather the draenei for the Tishamaat if we are threatened this close to home.\n\nIf one of the man'ari is using the satyr to orchestrate these attacks, or to distract us from some larger foul purpose, then they must be rooted out immediately.\n\nWe will divide our efforts to look for signs of the enemy. Arzaal will search the northern satyr camp. You, Hatuun, and myself will search the closer camp.", objectives = "Meet Velen and Hatuun in Nazzivian to search for signs of man'ari presence in the area.", completion = "We did not find the man'ari responsible. But when we do, they will pay." }
WordHunterWoW_QuestEN[78080] = { title = "At the Source", description = "Can you hear that? The silence? \n\nThe area is empty. Not even the rabid wildlife dare approach the camp.\n\nI do not see any immediate cause, but the fel resonance here is overwhelming. I sense it was woven by man'ari hands, but I'm being blocked from probing more deeply.\n\nSomething is being hidden.\n\nIt must be the cloaking magic Hatuun reported from the other camp that hinders me. I can dispel it, but I cannot guarantee what we will find when I do.", objectives = "Discover the source of the fel concentration in Axxarien and destroy it.", progress = "This ends here!", completion = "It is done.\n\nI could not have imagined the threat in Bloodmyst had grown this dangerous.\n\nThank the Light that I chose to bring Hatuun and Arzaal here. This could not have been done without them--without all of us." }
WordHunterWoW_QuestEN[78081] = { title = "Pain Recedes", description = "With Sironas slain once again, Bloodmyst will finally be able to heal. Her influence was no doubt anchoring the corruption to the land.\n\nIt is another reason to celebrate today. But it is not the true reason I called Hatuun and Arzaal to Azeroth.\n\nI would have them attend the Tishamaat with us.\n\nThe sacrament asks us to reflect on the past and commit to a better future. The unity of our efforts epitomizes that.\n\nI will bring them to the Exodar. Please join us when you are ready.", objectives = "Meet with Prophet Velen in the Exodar.", completion = "It brings me great joy to see the eredar gathered together at last." }
WordHunterWoW_QuestEN[78082] = { title = "A Burden Shared", description = "The Tishamaat was once a solitary holiday. Each eredar would inscribe a stone with a painful memory we carried. We would reflect on what that memory could teach us then commit to moving forward with that wisdom.\n\nAt last, the stones are dissolved in the Flame of Reprieve, symbolically removing the weight from our souls.\n\nToday, the Tishamaat will be celebrated not in solitude, but as a community.\n\nGather the stones of those who would trust you with them then take them to the flame.", objectives = "Collect 10 Memory Stones, create your own Memory Stone, and then dissolve the stones in the Flame of Reprieve.", progress = "For many, this is the first Tishamaat they have participated in. For others, it is a distant memory.", completion = "The <race> have suffered, scattered and solitary, for too long.\n\nToday, we allow ourselves to rely on each other." }
WordHunterWoW_QuestEN[78083] = { title = "Our Path Forward", description = "Ah, I believe I hear the Prophet calling the attendants before the stage.\n\nI am curious to see what he and Romuul plan to announce now that everyone is gathered.\n\nWe should make haste, yes?", objectives = "Speak to Prophet Velen to begin the ceremony.", progress = "The future is ours.", completion = "Today marks the beginning of a new age for the eredar.\n\nWe are one people united in purpose.\n\nAnd we will never be broken apart again." }
WordHunterWoW_QuestEN[78097] = { title = "Sparks of Life: Emerald Dream", description = "Follow the essence into the Emerald Dream and see what you may explore, but beware of foes who may cross your path.", objectives = "Collect 100 Sparks of Life in Emerald Dream, while in War Mode.", progress = "Guard against immoral foes.", completion = "Well done!" }
WordHunterWoW_QuestEN[78102] = { title = "Canopy Concours", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[78103] = { title = "Canopy Concours - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[78104] = { title = "Canopy Concours - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
