WordHunterWoW_QuestEN[78444] = { title = "A Worthy Ally: Dream Wardens", description = "So much change to that which should be unchanging... \n\nRarely has the Dream seen such turmoil. It is meant to be a place of peace. Of life. \n\nChampion, we need all the help we can get. I bid you go forth and bring aid to the expanse of the Dream.\n\nI have no doubt the Dream will share its plenty with you in return.", objectives = "Aid the Dream Wardens and their allies throughout the Emerald Dream.", progress = "Do take some time to stop and smell all that blooms throughout the Dream. It will enrich your life.", completion = "<Keeper Amrymn takes a deep breath.> \n\nThe air has gone calm. Peace returns to the Dream, even if slowly.\n\nAll who keep and defend this place thank you, hero." }
WordHunterWoW_QuestEN[78446] = { title = "Aiding the Accord: Superbloom", description = "As life blooms within the Emerald Dream, the budding World Tree Amirdrassil blooms with it. \n\nThe Ancient Sprucecrown's ritual empowers mighty life energies all around the tree, encouraging its growth. The more hands there to help protect and nourish Amirdrassil, the better its bloom will be! \n\nPlease lend your aid to Sprucecrown on his journey.", objectives = "Travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "I do hope you don't suffer from allergies.", completion = "Ah, I can almost smell the flowers on the wind from here!\n\nPlease accept this humble gift, along with our gratitude." }
WordHunterWoW_QuestEN[78447] = { title = "Aiding the Accord: Emerald Bounty", description = "The Emerald Dream suffers at the forces of the Incarnate Fyrakk. In its turmoil, some of its seeds have trouble taking root. \n\nIn exploring the Dream, I am certain you shall collect some special seeds. Plant them in soil and nourish them into a bloom, and I hear they will share bountiful gifts with you.\n\nGo forth and help life blossom in the Emerald Dream!", objectives = "Travel to the Emerald Dream and plant 3 Dreamseeds of any quality in Emerald Bounty soil. Dreamseeds can be acquired from most activities in the Dream. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "I wonder what gifts a flower can bestow?", completion = "The Dream is such a strange place!\n\nPlease accept this humble gift, along with our gratitude." }
WordHunterWoW_QuestEN[78452] = { title = "Reinforcements - Activate", description = "", objectives = "" }
WordHunterWoW_QuestEN[78454] = { title = "Dragonblight Dragon Flight", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
