WordHunterWoW_QuestEN[78589] = { title = "Invasive Cuisine", description = "<This rarely seen plant may be of use to Chef Dinaire.>", objectives = "Deliver the Umbral Eggplant to Chef Dinaire at the Fungal Fields.\n\nProvided item:", completion = "Umbral Eggplant might not be everyone's idea of a delicious food, but when I prepare it, it is a crowd favorite!" }
WordHunterWoW_QuestEN[78590] = { title = "Cutting Edge", description = "", objectives = "" }
WordHunterWoW_QuestEN[78591] = { title = "Getaway to Scenic Nagrand!", description = "Today's special is a magical getaway to the great plains of Nagrand!\n\nIf you're headed there, would you mind shooting a few animals? Oh, not like that! Here, borrow my camera.\n\nMy friend Beatrice has been roaming around there lately. She would really appreciate some photographs, but I've got portals to attend to.", objectives = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Beatrice.", progress = "There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", completion = "I knew Beatrice would appreciate your photographs.\n\nThank you for your kindness, <name>." }
WordHunterWoW_QuestEN[78594] = { title = "Getaway to Scenic Feralas!", description = "Today's special is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited!\n\nUnfortunately, some of the partygoers who took this portal earlier left their gifts here at the gala.\n\nCould you help me return them? Meet me at the beach and we'll figure out which gifts belong to whom.", objectives = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients.", progress = "There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", completion = "Thanks for the assistance, <name>! You've made a lot of people happy by getting their gifts back to them.\n\nAnd what an array of gifts they were! Maybe the language of love looks different to everyone." }
WordHunterWoW_QuestEN[78595] = { title = "Dream Infused", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, your deeds have helped garner enough strength for a dream infusion! Meet me at the Central Encampment so I can get it to you.\n\n- Elianna", objectives = "Talk to Elianna in the Central Encampment.", completion = "Infuse away!" }
WordHunterWoW_QuestEN[78596] = { title = "Summons to Lord Greymane", description = "Greetings, \n\nLord Greymane has requested your presence at Stormwind Harbor to assist him with a matter regarding Gilneas.\n\nThat is all I am able to say.\n\nGood luck, {name}.", objectives = "Meet with Genn Greymane at Stormwind Harbor.", completion = "<name>, thank you for coming.\n\nLet me brief you on the mission." }
WordHunterWoW_QuestEN[78597] = { title = "Clandestine Movements", description = "{name},\n\nLilian Voss and Calia Menethil have requested your presence for a clandestine operation involving Gilneas.\n\nThey will brief you in full when you arrive.", objectives = "Meet with Lilian and Calia in Pyrewood Village in Silverpine Forest.", progress = "Excellent, we've been waiting for you.", completion = "<name>, thank you for coming.\n\nLet me brief you on the mission." }
WordHunterWoW_QuestEN[78598] = { title = "Dream Infusion", description = "", objectives = "Your contributions have helped us harness enough power for another Dream Infusion! Great work." }
WordHunterWoW_QuestEN[78600] = { title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", objectives = "Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Normal difficulty.", progress = "The energy found within these fragments will allow us to quickly access the Throne of the Firelord.", completion = "These should grant us access to Smolderon's throne more easily." }
WordHunterWoW_QuestEN[78601] = { title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", objectives = "Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Heroic difficulty.", progress = "The energy found within these fragments will allow us to quickly access the Throne of the Firelord.", completion = "These should grant us access to Smolderon's throne more easily." }
WordHunterWoW_QuestEN[78602] = { title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", objectives = "Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Mythic difficulty.", progress = "The energy found within these fragments will allow us to quickly access the Throne of the Firelord.", completion = "These should grant us access to Smolderon's throne more easily." }
WordHunterWoW_QuestEN[78607] = { title = "To Mereldar", description = "We must get to Mereldar and let General Steelstrike know what the Order of Night tried here.\n\nThank the Sacred Flame we stopped them before they could do any worse.", objectives = "Travel to Mereldar and meet with General Steelstrike.", completion = "Finally, a chance to rest." }
WordHunterWoW_QuestEN[78608] = { title = "Geothermal Jaunt", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[78609] = { title = "Geothermal Jaunt - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[78610] = { title = "Geothermal Jaunt - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[78613] = { title = "The Bastion of Hallowfall", description = "I have to admit, I did not think that the first visitors we'd have in Mereldar would have been outsiders. I thought the Empire... Well, nevermind.\n\nYou have been more than helpful to my people, and that deserves recognition. Mereldar is the bastion of the Arathi in Hallowfall. Take some time, rest.", objectives = "Explore Mereldar.", progress = "This city has much to see.", completion = "It's been good to sit down and breathe for a bit." }
WordHunterWoW_QuestEN[78614] = { title = "Mereldar's Light", description = "I still need more time with Alleria to learn about Xal'atath. What I have learned is very worrying.\n\nFaerin sent word that she was going to the orphanage, and asked you to meet her there. \n\nShe often entertains the children while she is in Mereldar, I don't doubt she would appreciate you doing the same.", objectives = "Play with 3 Arathi Orphans.", progress = "It's great to see how happy these kids are, after what they have gone through.", completion = "I love coming here whenever I visit Mereldar. The kids always bring a smile to my face, and I hope I do to them as well. \n\nAfter everything they have been though, they deserve happiness." }
WordHunterWoW_QuestEN[78615] = { title = "The Bell Tolls", description = "Those bells mean Mereldar is under attack! \n\nLet's get to the gates and find out what is going on.", objectives = "Go to the main gates of Mereldar in Hallowfall.", completion = "We will make them pay for this, <name>. \n\nWe will hit them so hard they never come back." }
WordHunterWoW_QuestEN[78616] = { title = "Technoscrying: The Mysteries of the Concord Observatory", description = "", objectives = "" }
WordHunterWoW_QuestEN[78618] = { title = "Fungal Frenzy", description = "", objectives = "" }
WordHunterWoW_QuestEN[78620] = { title = "Crossroads of Twilight", description = "We need to take the Veneration Grounds back from the kobyss. \n\nPush them back and pave a bloody path through them.\n\nWe need to stop whatever is happening at the Eternal Flame! If they manage to corrupt it like they did at the tower... I don't even want to imagine what will happen.", objectives = "Kill 15 kobyss attackers in the Veneration Grounds in Hallowfall.", progress = "Flames, they just keep coming.", completion = "Now we just need to deal with the shield." }
WordHunterWoW_QuestEN[78621] = { title = "The Shadow Rising", description = "I can sense three beacons of void ahead, all funneling their power into one massive font of darkness.\n\nYou will need to kill them. With them dead, I can bring down the shield.", objectives = "Kill the kobyss deepspeakers in the Veneration Grounds in Hallowfall.", progress = "I'm ready to end this.", completion = "Excellent. \n\nNow to break through this shield." }
WordHunterWoW_QuestEN[78624] = { title = "A Candle in the Dark", description = "Beledar has turned to Shadow, we must retreat back to Mereldar!\n\n<Vaelisia looks towards Aelric Leid.>\n\nI-- No. We need to destroy Aelric first.\n\nTake him down, then we retreat.", objectives = "Kill Aelric Leid in the Veneration Grounds in Hallowfall.", completion = "May the Light bless Faerin. \n\nI thought the Eternal Flame lost. \n\nI thought this was the end of hope, and the death of our people." }
WordHunterWoW_QuestEN[78626] = { title = "Spar Day", description = "Your skills in combat are impressive, {name}. \n\nWe are rotating our next round of reserves into active duty, and they need to sharpen their skills. \n\nWhile Alleria fills me in on Xal'atath, I would appreciate it if you could help with their training.", objectives = "Duel 8 Arathi Recruits in Mereldar.", progress = "The tricks they learn from you today will help them survive a difficult encounter later.", completion = "Thank you.\n\nWhat they learnt from you will no doubt save their lives later." }
WordHunterWoW_QuestEN[78627] = { title = "The Final Front", description = "Just before the kobyss attacked, we received word of a disturbance near Livia's Patience. Now we know the cause.\n\nWe... Light... We can't survive fighting on two fronts, {name}. We have to stop this, now.", objectives = "Travel to Light's Redoubt in Hallowfall.", completion = "Flames, they tunnelled up through the lake bed.\n\nLivia's Patience has already fallen." }
WordHunterWoW_QuestEN[78628] = { title = "Trapdoor Sprung", description = "We need time to get the Reckoning ready. Take your friends and hold back the nerubians for as long as you can.\n\nThey deserve nothing but death for what they have done to our people.", objectives = "Kill 15 nerubians in Livia's Patience in Hallowfall.", progress = "How goes the hunt?", completion = "Good job, <name>. I'm surprised the nerubians aren't fleeing already!" }
WordHunterWoW_QuestEN[78629] = { title = "Running on Reserves", description = "We have to try to save any of our people left alive in Livia's Patience. \n\nEvery Arathi is or was a member of the military. If you can help them, they'll be able to help themselves.", objectives = "Assist 5 Arathi Reserves in Livia's Patience in Hallowfall.", progress = "I managed to rescue a few, did you find people to rescue?", completion = "Thank you, <name>. Between myself, Alleria, Anduin, and you, I think we managed to save quite a few. \n\nThe nerubians abducted many of the rest. We need to help them!" }
WordHunterWoW_QuestEN[78630] = { title = "The Rise of the Reckoning", description = "The Reckoning is ready!\n\nLet's make these spiders pay. Blood for blood.", objectives = "Board The Reckoning and slay 150 nerubian forces.", progress = "We will make the nerubians regret ever thinking they could push into our home!", completion = "What fools we are." }
WordHunterWoW_QuestEN[78631] = { title = "Speaking to the Speakers", description = "I've heard about a problem nearby, and I think I know what's wrong.\n\nWe used to have a mining operation northeast of Gundargaz. When we moved out, kobolds moved in.\n\nWe haven't heard from those kobolds in a long time, but it sounds like they're raiding us now! And the High Speaker is doing nothing about it.\n\nSomeone has to do something. If we can solve this, more Machine Speakers will listen to us. If the High Speaker doesn't get results, we will.", objectives = "Reassure Gundargaz' defenders on the way to the Lost Mines.", completion = "It's good to see some of the kobolds are not so keen on this war." }
WordHunterWoW_QuestEN[78634] = { title = "Leave No Stone Behind", description = "Many earthen fell when the kobolds took this mine.\n\nWorse, those who fell were left to crumble where they dropped. There was no attempt to recover them. We couldn't provide closure or respect their memories. Why? Why did we forsake the fallen?\n\nWe will not fail them again, {name}. Gather the identification plaques of those we lost, so we may commemorate them properly.", objectives = "Recover Identification Plaques from fallen earthen in the Lost Mines.", progress = "Have you found them?", completion = "Thank you, <name>. The fallen will be remembered.\n\nThe earthen above us have their own rituals of remembrance, and the Machine Speakers have procedures in place. \n\nThere's a plinth in the town square with the plaques of the fallen. Jurlax will ensure that the proper observances are performed... along with process checks and a recalculation of worker allocation. Work never stops here." }
WordHunterWoW_QuestEN[78635] = { title = "Death and Waxes", description = "Kobolds take candles seriously. Wax, even more. More important than gold. More important than freedom!\n\nWe steal candles from Candle King. We make him look weak. Bully that looks weak loses control. Gets dead!\n\nAlso means we not have to wait out here in dark until get eaten. Hurry!", objectives = "Recover Flickerflame Candles from around the Lost Mines.", progress = "Did you take candle?", completion = "<Skitter visibly relaxes in the presence of the candles.>\n\nAh, good. Now get me out of this!" }
WordHunterWoW_QuestEN[78636] = { title = "Retaking the Mines", description = "Now that we have the keys, it is time to take the fight to the Candle King.\n\nGet that gate open. Once we're inside, we'll move on to the next step.", objectives = "Unlock the gate to the Lost Mines.", completion = "That...did not go as expected.\n\nOur new kobold friend might have some better ideas." }
WordHunterWoW_QuestEN[78637] = { title = "Cracking Cogchewer", description = "Cogchewer is muscle for Candle King. So mean! Rebuilds earthen gears for wars. Also in charge of mine's defenses. \n\nNeed his keys to get in the mines... and get me out of this thing!", objectives = "Kill Cogchewer in the Lost Mines and recover his keys.", progress = "Did you find keys?", completion = "Thank you, <name>. Never thought I walk free again." }
WordHunterWoW_QuestEN[78638] = { title = "Engineering Destruction", description = "Some of the kobolds are retrofitting equipment left behind when the mines fell.\n\nPlease, destroy the rigs before they're used against us. I'd rather they be scrap than in the hands of an enemy.\n\nThere was a storage depot on the western edge of the lowest level of the mine. Start there.", objectives = "Destroy mining rigs in the Lost Mines.", progress = "Are any still operable, <name>?", completion = "Thank you. Our enemy now has one less advantage." }
WordHunterWoW_QuestEN[78639] = { title = "Ko-boldening", description = "Bullies everywhere!\n\nInnocent kobolds kept down by Candle King's thugs all across Warrens.\n\nGive bullies taste of own medicine!\n\nOnce bullies beaten, innocent have chance to run. Be free!", objectives = "Free oppressed kobolds in the Warrens by defeating their captors.", progress = "Now they will see what it feels like!", completion = "Is start, friend. Is start. Thank you." }
WordHunterWoW_QuestEN[78640] = { title = "Manifesto Destiny", description = "Before take mines, my people live in great city. Stoneheads call it the Warrens.\n\nCandle King's bullies run it now. We need see what we are fighting. Let kobolds know we here to help! Better choices than Candle King.\n\nWhat better way than pamphlets? Everyone love pamphlet! We draw real good!\n\nBrinthe say you have some sort of flying dragon-bird-thing? Perfect for scout! Perfect for dropping pamphlets!\n\n<Skitter looks at you expectantly, making small flapping motions as she waits.>", objectives = "Scout out and distribute pamphlets across the Warrens from the air.", progress = "Never flown before. Is fun?", completion = "Sad to see home in such state.\n\nBut we fix!" }
WordHunterWoW_QuestEN[78641] = { title = "Tackling Torchsnarl", description = "Torchsnarl runs Warrens for Candle King. Nothing but big bully! Very, very big bully.\n\nWe show everyone. Bullies can be beaten!", objectives = "Defeat Torchsnarl in the Warrens.", progress = "Torchsnarl is big one. Don't know why hiding behind flunkies. Still, can't miss him!", completion = "Sad he got away, but everyone else? See him as coward! Just as good.\n\nI'm tall, so I use words good. He's huge! He should use words gooder! Not very smart." }
WordHunterWoW_QuestEN[78642] = { title = "New Candle, New Hope", description = "We weaken Candle King's grasp. Still need symbol, rally my people.\n\nKing has ancient relic: symbol of hope. Called Candle Crown. Heart of my people. Candle King threw away! Found new prize: Darkflame Candle.\n\nThat crown? Still in hoard. Candle King should come out now. See what we did here!\n\nWhile he looks, we sneak in! Use old tunnels! Take what's ours! We smart.", objectives = "Recover the Candle Crown from the Darkflame Cleft.", progress = "We take hope from darkness, <name>.", completion = "Ha! We did it! Everyone knows now: Candle King is not only way." }
WordHunterWoW_QuestEN[78643] = { title = "Fair Skies and Strong Winds", description = "It has been a long road for us all, {name}.\n\nBut after persevering through hardship and strife, dragonkind stands poised to enter a new age.\n\nBefore you leave for your next adventure, my fellow Aspects and I wish to thank you for all you have done for us.", objectives = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken.", progress = "The Dragon Isles stand in your debt.", completion = "Fair skies and strong winds to you, <name>." }
WordHunterWoW_QuestEN[78645] = { title = "Excavation: Buried in the Riverbed", description = "", objectives = "" }
WordHunterWoW_QuestEN[78646] = { title = "Fire Watch", description = "My mother seems unable to fully attune with the Eye. Perhaps it senses her ties to Ardenweald...\n\nHer shield is but a fraction of the Eye's power. If she was fully attuned, she could completely quench our foes' flames.\n\nBut we cannot idly wait. We still need more information about Galok and his plan of attack. Bodwin indicates there is new flurry of activity in Igira's base of operations. With Bodwin's help, we can investigate without being seen.", objectives = "Regroup with Merithra at the edge of Eye of Ysera, overlooking Slagfell Hold.", completion = "This will not be easy..." }
WordHunterWoW_QuestEN[78649] = { title = "Excavation: Something Big Beneath the Riverbed", description = "", objectives = "" }
WordHunterWoW_QuestEN[78655] = { title = "Adaptive Cooling Salve", description = "Should you need my assistance, I can craft you an ointment that should prove helpful in your attunement with Fyr'alath.\n\nBring me the materials I don't have, and I'm sure I can put something together.", objectives = "Bring ErdenZaralek Glowspores, Awakened Frost, and a Dreaming Essence for the Adaptive Cooling Salve.", progress = "Keep at it. All this hard work is going to pay off.", completion = "Perfect." }
WordHunterWoW_QuestEN[78656] = { title = "Hose It Down", description = "With the flame restored, you can see the extent of contamination to the fishing hole. Kobyss and frogs have left heaps of strange goo that pollutes the shoreline.\n\nWe need your help to clean up this gooey blight! \n\nI have a specially modified harvester equipped with a water barrel. Use this device to spray water on the goo piles and clean the shore of this contamination.", objectives = "Activate Baeny the Barrel and use the hose to wash away 40 Contaminating Goo.", progress = "Have you cleaned up the shoreline?", completion = "Great work <name>, things will be a lot less messy around here now!" }
WordHunterWoW_QuestEN[78657] = { title = "The Midnight Sentry", description = "", objectives = "" }
WordHunterWoW_QuestEN[78658] = { title = "The Hallowed Path", description = "{name}, I'm glad our paths have crossed. Adelgonn has been telling me about a cavern called Hallowfall.\n\nShe's told me the people there are called the Arathi. I cannot imagine that they are related to the ancient human kingdom, but it can't be a coincidence.\n\nAdelgonn's people had fruitful contact with them some time ago. Whatever happened, I hope to repair that relationship and gain their aid. Please meet me at the Hallowfall Gate.", objectives = "Meet with the denizens of Hallowfall.", progress = "Who are you?", completion = "Friendly outsiders are not common in Hallowfall. Only enemies emerging from the shadow. \n\nBut you seem comfortable in the light despite how unusual you may appear. I would welcome you, were we not in the midst of a crisis." }
WordHunterWoW_QuestEN[78659] = { title = "Where the Light Touches", description = "Many in Hallowfall will call you \"outsider\". I would call you friend. I would also ask for your help, if you are no stranger to combat. Desperate times forge strong friendships.\n\nGeneral Steelstrike ordered the army to fall back from the nerubian onslaught. In doing so, she abandoned a Lamplighter and many troops to the darkness. I may not be able to save them on my own, but with your help I may succeed.\n\nIf you're willing, ride with me or meet me there.", objectives = "Meet with Faerin's ally near the Aegis Wall.", completion = "Outsider! The nerubians took us by surprise. The army went into retreat when the wall was breached. I've been keeping them away from this tower, but I could certainly use your help." }
WordHunterWoW_QuestEN[78661] = { title = "Excavation: Treasures in the Cliffside", description = "", objectives = "" }
WordHunterWoW_QuestEN[78662] = { title = "Excavation: A Cliffside Full of Caches", description = "", objectives = "" }
WordHunterWoW_QuestEN[78663] = { title = "Excavation: Scattered Around the Tower", description = "", objectives = "" }
WordHunterWoW_QuestEN[78664] = { title = "The Gift of Self-Care", description = "The eyes of a tired adventurer.\n\nA {class} that does many great deeds for many people. When was the last time you did a kind gesture for yourself? \n\nPerhaps now is the time. Look into your heart. \n\nWhat do YOU desire?", objectives = "Speak with Ying to discover your heart's desire.", progress = "Love is a blessing, especially if it comes from within.", completion = "Let us begin your journey to self-love." }
WordHunterWoW_QuestEN[78665] = { title = "Tunnel Trouble", description = "It's good to have new allies here. Together, we have much better chances of protecting this tower.\n\nThe nerubians have overwhelmed us. If we're going to have any chance against them, we need to destroy the burrows they're using to come under the Wall.\n\nIf you can handle that, we will survey the field from the top of the wall and meet you there.", objectives = "Destroy 6 Nerubian Burrows.", progress = "Were you able to stop the nerubians from coming under the ground?", completion = "Excellent, <name>--if we don't have to worry about the nerubians stabbing us in the back, we can deal with those pouring through below." }
WordHunterWoW_QuestEN[78666] = { title = "The Only Good Spider", description = "{name}, if we don't stem the tide of nerubians climbing up to us, nothing else will matter.\n\nTheir numbers are just too great.\n\nWe need to delay their onslaught to buy the people of Hallowfall time to prepare. The wall still serves as a very effective chokepoint.\n\nDo what you can to thin their numbers.", objectives = "Kill 12 Nerubian attackers.", progress = "<name>, every nerubian you kill here could mean a life saved in Hallowfall, and aids the chances of our own success.", completion = "This is a good start. There are still many more nerubians coming from below, but we must turn our attention to those already inside Hallowfall." }
WordHunterWoW_QuestEN[78667] = { title = "Rekindled Memories", description = "Good people died here today, {name}--a lot of them.\n\nEvery Arathi soldier carries a tinderbox. It represents their devotion to the Sacred Flame. Many use it as a focus to bring forth the Flame's light. In the dark places beyond the light of Beledar, the Sacred Flame brings hope.\n\nWith the nerubian attack, we can't recover their bodies. So we must retrieve these symbols, to venerate their sacrifice. Then use this torch to burn their bodies. It's the best funeral we can offer.", objectives = "Recover 6 Arathi tinderboxes from fallen soldiers and burn their bodies.", progress = "Have you recovered their tinderboxes? Every life deserves to be remembered in the Sacred Flame.", completion = "Thank you, <name>. You've helped to honor their sacrifice as well as we can." }
WordHunterWoW_QuestEN[78668] = { title = "Rally on the Dawnbreaker", description = "It's critical, with so many nerubians pouring through the Aegis Wall, that we defend our airships docked at Tenir's Ascent.\n\nThe nerubians have always outnumbered us, but our fleet allows us to concentrate our defenders where they are attacking, as well as allowing us to bombard them from the safety of the skies.\n\nIf we lose our armada, our hopes fade dramatically. Meet us there when you can.", objectives = "Meet Faerin at Tenir's Ascent aboard the Dawnbreaker.", completion = "I'm glad you're with us, <name>. \n\nWithout our airships, we have little chance of holding back the nerubians in the long run. \n\nTo say nothing of our dockworkers, who are safe below deck.\n\nLet's see to the defense." }
WordHunterWoW_QuestEN[78669] = { title = "For Their Eyes Only", description = "We've fought the nerubians since we arrived, {name}. Their attacks have not risen to this level in a long time.\n\nThese airship docks are clearly a target, but do they have any others? Is there a larger goal?\n\nThe nerubians carry shadecasters with orders from their queen. We need to learn what we can of their plans and intentions, and recovering a few of those shadecasters is the best way we can do so.", objectives = "Gather 3 nerubian Shadecasters to learn their plans.", progress = "Have you found any of those shadecasters yet, <name>?", completion = "Final war? Ascension? Not as many answers as questions, <name>. But we at least have some pieces of the puzzle." }
WordHunterWoW_QuestEN[78670] = { title = "Siege Weapon Sabotage", description = "{name}, if we're going to hold the nerubians back, we have to deal with their siege weapons. \n\nAround Tenir's Ascent, there are kegs of black powder to supply our ships for combat. Since the nerubians have caught these ships on the ground, let's put that powder to work.\n\nGather some barrels, and take them down to the nerubian siege weapons.", objectives = "Destroy 4 siege weapons below Tenir's Ascent.", progress = "Were you able to destroy their siege weapons, <name>?", completion = "With those siege weapons destroyed, we're in much better shape. Faerin went ahead to light the Dawntower with Great Kyron. She asked that we meet them there." }
WordHunterWoW_QuestEN[78671] = { title = "The Light of the Dawntower", description = "{name}, Faerin went to light the dawntower. She said it keeps the light of the Sacred Flame shining upon Hallowfall. Kyron is there as well.\n\nIt's hard to imagine that any beacon could outshine their star Beledar, but I am eager to see this new expression of the Light.\n\nMeet me by the dawntower and we can see how the Sacred Flame of the Arathi helps to safeguard these long-lost cousins of mine.", objectives = "Assist the Lamplighters in lighting the dawntower.", completion = "Just in time, <name>--Beledar has fallen dark for a time. But now we have our own light to hold back the darkness." }
WordHunterWoW_QuestEN[78672] = { title = "A Lamplighter's Duty", description = "Darkness has fallen. We can't rest yet. \n\n<Faerin gives you a weary smile, but there is a light in her eyes.>\n\nThe light from the tower will hold the worst dangers in the darkness at bay. It's my duty, as a Lamplighter, to keep all the towers blazing. \n\nMy patrol takes me to Lorel's Crossing by air next. I would welcome you and Anduin at my side, for all our sakes.", objectives = "Take the Lamplighter Skiff to Lorel's Crossing.", completion = "The kobyss have already been dragging innocent villagers to the shore! They'll drown them and eat them!\n\nWe have to save them!" }
WordHunterWoW_QuestEN[78674] = { title = "The Gift of Relief", description = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. \n\nI saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. \n\nPerhaps he has insight to teach you.", objectives = "Speak to Simeon Griswold at the Gala of Gifts, then relieve your stress in Old Town.", progress = "I've seen men die of stress. You don't want to bottle it up every day.", completion = "Feeling better?\n\nYou must take care of yourself after a tough day. If you're good to your body and brain, they'll be good to you." }
WordHunterWoW_QuestEN[78679] = { title = "The Gift of Relaxation", description = "Self-love can take many different forms. And on occasion it can take the form of relaxing. \n\nThe night elf by the fireworks seems particularly relaxed. \n\nPerhaps you could ask him for his insights on relaxation.", objectives = "Speak with Bordol Dewgarden about relaxation, then relax by Olivia's Pond in Stormwind.", progress = "True love is letting your guard down. Let yourself relax, you will see what I mean.", completion = "You feel renewed, don't you? Personally, I love petting the turtles.\n\nDid you discover your favorite relaxation technique?" }
WordHunterWoW_QuestEN[78685] = { title = "The Tunnel's End", description = "So we're hearing more rumors about Taelloch. \n\nThe town and its mine are responsible for ore production. Apparently, we haven't received shipments in weeks, and the town's foreman has disappeared. Now the High Speaker is discouraging anyone from traveling there.\n\nThat tells me we should investigate. And of course, if people are hurting, then we should help them.", objectives = "Investigate the rumors about Taelloch.", progress = "We have to find out what happened here.", completion = "Beasts inside?\n\nThe residents of Taelloch might need our help.\n\nHelp me keep an eye on Dagran, <name>. He's read a lot of stories about thrilling adventures, but he hasn't seen what we've seen. \n\nAnd something seems... off." }
WordHunterWoW_QuestEN[78686] = { title = "Lights Out", description = "Name's Aegor. I try to keep tabs on Lamplighters in the field and assess what areas of Hallowfall may be in need of their aid.\n\nThe dawntower fell dark at Velhan's Claim a few weeks ago. Based on what's been happening around Hallowfall, it's probably because of the rising tide of kobyss.\n\nLamplighters Taenar and Aemyra are heading there, but this might be more than even two Lamplighters together can handle. Will you meet them there and help them restore the light at Velhan's Claim?", objectives = "Meet Taenar and Aemyra near Velhan's Claim.", completion = "Pleased to meet you, <name>. I'm Taenar, and this is Aemyra.\n\nThe dawntower at Velhan's Claim went dark a while ago, and with all that's been happening, we're only just getting here to help.\n\nWe did some scouting, and it seems the area is overrun with kobyss. I imagine Velhan's holed up inside, instead of fighting them off.\n\nGood thing for his people that we're here. And it's better still to have you along helping." }
WordHunterWoW_QuestEN[78687] = { title = "Crash Recovery", description = "A lot of things went wrong when the Indomitable crashed, {name}. But the most upsetting one is that--when the order was finally given to make our way back to Mereldar, we couldn't honor our fallen comrades.\n\nIt seems the kobyss reanimated our fallen stalwarts, who now wander the Indomitable in a ghastly skeletal form.\n\nTake back their tinderboxes. If we can deliver those to the Sacred Flame, they'll finally be free after all these years.", objectives = "Retrieve 4 Recovered Tinderboxes from the Indomitable's stalwarts.", progress = "Did you find those tinderboxes, <name>?", completion = "The flame burns for us all, <name>. I wish I could have saved them that night, but I'm glad we'll be able to honor their memories.\n\nIt's what we all would want, if it happened to us." }
WordHunterWoW_QuestEN[78688] = { title = "Cage, Match", description = "When we were scouting before you arrived, we saw a lot of cages set up around Velhan's Claim. Typically, the kobyss use these to hold their victims until they're needed for a ritual sacrifice.\n\nThose sacrifices lead to... lots of other dark activities. Not the least of which is eating the victims.\n\nLet's get ahead of all that. Take my torch, and destroy the cages, so we don't have to see that happen to anyone from Velhan's Claim.", objectives = "Burn 10 kobyss cages with Aemyra's Holy Flame.", progress = "Have you dealt with those cages yet? The citizens of Velhan's Claim won't be safe until you do.", completion = "Good work, <name>. Without their cages, the kobyss won't be able to take prisoners.\n\nNo prisoners means no foul rituals, and preventing those gives us a much better chance of saving the people at Velhan's Claim." }
WordHunterWoW_QuestEN[78689] = { title = "If It Leads, It Bleeds", description = "Everything rises and falls on leadership, {name}. With a good leader, a unit can achieve almost anything. With a bad leader, chaos ensues and success moves out of reach. I've seen that first-hand.\n\nWithout leaders, the kobyss siege will break like a wave and everything else we do here becomes easier. I've seen three kobyss who seem to be leading the others--let me mark their locations on your map.\n\nDeal with them, and we'll be much more able to help Velhan's Claim.", objectives = "Defeat the kobyss leaders besieging Velhan's Claim.", progress = "Did you find their leaders? They look strong, but I'm sure you're up to the task.", completion = "Excellent. That will put us and the kobyss on a more even footing. At least in terms of leadership.\n\nThey still outnumber us by a lot, but one thing at a time." }
WordHunterWoW_QuestEN[78690] = { title = "Situational Awareness", description = "Regardless of what history Taenar and Velhan have between them, we need to take care of the people here at Velhan's Claim.\n\n{name}, will you please check in with the families here? Let them know we're here to help.\n\nSee if they're worried or need anything. And reassure them that the Lamplighters will drive back the kobyss.", objectives = "Speak with 10 citizens of Velhan's Claim.", progress = "It's so important to reassure the citizens of Velhan's Claim, <name>, that they'll get through this. Hope is everything in dark times.", completion = "We're here to help. But I've learned in the past, that there are times hope and reassurance can be the most urgent need.\n\nWhile you were talking with the residents, Taenar and I have determined what our next steps are going to be. \n\nWe need to give the people room to breathe, but we also need to prepare them to fight." }
WordHunterWoW_QuestEN[78691] = { title = "The One That Got Away", description = "{name}, my son is out with the kobyss. He convinced the other kids they should sneak out with him to fight. Said they should, \"be brave like my dad\". \n\nWhen they met a kobyss, the others all ran back here, while he ran toward the crashed ship, to lead it away.\n\nI have not handled myself bravely, {name}. The story of the Indomitable says I was a hero; those lies were my report. \n\nIf there was ever a time to step up, it's now. But I'm no match for the kobyss alone. Come with me, {name}--help me save Maximillian.", objectives = "Rescue Maximillian at the crash of the Indomitable.", progress = "Stay focused, <name>--we have to find my son.", completion = "I know it sounds trite, <name>, but I could never thank you enough for getting Max home safely.\n\nThrough all this, you've also shown me I need to be out front, leading the way for my people. I've seen there are outcomes worse than death. \n\nI can't undo the mistakes I've made in the past, but I can be certain not to repeat the pattern." }
WordHunterWoW_QuestEN[78692] = { title = "Teach a Man to Fish", description = "{name}, the people of Velhan's Claim have been locked up inside, afraid of the dark, for too long. \n\nAnd there's plenty to fear out there, but these are capable, strong people. They should be driving the kobyss away, not hiding behind their walls. \n\nGet these spears to the people of Velhan's Claim. They've learned to hide from their problems, but we'll give them the means to take their lives back!", objectives = "Distribute 8 spears to the residents of Velhan's Claim.", progress = "Have you handed out those spears yet? The people need them to remind them what they're capable of.", completion = "I think now we'll see them acting very differently, now that they're armed, <name>.\n\nThere's something about knowing you can take care of yourself, that you can handle your own problems, and you don't need anyone to rescue you.\n\nOf course, we Lamplighters will always be there to help, but it's very likely that we won't be needed next time." }
WordHunterWoW_QuestEN[78693] = { title = "Spears for Fears", description = "It seems Velhan and his followers hoped they could live in peace here. They were so sure they could, in fact, that they didn't bring any weapons with them.\n\nThis is a problem, with the kobyss attacking now, but the kobyss can actually solve it for us. They've brought plenty of spears for their siege on Velhan's Claim, and a spear will skewer a kobyss just as well as a human.\n\nHead out there and gather some spears for the people, {name}, and they won't have to be so afraid.", objectives = "Gather 8 Kobyss Spears for the people of Velhan's Claim.", progress = "Kobyss giving you trouble? Soon, the people of Velhan's Claim will be the ones giving them trouble.", completion = "Good work, <name>, this is exactly what we need to not just drive the kobyss back today, but to make sure the people of Velhan's Claim can defend themselves in the future." }
WordHunterWoW_QuestEN[78694] = { title = "Reclaiming Velhan's Claim", description = "The problem I see, {name}, is the kobyss. There's just so many of them.\n\nEveryone here was serving in the Empire's military when we arrived in Hallowfall. They may be rusty now, but they've all trained before, and know how to be dangerous.\n\nBut we need to eliminate every disadvantage, including the kobyss numbers. So head out there and even up the numbers. Aemyra and I will keep everyone safe here.", objectives = "Kill 12 Kobyss warriors around Velhan's Claim.", progress = "How's it going out there, <name>? You sending those creatures of darkness back to the deeps?", completion = "You know, I've hated the kobyss ever since they were dragging my fellow stalwarts into the night as dinner guests.\n\nHopefully because of the work you've done, that won't happen to any of the citizens of Velhan's Claim, <name>." }
WordHunterWoW_QuestEN[78695] = { title = "Lamp Lit", description = "The kobyss normally live deep underwater, {name}. When Beledar is at its brightest, they don't bother us. Other sources of bright light will usually keep them away, but definitely weaken them.\n\nAs Lamplighters, we not only go into the dark to protect those in need, but we provide them the light that will keep them safe. Go set up these torches along the perimeter, then meet us up at the dawntower behind Velhan's Claim.", objectives = "Place 8 torches around the perimeter of Velhan's Claim, then observe the re-lighting of the dawntower.", progress = "Did you get those torches set, <name>? The people will be able to quickly light them whenever Beledar fades.", completion = "You saved my son, <name>. You broke the spine of the attack on our home, gave us what we need to fight. \n\nYou helped me to be the leader I'd pretended I was. Thank you.\n\nThe Lamplighters will always have allies in Velhan's Claim." }
WordHunterWoW_QuestEN[78696] = { title = "We Don't Go to Taelloch", description = "This troubled Machine Speaker was here to do something. But what? It looks like something really did some damage to him.\n\nWe shouldn't dally. \n\nWe need to head into Taelloch and look for the foreman. Can you clear the entryway into the town? Someone could get hurt!", objectives = "Clear the entrance to Taelloch of encroaching beasts.", completion = "There's not much to see in the foreman's office. If we want answers, we'll need to search the town." }
WordHunterWoW_QuestEN[78697] = { title = "Ghost of a Company Town", description = "The foreman isn't here. Obviously. But the evidence points to her being here recently. So perhaps she's still nearby!\n\nWe should go further into town and see if anyone has any idea where she might be.\n\nOr maybe someone else can give us the answers we need. Maybe we'll find out on our own! Maybe it was some sort of attack or some kind of... sorry. I'm getting ahead of myself. Let's go investigate!", objectives = "Use the Investigate ability to find clues about what happened in Taelloch.", completion = "Well... there's one question answered perhaps. Only to unearth a dozen more." }
WordHunterWoW_QuestEN[78700] = { title = "Controlled Demolition", description = "I know we've fought skardyn before, champion, but this... this is worse. \n\nI knew that skardyn were turning earthen into more skardyn, but I didn't expect... the crystals... the spikes... the roiling blue energy... that smell! Anyway, not what I expected at all. \n\nIf we must venture out there, I'm taking down some of those abominations along the way.", objectives = "Kill 18 skardyn in Taelloch", progress = "There's more to be done. We can't let this corruption spread.", completion = "Maybe we've only killed a few skardyn from a much larger swarm. But we have to start somewhere." }
WordHunterWoW_QuestEN[78701] = { title = "The Truth in Chalk", description = "So the people of Taelloch use chalk on slate to leave messages to each other. So many clues! But what does it all mean....\n\nI'm seeing a pattern, and I think it points to the mines. If the workers haven't already been lost, I'd expect them to be in the mines.\n\nAnd I know the foreman is the key. She has to be.", objectives = "Search for messages in Taelloch Mine.", progress = "There's more to learn here. I'm sure of it.", completion = "I think I know where we need to go next." }
WordHunterWoW_QuestEN[78703] = { title = "Buried in Stone", description = "We need to go into the cave, the one mentioned near the last slate. It's not signed, but I think that's the foreman's handwriting... and we've looked everywhere else. We have to investigate.", objectives = "Investigate the cave at the back of the Taelloch Mine", progress = "We're missing something... There must be something in that cave!", completion = "I knew it! I was right! There's something in here. Something someone was trying to hide." }
WordHunterWoW_QuestEN[78704] = { title = "Find the Foreman", description = "Dagran was right. I suppose I shouldn't be surprised by that any longer.\n\nAll the signs suggest there's something in this cave. Maybe the foreman is hiding here. Maybe she can give us some answers.\n\nWe've come this far. Let's see what's inside.", objectives = "Find the foreman.", progress = "There must be answers deeper within the cave.", completion = "That was her. The foreman. It had to be. After all that... she was already gone." }
WordHunterWoW_QuestEN[78705] = { title = "What She Saw", description = "What is that? That thing the skardyn dropped before we... before it died.\n\nI think I've seen something like that before.", objectives = "Investigate the gem left by the skardyn.", progress = "I think I know what that gem is...", completion = "Oh. This is bad, isn't it?\n\nThe foreman witnessed this conspiracy at the Hall of Awakening.\n\nThen she traveled back to Taelloch with her memory gem.\n\nShe tried to warn the others, but she was infected... and her transformation was swift. She sealed herself in this cave, but her corruption still spread.\n\nAnd the High Speaker knew what would happen. The High Speaker is behind all of this!\n\nWe've got to warn Brinthe. We've got to warn the world." }
WordHunterWoW_QuestEN[78706] = { title = "The High Speaker's Secret", description = "We got what we came for. We need to return to Gundargaz. Brinthe has to know what happened here.\n\nWe'll go on ahead, {name}. Meet us in Gundargaz.", objectives = "Return to Brinthe in Gundargaz.", completion = "Thank you for looking into the mystery plaguing Taelloch.\n\nWhat did you find?" }
WordHunterWoW_QuestEN[78713] = { title = "The War Within", description = "There is a vision being seen across Azeroth. A \"Radiant Song.\" We believe it's a warning, but we are unsure of its meaning.\n\nMeet me in Silithus. We must ask Azeroth's Speaker what this vision means.", objectives = "Go to Silithus to talk with Thrall about the visions spreading across Azeroth.", completion = "We're all here. Good. Let's find out what the Radiant Song is trying to tell us." }
WordHunterWoW_QuestEN[78714] = { title = "A Poor Reception", description = "There's strong evidence that the Radiant Song is a warning from Azeroth herself. A cry for help.\n\nThat's why we're here. If this vision truly is Azeroth's message, Magni will know what she's trying to tell us.\n\nHe should be in the Chamber of the Heart. Let's go.", objectives = "Go to the Heart Chamber to ask Magni for help deciphering the Radiant Song.", completion = "I know why you're here. It's the visions. Azeroth's voice, heard all across the lands. Ye thought I would know what she's trying to tell us. \n\nWell, ye thought wrong." }
WordHunterWoW_QuestEN[78715] = { title = "Azeroth's Voice", description = "I haven't spoken with Azeroth for years. At first I just didn't feel the need. Then I realized I had started to resent her. For leaving me like... this. And now I'm not sure if I can.\n\nBut I know the stakes. This Radiant Song of hers foretells something dire. And we need to know what.\n\nFirst, we need to prepare the Heart Chamber. Can ye start up the consoles nearby?", objectives = "Help Magni perform his ritual.", progress = "I understand Magni's concerns, but we have no other choice. The future of our world is at stake. We must try everything we can to understand what Azeroth is trying to warn us of.", completion = "This has never happened before. Magni is the Speaker of Azeroth. Why would communing with her cause him to collapse?" }
WordHunterWoW_QuestEN[78716] = { title = "Painful Lessons", description = "Magni appears stable for now, but he's still not responsive. We need to get him treatment quickly. I'll open a portal to Dalaran.\n\nFollow us when you can.", objectives = "Take the portal to Dalaran.", completion = "I'm unsure why the Speaker of Azeroth would end up in such a state after attempting to... well, speak with Azeroth.\n\nAll we can do is wait for Magni to recover." }
WordHunterWoW_QuestEN[78717] = { title = "A Mysterious Warning", description = "Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin.\n\nI saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us.\n\nThat's what we need to protect.", objectives = "Discuss the next steps, then follow up with Khadgar.", progress = "Khaz Algar...", completion = "The council has decided. We travel to Khaz Algar.\n\nDalaran will teleport as soon as we're able. Will you lend us your aid in our preparations?" }
WordHunterWoW_QuestEN[78718] = { title = "Strengthen the Wards", description = "Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst.\n\nHere, take this wand. It's been attuned with Dalaran's defense magics.\n\nJust wave it near strategic parts of the city to strengthen our magical defenses.", objectives = "Strengthen Dalaran's defenses.", progress = "We will be hard pressed to save Khaz Algar if our own defenses aren't strong enough to withstand attack.", completion = "Well done, champion.\n\nLet's just hope it's enough. I would hate for anything to happen to our city right as the world needs us most." }
WordHunterWoW_QuestEN[78719] = { title = "Citizens of Dalaran", description = "Our citizens must be prepared for Dalaran's departure. Can you ask around the city and see if anyone requires aid?\n\nI'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.", objectives = "Help the citizens of Dalaran prepare for the teleportation.", progress = "Dalaran is always ready to defend the world, but that doesn't mean we can do so on a whim. Preparations are key to a smooth transportation.", completion = "Thank you for your help. It's important that the citizens of Dalaran are ready for whatever may come." }
WordHunterWoW_QuestEN[78721] = { title = "Meet the Team", description = "If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. \n\nThey're calling themselves the Algari Expedition this time around.\n\nI'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?", objectives = "Check in on the Algari Expedition.", progress = "A league and an expedition walk into a tavern... Nope, nothing's coming to me.", completion = "They're getting along? Well I'll be a goat's uncle. Ach, no offense to Dagran.\n\nWell, that certainly makes my job easier. Thanks for checking in on them, all the same!" }
WordHunterWoW_QuestEN[78722] = { title = "To Khaz Algar!", description = "From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out.\n\nLet me know when you're ready to depart.", objectives = "Tell Khadgar you're ready to depart.", completion = "She was Archmage Drenden. All along, Xal'atath has been watching, plotting, right in front of me. How could I be so blind? \n\nAnd now she's invading Dalaran with an army of nerubians. \n\nXal'atath planned this. All of this. She wanted us to come to Khaz Algar." }
WordHunterWoW_QuestEN[78724] = { title = "Loving Yourself, Your Way", description = "If it's a challenge you're after, I think I have an idea.\n\nI saw a boastful champion heading toward Goldshire. You could challenge him to a duel.\n\nThis would satisfy your desire and perhaps teach him a valuable lesson in humility.", objectives = "Defeat Matley Graston in a duel near Goldshire.", progress = "How fares your challenge?", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all." }
WordHunterWoW_QuestEN[78726] = { title = "Loving Yourself, Your Way", description = "A full belly is a happy belly!\n\nThere is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", objectives = "Consume treat packages from vendors at the Gala of Gifts.", progress = "Have you had your fill of treats? I love the fruits, myself.", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all." }
WordHunterWoW_QuestEN[78727] = { title = "Loving Yourself, Your Way", description = "While visiting this gala, I am staying at the Lion's Pride Inn at Goldshire.\n\nI hear they have some extra beds upstairs. Why not see if you can sleep there for a while?\n\nI think I will have a bit of a rest too... Right... here...", objectives = "Take a nap in the upstairs guest room at the Lion's Pride Inn.", progress = "<Ying is quietly snoring.>", completion = "...Huh? Oh! Welcome back, did you enjoy your rest?\n\nOn any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all." }
WordHunterWoW_QuestEN[78729] = { title = "Raising a Stink", description = "Those clues add up to an ugly story, {name}.\n\nThat map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic.\n\nI've got a guy that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", objectives = "Meet Inspector Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.", completion = "There you are, right on time.\n\nI've got a plan to deal with this chemical conspiracy." }
WordHunterWoW_QuestEN[78738] = { title = "Absent Speaker", description = "It is a dark day for the Ringing Deeps, {name}.\n\nI always knew there was something about the High Speaker that wasn't quite right. Now we have proof.\n\nAnd we need justice. If he has plans for the Awakening Machine, then we've got to stop him.", objectives = "Meet Speaker Brinthe in the Earthenworks.", completion = "The High Speaker and his followers will answer for their crimes." }
WordHunterWoW_QuestEN[78739] = { title = "Excavation: The Trove in the Tower", description = "", objectives = "" }
WordHunterWoW_QuestEN[78741] = { title = "Sympathetic Speakers", description = "I have to stop the High Speaker from making more skardyn.\n\nMachine Speaker protocol dictates that one of the foremen in this area should have a key to the Hall of Awakening. Come with me, and we'll track it down!", objectives = "Look for Machine Speaker Foremen in the Earthenworks with Speaker Brinthe.", completion = "This should get us into the Hall of Awakening..." }
WordHunterWoW_QuestEN[78742] = { title = "Battle of the Earthenworks", description = "{name}! There's a battle afoot! We need to assist Machine Speakers loyal to our cause and move against anyone defending the High Speaker.\n\nI'm going to remain and make plans with Adelgonn. I need you to lead our forces while we're containing consequences of the High Speaker's actions in the Earthenworks. This is our first step in deposing him. We're putting a stop to his horrendous crimes once and for all. \n\nWhat do you say, {name}? Up for a scrap?", objectives = "Defeat enemy Machine Speakers, constructs, and help frightened workers in the Earthenworks!", progress = "I'll admit: the ability to acquire an army at the drop of a hat has gotten me fairly far in life.", completion = "You've managed to drive out some of the High Speaker's most devoted disciples... and you've cracked some heads.\n\nThat's a fine start. But there's so many... too many..." }
WordHunterWoW_QuestEN[78743] = { title = "Before I Depart", description = "I can feel my energy reserves depleting.\n\nI will soon not be able to execute my duties. That is why I have Urtago here to take over.\n\nBefore my systems grind to a halt, I must make sure Mourning Rise is free of kobolds. They have invaded the memorial site I tend and plunder the Unbound shrines and bodies that are there.\n\nMaybe it is good you are here. You may have the strength to help us.\n\nPlease, help Urtago rid the site of kobolds.", objectives = "Meet Urtago at the Mourning Rise memorial site.", completion = "Korgran still calls himself the caretaker, but I'm the one who has been taking care of Mourning Rise for some time.\n\nI don't mind. Korgran is very kind. \n\nBut the situation here has gotten away from me. We have some work ahead of us." }
WordHunterWoW_QuestEN[78744] = { title = "Honor Their Memories", description = "Take these gifts and place them by the past caretakers. Each is a gift honoring their memory.\n\nI'd also like us to perform some light groundskeeping to at least maintain the site. Unfortunately, what these kobolds are doing to the memorials will take us weeks to fix.\n\nPlease do what you can about the kobolds. It would be unwise to leave the gifts unguarded while they are still roaming the area.", objectives = "Eliminate the kobold infestation and place gifts near the shut-down, past caretakers.", progress = "The kobolds cannot be left to desecrate Mourning Rise.\n\nThe Unbound that rest here are here because they do not want to be disturbed or moved. While they do not wish to be revived, taking their armor and possessions is an insult to earthen culture.\n\nWe must do something.", completion = "I am amazed how much damage the kobolds have done to the site. So many shut-down earthen desecrated!\n\nI know that I am not yet the head caretaker, but I take full responsibility for this. I should have asked for the mantle of caretaker long ago when Korgran started to show the first signs of memory overwrite and stasis lock." }
WordHunterWoW_QuestEN[78745] = { title = "You No Take Plunder!", description = "It looks like the kobolds have taken gems and other... body parts off these shutdown earthen. \n\nAbominable.\n\nFind where the kobolds are holding their plunder, and bring it back to me so I can return it to its rightful place later.\n\nThis vandalism will not go unchecked!", objectives = "Recover earthen belongings from piles of plunder.", progress = "Were you able to find their plunder?", completion = "Thank you for doing this.\n\n<Urtago nods to herself with confirmation as she examines the items.>\n\nI am relieved, but there is much more work to do." }
WordHunterWoW_QuestEN[78746] = { title = "Laws Apply to All", description = "Desecrating a memorial site is one of our greatest taboos in earthen society. This site is a window to our past, into our memories, and a place of self-reflection where we can commune with those who are no longer here.\n\nStill, so many of these kobolds infest Mourning Rise. For their crimes, the kobolds deserve the harshest punishment. They must be culled even further.", objectives = "Slay kobold invaders in Mourning Rise.", progress = "So many of them still infest Mourning Rise.", completion = "I was not made as an earthen of the sword, nor as one who calls for violence. That is the domain of the Stormriders. \n\nWhat these kobolds did is frowned upon not just by us, the Unbound, but by everyone in earthen society. I am not proud that we had to kill them, but we had to stop them by any means." }
WordHunterWoW_QuestEN[78747] = { title = "The Great Collapse", description = "Now that we landed a mighty blow, it is time to make sure that we block their tunnels so they cannot come back.\n\nRemember the stuff that Korgran asked about? Explosive sticks--his recipe. I have brought enough to shake a mountain! More than enough for the kobolds.\n\nHelp me show these kobolds that we will fight for what is ours so they will never come back!", objectives = "Use the Explosive sticks to destroy Kobold tunnels.", progress = "Is it done? Were the tunnels dealt with?", completion = "Ha ha! What did I tell you? I felt the tremors from back here!" }
WordHunterWoW_QuestEN[78748] = { title = "Cutting the Wick", description = "Knowing kobolds, they will have several workmasters, or leaders, running this raid.\n\nFind and eliminate these so-called \"workmasters.\" The rest of them will get disorganized, forget why they are here, and hopefully leave us alone.", objectives = "Find and slay the kobold workmasters.", progress = "Were you able to slay all three of them? Their deaths will strike a significant blow to this kobold operation.", completion = "Eliminating the minds behind this operation will only buy us more time if and when the kobolds decide to do this again.\n\nUnfortunately, there is still one more kobold brain that we have missed. Until now." }
WordHunterWoW_QuestEN[78749] = { title = "Who Runs This Fine Establishment?", description = "While you were dealing with the tunnels and the workmasters, I saw a peculiar kobold go into a cave to the northwest. The kobolds seemed to respect him more than the others, calling him Grand-Heister Bokk and offering him the food you call \"cheese.\" This makes me think he is the real mastermind.\n\nIf that kobold is in fact the real Ward of this operation, then we should take the opportunity to strike him down.\n\nI will meet you at this cave.", objectives = "Slay Grand-Heister Bokk.", completion = "I am happy to see you, <name>.\n\nI feel my inner workings grinding--that's a sign of anxiety. Korgran nears his shutdown with every passing moment, and then this place will be under my care. \n\nIt is a lot of responsibility. But I believe that I am ready for it." }
WordHunterWoW_QuestEN[78754] = { title = "Lost Delivery", description = "<You find a small yet heavy leather-bound package on the road with an attached label.>\n\nGundargaz Courier Express\n\nEXPEDITED\n\nTo: \nHarvester Farnee\nDurgaz Cabin\n\nOPEN WITH CARE: Contains volatile elemental minerals.", objectives = "Deliver the Abandoned Package to Harvester Farnee at Durgaz Cabin.", completion = "Well, smoke the hive... you found it! I still can't believe the courier just lost my package...\n\nWe've been waiting on this to help with Shalehoof's leg. \n\nMixed with fire honey, this stuff should patch him up quickly!" }
WordHunterWoW_QuestEN[78755] = { title = "Playing in the Mud", description = "Remember when we used that clay and the fire honey to patch up Shalehoof? Let's do that again but bigger!\n\nProblem is we've run out of clay. But fortunately, with all the recent seismic activity, a whole avalanche of elementals has been roused out of torpor and are clashing on the eastern beach!\n\nBring me wet, elementally charged silt to use as our restorative substrate!", objectives = "Gather 20 handfuls of Elementally Charged Silt.", progress = "By combining living sand and water, we can create an elemental silt that mimics the underclay's healing properties. Or at least something that comes close to it!\n\nIsn't elemental fusion fascinating?", completion = "Can you feel the energy in the silt between your fingers, <name>? The charge that hums through it?\n\nIsn't it exhilarating? Doesn't it make you feel one with the earth and the mountains?" }
WordHunterWoW_QuestEN[78756] = { title = "Lots and Lots of Fire Honey", description = "If Harmot wants to patch this sleeping boulder up and get him out of my pond, I'm all for it. \n\nUnfortunately, we used the last of my store of fire honey on Shalehoof's wound. I haven't had time to harvest any from the Cinderwold with all these elementals running amok. \n\nHead on down to the wold's edge and bring us some honey. You're going to need a lot.", objectives = "Find a lot of Fire Honey.", progress = "Mind yourself in my forest. Cinderbees are dangerous, but we rely on them for the honey they produce for our mead.", completion = "You found this off of WHAT? A living honey e--\n\n<Farnee stops her sentence before lowering her voice.>\n\nLet's keep all mention of living fire honey between us. Harmot might get distracted and run off into danger if we tell him..." }
WordHunterWoW_QuestEN[78757] = { title = "Honey and Clay the Pain Away", description = "Ramoliths! Magnificent, aren't they? One of the finest elemental beasts on the isle. \n\nThe bad news is they're not immune to injury. Poor Shalehoof here was attacked by awakened elementals in Farnee's pond.\n\nThe good news is that we have all we need to tend to him.\n\nWe just have to mix that clay you found with some fire honey and slap it up on ol' Shalehoof's hock! \n\nReady?", objectives = "Help Harmot prepare Shalehoof's salve.", progress = "Much like us earthen, healing something made from rock and stone is no easy task.\n\nBut the unique properties of the clay you've brought, combined with the fusing properties of the honey makes for an excellent restorative!", completion = "Well, aren't you just a natural with the elements. Ever thought about making a career out of it?\n\nSay, since you're not afraid of getting messy, why don't you help us with Farnee's problem?" }
WordHunterWoW_QuestEN[78758] = { title = "Pulse Within the Earth", description = "Before we go and wake up a slumbering mountain giant, it's probably best we get an idea for how deeply asleep he is. \n\nThough, if the nerubians burrowing up didn't wake him up, I'm not sure what will.\n\nTake these earth shards and plant them on the waterfalls and hills around the lake. \n\nOnce we've got them set up, I'll be able to get a reading on the giant's health.", objectives = "Place 4 Tremor Stones around the pond.", progress = "Once you've got the shards set up, I can drop the final one here to get a proper read.", completion = "The mountain giant's got a weak heartbeat.\n\nPoor lad's likely been disturbed from a deep slumber with all of these elementals breaking off from the falls.\n\nFortunately, the pair of us are experts in healing elemental and elemental-adjacent's life forms, aren't we? \n\nIf the salve can work on earthen and rock rams, it can work on mountain giants!" }
WordHunterWoW_QuestEN[78759] = { title = "To Wake a Giant", description = "By the Coreway, this stuff packs a punch!\n\nCombining healing silt with the molten fusion properties of fire honey has given us a salve that could wake a whole mountain!\n\nWhich is exactly what you'll do. Take the mixture over to our wounded friend in Farnee's pond, and slap it on his hide!\n\nIt should be enough to wake him up and alleviate any soreness.\n\nHopefully, anyways.", objectives = "Apply elemental salve to the mountain giant for Harmot.", progress = "This will either wake the giant and patch him up good as new or...\n\nWell, let's not talk about the other possibility. Have some faith in the process!", completion = "Well, would you look at that! \n\nThousands of years slumbering at the base of a waterfall and he wakes up without even a roar or a foot-stomp.\n\nHah! And Farnee was worried!\n\nYou did great with making that salve, <name>. Both Farnee and I owe you a big thanks. \n\nOur new friend looks thankful too!" }
WordHunterWoW_QuestEN[78760] = { title = "Dark Iron from Above", description = "We've done our best to contain the High Speaker's followers. We've hampered their efforts at destroying or looting anything they can take with them into Hall of Awakening.\n\nNow, we just need to deal with the leader of their forces before they can coordinate a more unified resistance.\n\nAre you ready to do this, {name}?", objectives = "Defeat Supervisor Varric and his forces within the Earthenworks.", completion = "The Ringing Deeps should be safe... for now. But the High Speaker...\n\nWe need to follow Speaker Brinthe into the Hall of Awakening." }
WordHunterWoW_QuestEN[78761] = { title = "Into the Machine", description = "No time to catch our breath! The High Speaker is fleeing to the earthen's most sacred machine. We need to follow him.\n\nRemember, we're doing this for the earthen! For justice! For all the brothers and sisters and comrades who've fallen to the High Speaker's hubris!", objectives = "Confront the High Speaker inside the Hall of Awakening.", completion = "He's gone? He really gone?\n\nAs far as I'm considered, he just abdicated his authority. I don't know where he fled, and I don't care. Now that the Awakening Machine is operational again, we can step up and set things right." }
WordHunterWoW_QuestEN[78762] = { title = "Your First Find", description = "We've got a find on our hands! Looks like this might be one of my books from undergrad. Hah!\n\nNow, your job is to get all that dirt off of it, but you have to be careful. The artifacts we handle are very fragile, and the only thing worse than them staying in the ground is them breaking on the way out.\n\nEmpowering your elemental will only get you halfway. You'll need to use your environment to keep things in balance so that it's safe to excavate.", objectives = "Practice excavating on the Outdated Geology Textbook.", progress = "What do you think? Having fun yet?", completion = "There you go! Your first artifact... of a kind anyway.\n\nThe stuff we find out in the field is usually more exciting. But at least this one you can keep as a souvenir!" }
WordHunterWoW_QuestEN[78763] = { title = "Dragonflight (70) E", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[78764] = { title = "Dragonflight (70) E", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[78765] = { title = "Dragonflight (70) E", description = "", objectives = "Upon completion of this quest you will gain:" }
