WordHunterWoW_QuestEN[78789] = { title = "Flightstones", description = "", objectives = "" }
WordHunterWoW_QuestEN[78820] = { title = "Technoscrying: The Mysteries of Igira's Watch", description = "", objectives = "" }
WordHunterWoW_QuestEN[78821] = { title = "Blooming Dreamseeds", description = "The Emerald Dream is about the harmony and balance of nature. For Amirdrassil to bloom, we need a rich variety of plants growing alongside the world tree. Plant seeds wherever you find fertile soil.", objectives = "Plant dreamseeds in the Emerald Dream.", progress = "How's the planting going?", completion = "Thank you! It's in these many small acts that allows the Emerald Dream to flourish, and thus nourish Amirdrassil." }
WordHunterWoW_QuestEN[78827] = { title = "Go Take Candle!", description = "Ksk, ksk! You there! Yes, you!\n\n<You hear the sound of jostling behind the vent and a new, even scratchier voice emerges.>\n\nWe, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me.\n\nBring us, me, bring me candles! Yes! \n\nNo ask question, just go get candles. \n\nWe are, er, I am professional, yes. Professionals do not ask questions. \n\nOnly get candles.", objectives = "Steal candles for the suspicious vent in the Gundargaz Inn.", progress = "You have candles?", completion = "<Exuberant chanting can be heard from within the vent.>\n\nCandle! Candle! Candle!\n\nHush! Shh! Don't let the stone ones hear..." }
WordHunterWoW_QuestEN[78837] = { title = "Pomp and Dire Circumstance", description = "I'm seeing legitimate concerns. We have to do something about the nerubians... even if the High Speaker won't. If he won't do something, I will.\n\nThe High Speaker sent me to the surface because I wasn't \"reasonable.\" I think we should have a chance to... reason... with him. We'll need to go to Gundargaz.", objectives = "Meet Speaker Brinthe in Gundargaz.", progress = "That is... never pleasant.", completion = "So much for reason. \n\nThe Ringing Deeps has plenty of problems, and the High Speaker is obviously distracted. He sounds obsessed! \n\n<name>, if you and your companions can help us solve some of our challenges here, maybe I can convince the Machine Speakers to help you against the nerubians. That's a problem that concerns us all." }
WordHunterWoW_QuestEN[78838] = { title = "Cogs in the Machine", description = "Gundargaz is my home. Or at least, it was before the High Speaker saw fit to reassign me above ground. I've missed my home, but it's... changed.\n\nAs the number of Machine Speakers decreases, we're in a race against time. \n\nLately, we've been especially weary of our assigned tasks, but as always, we must bear our burdens.\n\nLet me show you around the area. There are some earthen I would like you to meet.", objectives = "Accompany Brinthe as they talk to earthen in Gundargaz.", progress = "This is not how I remember my home.", completion = "Problems are increasing, and our numbers are dwindling.\n\nThe High Speaker is distracted, kobolds are attacking, shipments are missing from Taelloch, and earthen aren't returning from their shifts.\n\nWhere to begin? Looks like our work is cut out for us." }
WordHunterWoW_QuestEN[78839] = { title = "Kobold Shoulder", description = "The first step to stemming our losses and retaking the mines is straightforward, if unpleasant. Without minions, this Candle King will be less of a threat to Gundargaz.\n\nSee if you can reduce the swarm, {name}, before hostilities escalate further.", objectives = "Kill invading kobolds in the Lost Mines.", progress = "This should never have happened.", completion = "Grim work, but necessary." }
WordHunterWoW_QuestEN[78860] = { title = "More Candles!", description = "I, er, we...no, no, I! I have new deal for you, oh shadowy one. \n\nMore candles! \n\nIn return, you get... er...\n\n<Frantic shuffling reveals a new voice.>\n\nYou get more candles! Then you give to us! To me! \n\nCandles! Candles! Candles!\n\n<The excitedly whispered chanting continues for some time.>", objectives = "Steal more candles for the suspicious vent in the Gundargaz Inn.", progress = "You have candles? More candles?", completion = "Ksk! You did it!\n\nMore candles...\n\n...unlimited candles.\n\n<A somber awe emanates from the vent.>" }
WordHunterWoW_QuestEN[78861] = { title = "Aiding the Accord", description = "", objectives = "" }
WordHunterWoW_QuestEN[78863] = { title = "A Place Beneath the Boughs", description = "Thanks to you and all the mortals who defended the Emerald Dream, a new World Tree now grows in the Dragon Isles.\n\nAmirdrassil's boughs will be a haven of peace and tranquility, and a place of respite for the kaldorei souls lost at Teldrassil.\n\nTyrande Whisperwind and Shandris Feathermoon are at the tree now. They would share words with you.", objectives = "Meet Tyrande and Shandris in Amirdrassil.", completion = "Welcome to Bel'ameth, <name>." }
WordHunterWoW_QuestEN[78864] = { title = "The Returning", description = "It is a time of reflection and change, {name}. For the world, and for my people.\n\nMy mother and I have been discussing the roads that led us here... and where those roads will lead in the years to come.\n\nCome, let us speak.", objectives = "Speak with Shandris Feathermoon.", completion = "My father has returned to us at last, <name>!" }
WordHunterWoW_QuestEN[78865] = { title = "Siblings Until the End", description = "Some time ago, Vyranoth received an unexpected summons... from Iridikron.\n\nYou will want to hear what he had to say.", objectives = "Speak with Vyranoth to hear about her meeting with Iridikron.", progress = "Iridikron had much to say...", completion = "I know not what Iridikron intends to do next. But I can no longer call him \"brother.\"" }
WordHunterWoW_QuestEN[78866] = { title = "Superbloom: Step 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[78867] = { title = "Superbloom: Step 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[78868] = { title = "Superbloom: Step 4", description = "", objectives = "" }
WordHunterWoW_QuestEN[78869] = { title = "Superbloom: Step 6", description = "", objectives = "" }
WordHunterWoW_QuestEN[78870] = { title = "Superbloom: Step 7", description = "", objectives = "" }
WordHunterWoW_QuestEN[78871] = { title = "Superbloom: Step 8", description = "", objectives = "" }
WordHunterWoW_QuestEN[78874] = { title = "Conjured Help", description = "If you're looking for food--softy food--I'm afraid we're clean out. Nothing but good ol' rocks and gems here at the moment.\n\nIt's starting to become a problem, actually.\n\nSay... you wouldn't be able to do anything about that, would you? Rustle us up some victuals for the fleshy folk?", objectives = "Summon food for Innkeeper Brax in the Gundargaz Inn.", progress = "You don't want to try a nibble of cobalt?", completion = "Strike me with a hammer and call me an anvil--that's a lot of food!" }
WordHunterWoW_QuestEN[78875] = { title = "The Unkillable", description = "I'm bettin' dat ogre Mai'Zoth is behind all dis. He should have died long ago, but his magics still be strong. \n\nHe be using the altar's centerpiece as a conduit to drain Lukou's power.\n\nRecover the centerpiece and prove he's not so unkillable when he doesn't have a loa hostage.", objectives = "Recover the altar centerpiece from Mai'Zoth.", progress = "Did you prove Mai'Zoth isn't unkillable?", completion = "That centerpiece be critical. It was being used to drain Lukou directly." }
WordHunterWoW_QuestEN[78876] = { title = "A Glowing Memento", description = "<An unusually persistent ember draws your eye. It glows with a pure, primal heat.> \n\n<Vyranoth would be interested in this.>", objectives = "Bring the Everglowing Ember to Vyranoth in Amirdrassil or the Central Encampment in the Emerald Dream.\n\nProvided item:", completion = "An ember of primal flame, somehow untouched by the shadowflame of that wretched cavern... \n\nThank you. It is a warm reminder of the brother I had long, long ago." }
WordHunterWoW_QuestEN[78877] = { title = "Bless These Homes", description = "Divine presence acknowledged.\n\nEvery day for as long as my memory serves me, I have walked the routes and lit the incense around our homes. It has ground my joints to dust, but is it an important task. \n\nA sacred task. \n\nThese are dark times we live in--perhaps you could add your own beatitudes to our little rituals?", objectives = "Bless the incense around Gundargaz.", progress = "You do us an honor, bringing your faith into these caverns. Let it bless these machines and those who work with them, just as they bless us in turn.", completion = "We are all cogs in the machine. We turn, and turn, and turn... \n\nThere is a beauty there. \n\nA quietude." }
WordHunterWoW_QuestEN[78879] = { title = "Evoking the Forge", description = "Harumph! This blasted forge is on its last legs. We'd repair it, but Stonemason Itsak picked up a shift at Ironhaul Station when the Coreway collapsed, and well...\n\nThere's no one to fix it anymore.\n\nIf you can figure out a way of getting it running hot again, Gundargaz would be in your debt!", objectives = "Find a way to stoke the forge outside of Gundargaz.", progress = "I'm going to miss Itsak. He made the best end-of-shift rock roasts...", completion = "Whoa! I've never seen anything like that! You just... keep fire in your throat?\n\nNow that's a trick I'd been keen on learning!" }
WordHunterWoW_QuestEN[78880] = { title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Stormwind.", completion = "Thank you for visiting, skyrider!" }
WordHunterWoW_QuestEN[78881] = { title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Orgrimmar.", completion = "Thank you for visiting, skyrider!" }
WordHunterWoW_QuestEN[78890] = { title = "Emerald Frenzy", description = "", objectives = "" }
WordHunterWoW_QuestEN[78892] = { title = "Superbloom: Step 9", description = "", objectives = "" }
WordHunterWoW_QuestEN[78893] = { title = "A Scrap of Bronze", description = "The vendors of Pandaria do not want the equipment you will find in this timeline.\n\nYou can convert unwanted equipment into Bronze using the magic of the infinite dragonflight.\n\nUse the Unraveling Sands ability and scrap the Unraveling Tunic.", objectives = "Use the Unraveling Sands ability to summon Unraveling Sands, then place the Unraveling Tunic in the Unraveling Sands to scrap it into Bronze.", progress = "You can place unwanted equipment into the Unraveling Sands to obtain additional Bronze for your journey.", completion = "Bronze can be spent at infinite bazaars to upgrade your equipment, acquire gems, or expand your collections." }
WordHunterWoW_QuestEN[78894] = { title = "Infinite Growth", description = "", objectives = "If you bring me sufficient Bronze, I will empower your equipment." }
WordHunterWoW_QuestEN[78895] = { title = "A Shadow Over Gundargaz", description = "You look dangerous.\n\n<Toki spits on the ground.>\n\nThat's good. We need dangerous. Something is stalking Gundargaz. \n\nSomething mean. \n\nSomething... recent. \n\nJust before the Coreway collapsed I started getting reports of workers going missing mid-shift. Only thing we've been able to find have been the odd chunk of rock.\n\nFingers, mostly. \n\nIf you could sniff out what's stalking my town, I'd be in your debt.", objectives = "Track down whatever is hunting the earthen in Gundargaz.", progress = "Life didn't always used to be this exciting.", completion = "A demon? Escaped from the crashed ruins of a flying magical city?\n\nIf you say so. \n\nI'm just glad it's sorted." }
WordHunterWoW_QuestEN[78897] = { title = "Boom or Blight", description = "This place is infested with cave borers. They pose a threat to the great roots that stretch through this place.\n\nYes, the tree provides sustenance for many living things, but this is not some small band of bugs nibbling on a leaf. This is a blight. Their numbers must be culled for the good of the whole. \n\nBy my oath I am unable to raise a hand to interfere. However... you have sworn no such oath. Will you do what must be done?", objectives = "Cull 10 worms of the Wormlands.", progress = "How fares the blight?", completion = "You have my gratitude, stranger." }
WordHunterWoW_QuestEN[78898] = { title = "Intention vs Instinct", description = "Cave borers are not social creatures as a rule. Seeing this many gather in one place speaks to intention.\n\nA wormcaller of the nerubians must be present.\n\nFind them and recover the tool they use to call these worms here. With it we can lead them away in time.", objectives = "Collect a Singing Stone from Wormcaller Iz'tikrine.", progress = "I can sense more worms coming. As if they are drawn to this place.", completion = "What a strange gem. \n\nThe song within must be what is drawing the worms to this place." }
WordHunterWoW_QuestEN[78900] = { title = "On Cold, Dark Wings", description = "You came down the Coreway, right? From up top?\n\n<Toki chuckles.>\n\nThey have it easy, those city earthen. Down here, death comes for you from all around. \n\nFrom below. From above.\n\nYou look like you've killed a fair few beasts in your time. Care to add another to the list?", objectives = "Track down the Ringing Death in Gundargaz.", progress = "Keep quiet, that's my advice.", completion = "The monstrous bat wasn't quite so monstrous after all, eh?\n\nWelcome to Gundargaz." }
WordHunterWoW_QuestEN[78901] = { title = "Heeeelllp!!!", description = "Hey! You!\n\nGet me down! Away from these worms! Please!\n\nI'll pay you! I'll even owe you one! Heck, I'll gladly sell out any cartel member you need dirt on! \n\nJust get me down!\n\nAlso, don't walk too much. They can hear your footsteps. Move from rock to rock if you don't want a swarm coming after you.", objectives = "Rescue Skedgit Cinderbangs.", completion = "Okay, okay! I'm okay." }
WordHunterWoW_QuestEN[78902] = { title = "Delegated Dig", description = "Okay, I know when I'm beat. So I want to hire you as my Champion of Coin... or coinchamp.\n\nThis is all a part of my brilliant enterprising venture. See, these worms here are great at rooting out rich minerals like a niffen sniffing out high-quality mushrooms. \n\nI'm willing to bet all of my money--and your life--that they found a vein of sivstone. Great stuff, though I doubt a {class} would know how to use it. \n\nTell you what, you bring me a shipment's worth and I'll go halfsies on the profits with ya!", objectives = "Acquire 25 Chunks of Sivstone.", progress = "You get the goods?", completion = "Nice haul! This should get us started back in Mmarl and show those goons who's who. \n\nHere's your cut." }
WordHunterWoW_QuestEN[78906] = { title = "Hello World", description = "", objectives = "" }
WordHunterWoW_QuestEN[78915] = { title = "Squashing the Threat", description = "I need your help!\n\nThe massive Shadow-Soured squash have begun to grow all over the place. They're stinky and crawling with nasty mites.\n\nMom and Dad brought in some airships to help us yank them out, but it's risky business with all those bugs.\n\nCan you attach ropes to these Shadow-Soured Squash, and the airships can then haul them away without making a mess?", objectives = "Remove 8 Shadow-Sour Squash and slay 10 Shadow-Sour Mites.", progress = "Have you removed all the Squash?", completion = "You did it! I heard stories of one time the squash was so heavy the airship crashed! Glad that didn't happen." }
WordHunterWoW_QuestEN[78918] = { title = "Brax's Brass Knuckles", description = "I have a proposition for you.\n\nWe get some rowdy patrons here from time to time. Nothing sinister, but our folk work hard and things can get out of hand faster than a dropped hammer. \n\nUsually I'd give 'em a considerate knock upside the head to remind them what's what, but I lost my brass knuckles while helping Watcher Toki clear monsters on the town's skirts.\n\nMind fetching my knuckles and administering some love taps?", objectives = "Kill creatures around Gundargaz to find Brax's Brass Knuckles.", progress = "Now which beasts did I punch with those knuckles last...", completion = "That's the genius of the knuckles. They keep your hands intact!" }
WordHunterWoW_QuestEN[78929] = { title = "Tricks of the Dark", description = "Kobyss lurk in the shallows of murky water and snatch any who come near, faster than a viper!\n\nAnd that's just when they hunt alone. In numbers, they are a swarm to be reckoned with. They've been a plague on our outskirt villages since the day we arrived. \n\nThey eat victims alive, given the chance. We must rescue the villagers that have already been dragged to the water!", objectives = "Rescue 5 Arathi captives.", completion = "Thank you, <name>. These people are badly hurt, but I think they will make it. Some seem to have some skill in healing of their own." }
WordHunterWoW_QuestEN[78931] = { title = "Technoscrying: The Mysteries of Dragonskull Island", description = "", objectives = "" }
WordHunterWoW_QuestEN[78932] = { title = "Fickle Fiendish Fish", description = "Judging by the glint in your eye, you wish to join Faerin in this madness?\n\nTo push into the kobyss waters? In the darkness?\n\nYou are a fool with a death wish. \n\nTake as many of those damnable fish out as you can, before they drag you into the depths for their dinner.", objectives = "Kill 13 kobyss invaders.", progress = "We can't abandon the villagers here!", completion = "These foes are relentless." }
WordHunterWoW_QuestEN[78933] = { title = "The Sweet Eclipse", description = "I've set out to create a dessert that transcends the ordinary, one that even the most devout followers of the light would savor!\n\nTo balance the flavors of the desert, between light and shadow, I require ingredients from several areas within the darkness.\n\nPlease assist me in harvesting the following ingredients: Frog-Kissed Caviar, Darkroot Persimmon and Ethereal Sugar.", objectives = "Collect 8 Darkroot Persimmon, 30 Frog-Kissed Caviar, and 1 Ethereal Sugar.", progress = "Have you found all of the ingredients?", completion = "Now the magic happens. Please sample this creation for yourself." }
WordHunterWoW_QuestEN[78934] = { title = "Blades of the Arathi", description = "I trust in your strength. I must ask you to go ahead to reinforce Sina's Yearning. Anduin and I can see my people to safety in Lorel's Crossing.\n\nWith the darkness and the kobyss, the hearts of my people in Sina's Yearning will be faltering to fear. We can't let them wallow.\n\nLight a torch with the Sacred Flame in the center of town and use it to inspire my people's valor. Remind them of their strength.\n\nWe will catch up with you. May the Flame guide you, my friend.", objectives = "Light a torch with the Sacred Flame, then rally 6 groups of Arathi in Sina's Yearning.", completion = "The Arathi are strong. Proud. The kobyss may be vile but they will not win this day." }
WordHunterWoW_QuestEN[78936] = { title = "Something's Fishy", description = "So you outsiders and Faerin managed to both survive and save the villagers at the beach? \n\n<Steelstrike breathes a quick prayer in relief.> \n\nWe're in trouble, here. The kobyss brought some of their strongest forces to the doorsteps of villagers. \n\nWe have our hands full just holding the line. If you can take out those monsters, we might be able to turn the tide.", objectives = "Slay Deepsludger, The Abominable Wavecrasher, and Tidelord Teethwretch in Sina's Yearning.", progress = "When we first encountered the kobyss, there were those among us who tried to establish peace with them. But it quickly became apparent that they only see us as food.", completion = "Every Arathi has killed more kobyss than I care to count. We've also lost more Arathi to kobyss than I want to count. \n\nI don't know what underwater cavern they hail from... but I shudder to think of it." }
WordHunterWoW_QuestEN[78937] = { title = "Shadow upon Shadow", description = "<Faerin's wide eyes dart around in surprise.>\n\nWhat just happened? Did you see that shadow? And the oil well... it's gone dark? \n\nI've never seen anything like this before. \n\nCould it be the nearby dawntower? Hurry!", objectives = "Investigate the nearby dawntower.", completion = "The fear and shame of these people lingers in the air like a fog." }
WordHunterWoW_QuestEN[78938] = { title = "Champion of the Waterlords", description = "I regret to inform you that a horrific threat awaits your kind within this mortal realm. An Elemental Lord of Fire, Ragnaros, bides his time waiting to strike and burn your Azeroth to its core. We, the elements of water, have waged war eternal with those beings of the lesser elementals. Trust that our warning is no small thing.\n\nProve your conviction! Slay Ragnaros, once and for all!", objectives = "Defeat Remembered Ragnaros during a Radiant Echoes event.", progress = "Ragnaros yet remains, mortal. His foul heat emanates from nearby.", completion = "You have done what most of your kind would think impossible. You have faced Ragnaros and triumphed!\n\nFor so small a creature, you have displayed great resource.\n\nSome day, perhaps we might strike a true allegiance between your kind and the Waterlords." }
WordHunterWoW_QuestEN[78939] = { title = "The Darkened Flame", description = "This... Order of Night, as they call themselves, did some foul ritual to turn the tower's flame to darkness. I know not what.\n\nWe should investigate.", objectives = "Investigate the darkened dawntower.", progress = "My own people... how could they? \n\n<Faerin shakes her head in disbelief.>", completion = "So, they killed Kelther, too? \n\n<Faerin squeezes her eyes shut and mouths a prayer and a curse at the same time.>\n\nWe'll make sure he gets a proper funeral. The Order of Night will pay for this.\n\nWe sealed off Gloomcrag, the nearby cave, years ago. They must have dug their way in so they could target this dawntower. \n\nHow long have they been planning this? How long has the Order of Night been among our ranks?" }
WordHunterWoW_QuestEN[78940] = { title = "Quest 00", description = "Placeholder for RP/Pacing as needed.", objectives = "Placeholder for RP/Pacing as needed.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[78941] = { title = "A Tide Needing Turned", description = "Xal'atath's army has been capable of striking at us for a while now. So what caused her to choose this moment?\n\nSomething is wrong here. She waited for us to build an army in response, and then attacks openly. We're playing into her hands.\n\nReport to the Arathi general. I'll head to the battlefield directly.", objectives = "Meet with General Steelstrike in Hallowfall.", completion = "Good, you're here. I'll keep it brief." }
WordHunterWoW_QuestEN[78942] = { title = "The Might of Khaz Algar", description = "The Harbinger thinks she can catch us off guard, but she's a fool if she expects to win this fight.\n\nThe Algari Offensive stands at your back, {name}. Spare no enemy.", objectives = "Fight back against the nerubians.", completion = "Your Horde and Alliance make a formidable army. I don't think there's much we could have done without them." }
WordHunterWoW_QuestEN[78943] = { title = "Steel and Flames", description = "Our forces may be able to hold their own, but seeing you in the fray may help their spirits. \n\nTake this warhorn. Let it ring out and fill our foes with terror. Once you're done rallying our troops, make your way to your commanders.", objectives = "Rally 20 Algari Offensive troops.", completion = "You've arrived just in time." }
WordHunterWoW_QuestEN[78948] = { title = "A Light in the Dark", description = "Something is very wrong. As the battle continues, each side has become more aggressive.\n\nAlleria seems to know something - she ran off at one point during the battle. We've been giving chase, but I cannot leave these soldiers to die. She's just ahead, we can reconvene with her together.", objectives = "Speak with Anduin and chase down Xal'atath.", completion = "Khadgar will need immediate help. We will have time for celebrations later." }
WordHunterWoW_QuestEN[78950] = { title = "Cutting Off the Legs", description = "While we've yet to locate Xal'atath, we've received reports from deeper in the field of certain nerubians giving orders. It won't buy us too much but every action is critical.\n\nTake them out. Hopefully that will allow us some breathing room. \n\nSpeak with Anduin after you are done. He and the Arathi girl went after Alleria.", objectives = "Slay the nerubian lieutenants.", progress = "Speak with Anduin within the Sanguine Grasps.", completion = "Oh, good, you made it." }
WordHunterWoW_QuestEN[78951] = { title = "Ever Deeper Shadow", description = "When I reached for the Flame, I felt the overwhelming hopelessness and despair that had been poured into it. \n\nIt pains me, but... my light alone is not enough to banish these shadows. \n\nAnd so, we take a more direct path. If the remaining cultists have withdrawn to Gloomcrag Bower, their combined power must be what's keeping the Flame dark. \n\nWe must stop them before this darkness spreads.", objectives = "Slay 10 Order of Night cultists in the cave beneath the Cliffside Beacon.", progress = "These were once my people. My allies. My mentors. \n\nI once tried to reason with them. Tried to make them see the Light... see that the Light is still within us all.\n\n<Faerin's face flickers between sadness and anger.>\n\nThey wouldn't listen. And they're killing innocents. \n\nI can't hesitate. Not anymore.", completion = "<Faerin's jaw is firm.> \n\nThey made their choice." }
WordHunterWoW_QuestEN[78952] = { title = "The Final Resistance", description = "<Faerin speaks in a hushed, furious whisper.>\n\nGood work. But before we can leave, there's something else. \n\nDown this way are some powerful priests. I think they are summoning something-- something big. No doubt to strike at us above and drive us from the tower itself.\n\nIt will be dangerous, but we must stop them. Are you with me?", objectives = "Destroy the Shadow Rift.", completion = "<Faerin's eyes are dark with weariness.> \n\nIt never ends, does it?" }
WordHunterWoW_QuestEN[78954] = { title = "Restore the Flame", description = "Do you feel it? Hope, returning? \n\nThank you for your help, {name}.\n\nThe dawntower's flame remains dark. But this time, I think we'll be able to restore it. \n\nLet's meet at the tower.", objectives = "Help Faerin restore the Holy Flame at the Cliffside Beacon.", progress = "I only hope that together, we can kindle a little more light in our little world.", completion = "<Faerin gives a warm, tired smile.> \n\nThank you. Thank the Light you all arrived when you did. I'm glad we can help each other." }
WordHunterWoW_QuestEN[78972] = { title = "Harvest Havoc", description = "Our parents went off to fight the monsters that invaded our farm. While they are gone, we try to keep the farm running. \n\nWe have a harvestbot to help with chores, but I keep crashing it into the river. We could finish our chores if you could help us drive the harvestbot!", objectives = "Control Harvestbot Remy to load 4 Cabbage and 4 Carrots into carts. In addition slay 12 Invasive Beetles.", progress = "Have you completed the chores?", completion = "You were really good at controlling Remy.  Maybe you can come back and help next week as well!" }
WordHunterWoW_QuestEN[78974] = { title = "Beetle-Minded", description = "", objectives = "" }
WordHunterWoW_QuestEN[78978] = { title = "Raising a Stink", description = "Those clues add up to an ugly story, {name}.\n\nThat map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic.\n\nI've got a gal that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", objectives = "Meet Detective Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.", completion = "There you are, right on time.\n\nI've got a plan to deal with this chemical conspiracy." }
WordHunterWoW_QuestEN[78979] = { title = "Loving Yourself, Your Way", description = "While visiting this gala, I am staying at the Razor Hill inn. It may not look like much, but it is surprisingly comfortable!\n\nWhy don't you see if they have any extra beds you could use?\n\nI think I will have a bit of a rest too... Right... here...", objectives = "Take a nap in the inn at Razor Hill.", progress = "<Ning is quietly snoring.>", completion = "...Huh? Oh! Welcome back, did you enjoy your rest?\n\nOn any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all." }
WordHunterWoW_QuestEN[78980] = { title = "Take a Look Around", description = "Here at the Gala of Gifts, we have many wonderful artisans crafting gifts just for you and your loved ones. But don't take my word for it--there are plenty of attendees enjoying the festivities as well!\n\nGo, speak to the visitors, and see what the artisans have to offer. Maybe you will find the perfect gift!", objectives = "Meet the vendors and visitors at the Gala of Gifts.", progress = "Are you having a good time?", completion = "As you can see, there are plenty of gifts to be given!\n\nGo get a gift for someone you care about!" }
WordHunterWoW_QuestEN[78981] = { title = "Love is in the Air", description = "Smell these roses! My partner got them for me at the Gala of Gifts.\n\nInterested in seeing things yourself? Head to Durotar. There are gifts, and food, and you should taste the chocolate, it's delicious!", objectives = "Visit the Gala of Gifts in Durotar, near Rocktusk Farm.", completion = "Welcome to the Gala, friend!\n\nWould you like to hear more about our specialty chocolates?" }
WordHunterWoW_QuestEN[78982] = { title = "I Smell Trouble", description = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it?\n\nWell, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away!\n\nAre you in? I could use a good partner to solve this.", objectives = "Use O.D.I.E.'s Remote Control to find clues around Orgrimmar.", progress = "Sure, O.D.I.E. can sniff out the clues, but you still gotta piece 'em together.", completion = "Poisonous perfumes? Revenge for kicking 'em out of the city?\n\nSeems like Apothecary Hummel is cooking up something sinister. This could get ugly." }
WordHunterWoW_QuestEN[78983] = { title = "An Unwelcome Gift", description = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent!\n\nBut let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", objectives = "Kill 8 Crown Chemical Co. members around Orgrimmar.", progress = "Follow your nose, pal! Anyone who stinks could be a suspect.", completion = "Yeesh, <name>, you reek!\n\n\n\nEven worse! I reek!\n\nWell at least we've given some peace to the gala. I'd hate to have the Crown ruining the celebrations." }
WordHunterWoW_QuestEN[78984] = { title = "Crushing the Crown", description = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver.\n\n<Snagglebolt points to the unmarked box.>\n\nBombs. I got bombs.\n\nPlaytime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", objectives = "Use the Artisanal Bon-Bombs to destroy Crown supplies and kill Crown members.", progress = "We need to put a stop to this before the Crown pulls off their smelly sabotage.", completion = "Man, I love a good fireworks show! Great job, <name>. That oughta slow them down.\n\nNow there's just Hummel to deal with." }
WordHunterWoW_QuestEN[78985] = { title = "The Stench of Revenge", description = "We're never gonna see an end to this unless we take on the boss himself.\n\nLook, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Orgrimmar if we let him finish his research.\n\nYou go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", objectives = "Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel.", progress = "You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.", completion = "Sounds like you got there just in time--great work.\n\nThis would have gotten real ugly if Hummel poisoned the entire gala.\n\nLet's just call this our gift to them, eh?" }
WordHunterWoW_QuestEN[78986] = { title = "Getaway to Scenic Grizzly Hills!", description = "Good morrow! Today's special portal is a magical getaway to the majestic forests of Northrend!\n\nAlthough perhaps I could beg you for a favor. You seem the adventurous type. \n\nI could use your help in delivering some flowers from Grizzly hills to a beautiful woman named Laverne. \n\nI would do it myself but... Well, you see, she is rather intimidating in her beauty.", objectives = "Take the Scenic Getaway Portal to Grizzly Hills to pick a bouquet of flowers for Laverne.", progress = "The mage conjuring portals?\n\n<Laverne giggles.>\n\nLet me see.", completion = "This gala is quite marvelous for making new discoveries...\n\n<Laverne idly picks at the flowers while staring in the direction of Aurora.>" }
WordHunterWoW_QuestEN[78987] = { title = "Getaway to Scenic Nagrand!", description = "Good morrow! Today's special portal is a magical getaway to the great plains of Nagrand!\n\nWould you, perchance, be interested in a proposition? I will lend you my camera if you could deliver any photographs you take to my dear friend Karn.\n\nHe has been adrift in Nagrand as of late, lost in his own thoughts. As stubborn as he is, I'm sure he will appreciate the company. I would do it myself, but I must maintain the portals here.", objectives = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Karn.", progress = "How is Karn? When last I saw him, he seemed drowned in regrets and loneliness.", completion = "He asked you to do WHAT?\n\nHe knows that Laverne is--ARGGH! This is my justice, I suppose, for not acting sooner on matters of my own heart.\n\nNo matter. Everything is fine, Aurora, this is fine...\n\nErm, thank you regardless, <name>. The thorns of my roses need not rest in your hands. I will find another way to gain Laverne's attention." }
WordHunterWoW_QuestEN[78988] = { title = "Getaway to Scenic Feralas!", description = "Good morrow! Today's special portal is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited!\n\nUnfortunately, some of our festival attendees who took this portal earlier left their gifts here at the gala.\n\nCould you perchance help me return them? I will meet you at the beach and together we shall be able to determine which gifts belong to whom.", objectives = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients.", progress = "There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", completion = "You are wonderfully helpful, <name>. You have brightened the spirits of many people by returning their gifts to them.\n\nAnd what an array of gifts they were! Perhaps the language of love looks different to everyone." }
WordHunterWoW_QuestEN[78989] = { title = "The Gift of Self-Care", description = "The eyes of a tired adventurer.\n\nA {class} that does many great deeds for many people. When was the last time you did a kind gesture for yourself? \n\nPerhaps now is the time. Look into your heart. \n\nWhat do YOU desire?", objectives = "Speak with Ning to discover your heart's desire.", progress = "Love is a blessing, especially if it comes from within.", completion = "Let us begin your journey to self-love." }
WordHunterWoW_QuestEN[78990] = { title = "The Gift of Relief", description = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. \n\nI saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress.\n\nPerhaps he has insight to teach you.", objectives = "Speak to Tokag Bonebreaker at the Gala of Gifts, then relieve your stress in Orgrimmar.", progress = "I've seen men die of stress, you don't want to bottle it up every day.", completion = "Feeling better? \n\nYou must take care of your body after a tough day. Be good to your head and heart and they'll be good to you." }
WordHunterWoW_QuestEN[78991] = { title = "The Gift of Relaxation", description = "Love is a gift, yes. But it is also a gift that you can give yourself.\n\nSometimes, the best way to love yourself is simply to relax.\n\nI met a troll across the Southfury River who seems particularly wise in this regard. Perhaps you could ask her for insights in the art of relaxation.", objectives = "Speak with Jaz the Reborn about relaxation, then relax by Southfury River in the Northern Barrens.", progress = "True love is letting ya guard down. Let yourself relax, you'll see what I mean.", completion = "Ya feel renewed, don't ya? We all got ta relax from da problems in our lives.\n\nRelaxin' has helped me re-discover who I was. Changed my whole life! I used to have tusks out to here and a mohawk, bwahaha! What a stupid boy I was.\n\nDid ya discover anyting about yourself?" }
WordHunterWoW_QuestEN[78992] = { title = "Loving Yourself, Your Way", description = "If it's a challenge you're after, I think I have an idea.\n\nI saw a boastful champion heading toward Razor Hill. You could challenge him to a duel.\n\nThis would satisfy your desire and perhaps teach him a valuable lesson in humility.", objectives = "Defeat Poggchug Ragethrower in a duel near the road to Razor Hill.", progress = "How fares your challenge?", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all." }
WordHunterWoW_QuestEN[78993] = { title = "Loving Yourself, Your Way", description = "A full belly is a happy belly!\n\nThere is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", objectives = "Consume Packages of treats from vendors at the Gala of Gifts.", progress = "Have you had your fill of treats? I love the fruits, myself.", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all." }
WordHunterWoW_QuestEN[78995] = { title = "Truffle Shuffle", description = "", objectives = "" }
WordHunterWoW_QuestEN[78996] = { title = "Weapons and Warriors", description = "Gorloc raiders have been slaughtering these farmers and stealing their pearls. They seek our protection, but we may not be enough.\n\nI know of others nearby who can help. Seek them out and request their aid. If they are hesitant, offer them the promise of pearls as payment.\n\nWe will also need to arm these farmers so they can defend themselves. Search for spare weapons and equipment that they might be able to use.\n\nI will go with the farmers and train them as best I can.", objectives = "Collect 3 weapon crates and recruit 5 warriors from Freywold Village and Dhar Durgaz.", completion = "Good work. I'm glad you were able to recruit some fighters. It is worse than I expected, and we will need every one we have." }
WordHunterWoW_QuestEN[78997] = { title = "Pilfered Pearls", description = "The pearls that these farmers harvest are their only source of livelihood. Some of these earthen even look at pearl farming as their primary reason for existing.\n\nThe gorlocs continue to pilfer pearls at every opportunity. As you eliminate the gorlocs, search them for stolen pearls. Let us recover as many as we can.", objectives = "Retrieve 8 Pilfered Pearls from gorlocs at the Glimmering Shore.", progress = "We need to return these pearls to the farmers.", completion = "Thank you <name>. Eliminating the gorloc threat was just one of our objectives here. Giving the farmers their lives back is another." }
WordHunterWoW_QuestEN[78998] = { title = "Frontline Farmers", description = "Most of the farmers are already out in the field, defending their positions. I have trained them as best I could given the circumstances, but they are still wielding farming tools. \n\nI need you to distribute the weapons you gathered to those on the frontlines. While it may not markedly improve their combat ability, at least it will boost their confidence that they are not alone in this fight.", objectives = "Distribute 3 weapon crates to the pearl farmers at Glimmering Shore.", completion = "Excellent. As long as they fight together and for each other, I believe we will be victorious." }
WordHunterWoW_QuestEN[78999] = { title = "Heart of a Hero", description = "It seems the gorlocs have been bolstering their forces with summoned elementals. That explains how they were able to overrun the farmers so easily.\n\nIt will take all of our strength to hold off the colossi already in the field. I need you to stop any new elementals from being created.\n\nElementals of this size and power can only be created by the most powerful of gorloc shaman. Seek them out behind enemy lines and eliminate them.\n\nThis should end the gorloc threat to the farmers once and for all.", objectives = "Defeat the three gorloc shaman leaders.", completion = "Thank you for your aid stranger. Without you, none of this would have been possible. You have given us back our livelihood today, and our hope.\n\nTake this as a small token of our gratitude. It is not enough, but it is all we can offer. Know that you will always be welcome among our people.\n\nLet us now turn our attention to Aggartha." }
WordHunterWoW_QuestEN[79000] = { title = "[DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[79006] = { title = "Faction Switch", description = "Default", objectives = "Default" }
WordHunterWoW_QuestEN[79009] = { title = "The Harbinger", description = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger...\n\nLet us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", objectives = "Meet Khadgar and Alleria in the Chamber of the Guardian in Dalaran.", progress = "A Radiant Song, a Dark Heart, and this mysterious Harbinger... What could it all mean?", completion = "We know Iridikron gave the Dark Heart to the Harbinger. But what the Dark Heart is, what the Harbinger plans to do with it... Those are mysteries still.\n\nAnd the Radiant Song. Its timing is no coincidence.\n\nThis matter can no longer wait. That is why I've asked you and Alleria to investigate." }
WordHunterWoW_QuestEN[79010] = { title = "Door to the Ren'dorei", description = "If this investigation involves the Void, it would be wise to consult the void elves. We must head to Telogrus Rift and report the situation.\n\nI'll speak with Umbric. He'll be able to mobilize the Riftwalkers to our cause.", objectives = "Follow Alleria to Telogrus Rift.", completion = "We'll need to hear the Riftwalkers' reports before starting our own investigation. Perhaps there will be something that tells us where to begin." }
WordHunterWoW_QuestEN[79011] = { title = "Riftwalker Reports", description = "The Riftwalkers are tasked with investigating all void activity that appears on Azeroth. A most vital duty, given how dangerous this dark force can be. And I speak from experience.\n\nMany of them were sent out on assignment to investigate recent fluctuations. I've been told they just arrived back, but have yet to hear their reports.\n \nWould you check in on them while I speak with Alleria?", objectives = "Gather reports from Riftwalkers in Telogrus Rift.", progress = "Let me know when you have those Riftwalker reports.", completion = "Thank you for gathering reports. Unfortunately, the Riftwalker from Northrend has yet to return.\n\nShe was investigating void activity in Galakrond's Rest. Given that location's connection to the Dark Heart, I'd suggest you search for her. \n\nLet's just hope our Riftwalker is still around to give you her report." }
WordHunterWoW_QuestEN[79012] = { title = "Cracks in the Void", description = "Telogrus Rift has always been extremely sensitive to cosmic shifts. It makes for a rather precarious homestead, but the void elves have... few options available to us.\n\nThe recent influx in void energies has resulted in unstable rifts opening sporadically. And with so many investigating Azeroth, I'm having trouble finding Riftwalkers to deal with them.\n\nCould you close any unstable void rifts you find along your path?", objectives = "Close 5 Unstable Void Rifts in Telogrus Rift.", progress = "Normally the Riftwalkers would be the ones to mend these sort of anomalies. But I wouldn't want to distract from their current investigations.", completion = "Excellent work.\n\nThose unstable void rifts threaten more than just our reality. If left unchecked, they would spread rampantly like little cosmic prions. No reality, no possibility, no truth that could possibly be would be safe from them.\n\nWhich is all to say, you did us quite the favor by closing them." }
WordHunterWoW_QuestEN[79013] = { title = "Galakrond's Unrest", description = "Galakrond's Rest. Where the Dark Heart was first empowered by Iridikron. We don't know what power the relic holds, but we do know that the Harbinger now wields it.\n\nAnd now one of our Riftwalkers is missing, right where it all began.\n\nI don't believe this is a coincidence, {name}. Let's travel to Northrend and search the area.", objectives = "Meet Alleria at Galakrond's Rest in Dragonblight.", completion = "Time to find our Riftwalker. And, if we're lucky, discover a clue about the Dark Heart and this Harbinger who wields it." }
WordHunterWoW_QuestEN[79014] = { title = "Walk a Mile in Her Shadows", description = "I don't often work with the Riftwalkers. I prefer to handle missions alone. Still, I will not abandon one of them.\n\nI cannot yet sense the Riftwalker's presence. Our best path forward is to retrace her steps. \n\nWhich means following the shadows.", objectives = "Uncover the void presence at Galakrond's Rest in Dragonblight.", completion = "We now know why the Riftwalker didn't report back. She's turned against us and serves only the Void now.\n\nThough I wouldn't be surprised if the Harbinger had a hand in this." }
WordHunterWoW_QuestEN[79015] = { title = "Dark Descension", description = "What are these void spawn doing here? Could it be the Harbinger's doing? Some power of the Dark Heart?\n\nWell. I do not mean to stand idly by.\n\nWe must confront the Riftwalker. I don't think she will see reason now, but perhaps she can tell us something.", objectives = "Confront the missing Riftwalker.", progress = "What would the Harbinger want with Ulduar?", completion = "It's my charge to teach the ren'dorei to withstand the Void's whispers. If only I had gotten to the Riftwalker before the Harbinger did...\n\nNilara. Her name was Nilara, wasn't it." }
WordHunterWoW_QuestEN[79016] = { title = "Legacy of the Void", description = "Make no mistake, {name}. I know this is a trap. But if there's any chance this leads us to the Harbinger, we must take that risk.\n\nBe at the ready. We venture forth.", objectives = "Travel to the Triad's Conservatory in Eredath.", completion = "Eredath. I never thought I would return here. Not after the Legion was finally defeated. Not after....\n\nWhy would the Harbinger bring us here?" }
WordHunterWoW_QuestEN[79017] = { title = "The Path Taken", description = "These apparitions before us. I believe they're... memories. My memories. Is this the Harbinger's doing? Or mine?\n\nWe need to explore. Discover why we were led here.", objectives = "Witness Alleria's memories in Eredath.", progress = "Suddenly, this all feels rather personal. The Harbinger must have a grievance against me. Or at least an... interest. Hm.", completion = "We're finding the Harbinger and leaving this place. Now." }
WordHunterWoW_QuestEN[79018] = { title = "And Be One Traveler, Long I Stood", description = "I sense another memory ahead.\n\nWhile I'm loath to play along with the Harbinger's game, it's the only path forward for us.\n\nStill, we have faced just as many dangerous memories as peaceful ones. Prepare yourself.", objectives = "Investigate the final memory at the Triad's Conservatory in Eredath.", completion = "The Harbinger dares to use my people, my memories, my love against me? \n\nThen she will know what it means to be my enemy." }
WordHunterWoW_QuestEN[79019] = { title = "Defend Telogrus Rift", description = "No. Not the ren'dorei. Not Telogrus Rift. Not today.\n\n<Alleria tightens her grip on her bow.>\n\nThese ethereal forces are the same we encountered in Ulduar. The Harbinger must command them. \n\nI'll go ahead. Engage the enemies here.", objectives = "Defend Telogrus Rift.", progress = "My people can defend themselves, but even they will struggle against such an overwhelming force. We must aid them.", completion = "There's no end to these void spawn. But for now, we must turn our attention elsewhere." }
WordHunterWoW_QuestEN[79020] = { title = "Null and Void", description = "We must defeat that loathsome apparition of Turalyon.\n\nThe abomination's presence is intolerable. If left unchecked, it may destroy what remains of Telogrus Rift. \n\nI will end it with my own hands.", objectives = "Defeat the Corrupted Memory of Turalyon in Telogrus Rift.", completion = "There was once a time when I wouldn't have hesitated. When I would have struck that apparition down with a clear heart. Even if it wore the face of my beloved.\n\nBut something changed. I changed...\n\nGo. Speak with Locus-Walker. It seems he knows more than we do." }
WordHunterWoW_QuestEN[79021] = { title = "Radiant Warnings", description = "So she goes by Harbinger now, does she? How fitting.\n\nI no longer feel her presence, but make no mistake. Xal'atath's nefarious games continue. And Alleria is now a pawn upon her board.\n\nAs are you, champion of fate.", objectives = "Deliver Locus-Walker's warning to Khadgar in Dalaran.", progress = "Telogrus Rift should no longer tempt Xal'atath. For now.", completion = "The Harbinger is Xal'atath? And she's already attacked Telogrus Rift. \n\nThis is most serious, <name>. I'm afraid we have no more time for investigations.\n\nIf Locus-Walker is right, the answer will lie within the Radiant Song. We must discover what it means." }
WordHunterWoW_QuestEN[79022] = { title = "A Mysterious Signal", description = "High Speaker Brinthe has sent an urgent missive for you, {name}.\n\nShe is eager to assist in the coming war effort, and is investigating a mysterious signal in the Deepforge Golemworks, a defunct golem manufacturing facility in the Ringing Deeps.\n\nCan you meet her there and provide your expertise?", objectives = "Meet Brinthe at the Deepforge Golemworks in the Ringing Deeps.", completion = "<name>, thank you for coming so quickly. I could use your help once again." }
WordHunterWoW_QuestEN[79023] = { title = "Small Friend, Big Plans", description = "I tracked down a distress signal that led me to this little maintenance machine. A curious find, but the real treasure is the defunct war golem facility to the southeast.\n\nIf we can start producing war golems again we'll be able to contribute to the war effort. Unfortunately, it's been overrun by a goblin salvage group. And we'll need to investigate and assess if the facility is functional.\n\nFortunately, I have a plan, and it involves our little friend here. Why don't you introduce yourself?", objectives = "Introduce yourself to the maintenance machine.", progress = "With your assistance, I think we can find a way to clear this place out.", completion = "Now that introductions are out of the way. Let's sneak our way into this facility." }
WordHunterWoW_QuestEN[79024] = { title = "Factory Recon", description = "ZZ-01-47 should be able to make its way in there without drawing too much attention.\n\nBut be careful! These goblins are hungry for raw materials. If they spot our bot, they won't show it mercy.", objectives = "Employ ZZ-01-47 to scout the Golem Factory.", progress = "Zee-Zee shouldn't be in much danger, as long as she stays away from the big mechs.", completion = "So we're contending with a lack of power, materials, and a dangerous amount of goblins.\n\nIf I had pores like an outlander, they'd be excreting moisture right about now. Is that proper terminology? I've seen your skin weep moisture before. Remarkable." }
WordHunterWoW_QuestEN[79025] = { title = "A Plan Comes Together", description = "We have our work cut out for us, {name}. But I think, with Dagran's help, we can break this down and tackle it piece by piece.\n\nWhy don't you take us through what we've learned so far.", objectives = "Go over the plan with Brinthe and Dagran.", progress = "We're some of the greatest minds in... well Gundargaz, at least. We can figure this out.", completion = "We need to secure the Waterworks and get the Shadowvein Excavation site up and running before we head back to the factory.\n\nLet's get to work." }
WordHunterWoW_QuestEN[79026] = { title = "Putting the Works in Waterworks", description = "Overly enthusiastic kobolds, angry elementals, and a broken-down power plant. This place is in shambles!\n\nDo you spot those large wheels on each side? They should be moving, but they're not. We'll need to get those moving again if we want this place to come back to life.", objectives = "Get the Waterworks running again.", progress = "I wonder if we could use this technology to rebuild the Stonewrought Dam? Wouldn't that be something.", completion = "Wowiee look at it go! \n\nJust a fraction of Azeroth's power, harnessed for its protection." }
WordHunterWoW_QuestEN[79027] = { title = "Elemental Trepidation", description = "<ZZ-01-47 twitches back and forth, sensors scanning unceasingly. They seem afraid of this area, if they're even capable of feeling fear. Maybe clearing out some of the elementals will set them at ease.>", objectives = "Defeat elementals.", progress = "I appreciate what you're doing for Zee-Zee.\n\nAnd they appreciate it, too.", completion = "Thanks. I'm sure Zee-Zee appreciates it. When we're done here you can find them at the Shadowvein Extraction site." }
WordHunterWoW_QuestEN[79028] = { title = "We Require More Minerals", description = "Zee-Zee is ready to help you get the Shadowvein site up and running again.", objectives = "Get the Shadowvein site up and running.", progress = "<Zee-Zee emits an inquisitive beep.>", completion = "<Zee-Zee whistles in relief. It seems they were not happy with the subpar maintenance standards here.>" }
WordHunterWoW_QuestEN[79029] = { title = "It's Sabotage", description = "We're back, and we're ready.\n\nYou and ZZ-01-47 head in and cause some mayhem. Blow stuff up and make a mess that will draw them out of the manufacturing bay. I'll use the commotion to sneak inside. Join me when you're able, and we should have a chance at reactivating the facility and driving them out.\n\nWe don't need to defeat them all. Defeating the Darkfuse leader supervising this operation should break their resolve.\n\nThe Darkfuse lackeys will clear out when the coin stops flowing.", objectives = "Wreak havoc, gain access to the manufacturing bay, and restart the facility.", completion = "It was touch and go there for a bit. But if anyone could seize a victory out of this, I knew it would be you.\n\nPlease return to the Emissary in Dornogal and communicate our victory. Go with my thanks, and with the knowledge that the Machine Speakers are indebted to you. Again." }
WordHunterWoW_QuestEN[79030] = { title = "The Voice of the Speakers", description = "Please take word of our victory to Alleria in Dornogal. I'm sure our allies will be pleased to hear what we can provide for the war effort.", objectives = "Return to Alleria in Dornogal.", completion = "What amazing news, <name>!\n\nThe War Golems awaken, and march against our enemies once again, just like in times past.\n\nYour contribution to the cause of the Machine Speakers, and to all of the Earthen, will not be forgotten." }
WordHunterWoW_QuestEN[79074] = { title = "Summoning All Soldiers!", description = "The Artisan's Consortium has struck one final deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this brochure to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", objectives = "Deliver the brochure to Calderax in the Gladiator's Refuge of Valdrakken.", completion = "<Calderax grumbles something under his breath before proceeding with a very well practiced speech.>\n\nHere are your trophies, as promised. Use them when crafting your own equipment or submitting Crafting Orders and the gear will be comparable in power to what I offer. It is perfect if you are looking for something highly specific or imbued with a certain embellishment... and are willing to put in some extra work.\n\nQuestions? Take them to the Artisan's Market." }
WordHunterWoW_QuestEN[79082] = { title = "The Superbloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[79085] = { title = "A Pile of Fish", description = "<A pile of fish, perhaps these could be transported by cart back to Seraphine Seedheart.>", objectives = "Load 4 Fish onto Fish Cart-Pusher." }
WordHunterWoW_QuestEN[79087] = { title = "A Pile of Clams", description = "<A pile of clams, perhaps these could be transported by cart back to Seraphine Seedheart.>", objectives = "Load 4 Clams onto Clam Cart-Pusher." }
WordHunterWoW_QuestEN[79089] = { title = "Consecrated Cleanup", description = "Our Veneration Grounds have been desecrated. Its beauty marred. \n\nIt's going to take a bigger effort, but I would appreciate anything you can do to cleanup our grounds.", objectives = "Restore the Veneration Grounds in Hallowfall.", progress = "I wish you could have seen this place before the Kobyss arrived.", completion = "Thank you, <name>. It may not have seemed like much, but this is one of our most sacred places. \n\nWe remember our dead here. We... have a lot to remember." }
WordHunterWoW_QuestEN[79105] = { title = "Breach", description = "As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. \n\nRescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.", objectives = "Send civilians to the landing for safety.", completion = "That's the first group evacuated. But we're not done yet." }
WordHunterWoW_QuestEN[79106] = { title = "Rupture", description = "Follow me. We'll work together to find any others in need of rescuing.", objectives = "Save Dalaran.", progress = "The nerubians are capturing anyone they can and stringing them up in webs. Make sure to free whoever you find before moving on.", completion = "Looks like we saved who we could. Let's just hope the other rogues escaped." }
WordHunterWoW_QuestEN[79107] = { title = "After the Storm", description = "Turalyon and Geya'rah are training our new earthen allies as ground forces. But we will need more than that. We will need the Stormriders. \n\nMany were lost in the infiltration of the Stormperch and more to the nerubians. Their leader, Stormward Baelgrim, died valiantly.\n\nThe surviving Stormriders are being cared for at a triage station nearby. We need to do whatever is necessary to get them and their rooks back in the air. They will be the earthen's most potent weapon in the battles to come.", objectives = "Check on the Stormriders.", completion = "I'm sorry about Shraubendre. She was just protecting me. And I lied to protect her.\n\nBut you truly don't intend to take her away? You just want to summon more stormrooks?" }
WordHunterWoW_QuestEN[79108] = { title = "Seeds of Evil", description = "{class}, some of the shadowleaf plants are more... wrong than the rest. I don't know how to describe it better.\n\nMy idiot brother, Tomothy, was supposed to help me get rid of these, but I haven't seen him and I can't wait.\n\nClearly we don't want these to reproduce so I want you to cull as many as you can find, and then take their seeds. We'll burn those in holy fire to make sure we've cut off the infestation.", objectives = "Collect Corrupted Shadowleaf Seeds.", progress = "Did you cull those plants?", completion = "Good job culling those plants. Now, if only my lazy brother would show up for work." }
WordHunterWoW_QuestEN[79109] = { title = "Follow Miral", description = "Tomothy's lynx, Miral, has been bugging me. I don't know what she wants but it is unusual to see her without my brother. She's a great farm cat, but she's still a cat, so maybe she's just bored with Tomothy today? I don't know. Maybe Tomothy got into some sort of trouble.\n\nCan you find out what is bothering her for me?", objectives = "Discover what is bothering Miral Murder-Mittens.", progress = "<Miral looks at you as if expecting something. You are being judged.>", completion = "<Miral lets out a pleased sound and purrs at you.>" }
WordHunterWoW_QuestEN[79110] = { title = "Save Tomothy", description = "<Miral looks at you expectantly then looks at the ruins, then back to you, then to the ruins. You get the sense she wants you to go over there. Perhaps this is where Tomothy got lost?>", objectives = "Save Tomothy Hillhelm from The Grasping Darkness.", completion = "You saved my idiot brother from the darkness! Thank you." }
WordHunterWoW_QuestEN[79111] = { title = "Missing Lynx", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[79113] = { title = "UNUSED PLACEHOLDER", description = "Upon arriving at a deserted beetle ranch, the player discovers 2 nerubians having an argument. \n\nThe larger of the two storms off in a huff.\n\nThe remaining nerubian informs you that the larger one was assigned to this ranch along with him, and they're Not Having A Good Time.\n\nHe asks you to follow the larger one to the barn.", objectives = "Upon arriving at a deserted beetle ranch, the player discovers 2 nerubians having an argument. \n\nThe larger of the two storms off in a huff.\n\nThe remaining nerubian informs you that the larger one was assigned to this ranch along with him, and they're Not Having A Good Time.\n\nHe asks you to follow the larger one to the barn." }
WordHunterWoW_QuestEN[79114] = { title = "Beautification Project", description = "A fine enough job, for one of your... ilk.\n\nIf you wish to keep breathing, I suggest you continue to assist us. It may even prove lucrative for you, if you comply.\n\nRak-Ush's former master allowed the stagshells to run feral, and abandoned the hollows to decay. Over time, invasive plants have infested the old stagshell hollows.\n\nFind a way to clear them. I don't care how.", objectives = "Clear the Stagshell Hollow of Overgrown Plants.", progress = "It would be unwise to return to me with an unfinished job.", completion = "Hm. It'll do." }
WordHunterWoW_QuestEN[79115] = { title = "Expert Consultant", description = "You alone are no longer sufficient. We require additional assistance, and the jawcrawlers and threadlings also need oversight.\n\nThe niffen settlement, Mmarl, is not far. However, past forced conscription attempts have failed. Nerubians are now forbidden within the settlement. We need someone to communicate in our stead.\n\nGo and barter with the rats. Come back with able bodies.", objectives = "Speak with Mmarl's leader about recruiting swarmhands.", completion = "The nerubians want our help again? I'd like to hear this..." }
WordHunterWoW_QuestEN[79116] = { title = "Spider Optics", description = "", objectives = "" }
WordHunterWoW_QuestEN[79117] = { title = "Bright Young Niffen", description = "You need swarmhands, huh? \n\nLast time the nerubians wanted our help, they tried to force us. They're terrible negotiators! All we wanted was a little quid pro quo.\n\nWe've got several arachnologists, but most of them are busy keeping the flyers at bay. I'm sure they won't refuse an opportunity to study some swarmbeasts up close and personal! \n\nMaybe if you lighten their workload, they'll take you up on your offer.", objectives = "Find 6 Niffen Arachnologists outside Mmarl to join Rak-Ush.", progress = "Have you found anyone yet?", completion = "See? All we wanted was a little something in exchange." }
WordHunterWoW_QuestEN[79118] = { title = "Rak-Ush Under New Management", description = "Well, you got your swarmhands. \n\nWhat are you still doing here? Go on then, you don't need my permission!\n\nMake sure the nerubians treat them fairly, now.", objectives = "Return to Vix'aron in Rak-Ush.", completion = "Excellent." }
WordHunterWoW_QuestEN[79119] = { title = "It's Rough to Be a Bug!", description = "Anub'azal gave his orders! We are the new masters of Rak-Ush! Yet Vix'aron decided to throw a tantrum and destroy our barn instead.\n\nSince this imbecile refuses to follow orders, perhaps you will, overcrawler. Maybe then we will decide not to kill you for eavesdropping. And recompense, I suppose.\n\nGo. We are to restore the stagshell hollows and fill them with swarmbeasts.", objectives = "Clean up the barn in Rak-Ush.", progress = "We need this barn in an operational state!", completion = "Surprisingly, you've proven yourself useful." }
WordHunterWoW_QuestEN[79120] = { title = "Beetle in a Haystack", description = "There are still feral stagshells on the outskirts of Rak-Ush.\n\nThis scent grenade should be sufficient in stunning the beasts and alerting the niffen to their location.\n\nOnce they are stunned, one of the rats will take them back to their hollow.\n\nCapture them and bring them back. We will be waiting.", objectives = "Capture and return six Feral Stagshells to Rak-Ush.", progress = "We still require more stagshells.", completion = "Excellent work." }
WordHunterWoW_QuestEN[79121] = { title = "Bug Test", description = "Oh, I'm sorry, did you think this was a one and done assignment? If you did, Vix'aron would gladly \"show you the door\", as it were. The stagshells will require constant maintenance. Food. Water. Those sorts of things.\n\nLoathe as I am to admit it, the niffen are much more skilled at caring for swarmbeasts than Vix'aron or I.\n\nThey can enlighten you on your duties, if this was not explanation enough.", objectives = "Speak to Aromash and care for the stagshells in Rak-Ush.", progress = "Do not return to me until you have finished your lessons with the niffen.", completion = "I trust that wasn't too complicated for you?" }
WordHunterWoW_QuestEN[79122] = { title = "Scarab Scouting", description = "The stagshells are of the utmost importance to Anub'azal's war campaign. We have a keen sense of smell, but only the stagshells are able to seek out valuable Kaheti truffles. \n\nThe truffles are a key ingredient in several... explosive elixirs, as it were. If you desire details, Aromash can give you more.", objectives = "Use a Rak-Ush Stagshell to find 5 Kaheti truffles.", progress = "We need an abundance of truffles to ensure we are properly prepared.", completion = "That is all that is required of you." }
WordHunterWoW_QuestEN[79123] = { title = "Permanent Hire", description = "Rak-Ush is beginning to look like a functioning swarmery.\n\nThe role of delegation has suited me and Vix'aron well. You will continue to aid the niffen. In return, you may keep a portion of the wealth the swarmbeasts produce. \n\nSaffrin has more detailed plans around the development of the swarmery. Go speak to him, I have nothing else to say to you.", objectives = "Speak with Saffrin in Rak-Ush.", progress = "You have not spoken to Saffrin yet, have you? Otherwise you would not be here.", completion = "These swarmbeasts aren't going to take care of themselves!" }
WordHunterWoW_QuestEN[79124] = { title = "Conduit of the Southern Storm", description = "I'll tell you what I told Baelgrim when we last spoke. The binding of stormrooks is wrong. These creatures are as smart as any earthen. Some I'd say are smarter.\n\nBut... Lufsela seems to be different. If her stormrook follows her willingly, then perhaps others will make that choice as well if she summons them.\n\nTo summon rooks, we need Baelgrim's conduit. It's tucked away here somewhere. Have a look around, and maybe ask these pilgrims if they have seen it.", objectives = "Find the Conduit of the Southern Storm.", progress = "Have you found the conduit?", completion = "Not only was Olbarig once a Stormrider, but he served as Baelgrim's right hand as a Stormguard for a long time. Seems they had a falling out over the rooks.\n\nBut Olbarig says that the conduit will serve as a beacon. If the stormrooks of Skywall are willing, it will guide them through the storm. He also seems to think I should be the one to use it." }
WordHunterWoW_QuestEN[79125] = { title = "The Kalimdor Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Stormwind.", completion = "Thank you for visiting, skyrider!" }
WordHunterWoW_QuestEN[79126] = { title = "The Kalimdor Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Orgrimmar.", completion = "Thank you for visiting, skyrider!" }
WordHunterWoW_QuestEN[79127] = { title = "The Outland Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Stormwind.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[79128] = { title = "The Outland Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Orgrimmar.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[79129] = { title = "Rook Rally", description = "Now that we've got the conduit all charged, I suppose it's time we joined everyone on the peak. \n\nThrall talked me through what to expect, but also said summoning the stormrooks will require me to trust my feelings and instincts.\n\nAn earthen trusting their feelings and instincts. That's... a challenge.\n\nYou will help me, right? I'm not a fighter, and it looks dangerous up there. \n\nIf anything happens to me, make sure Shraubendre makes it out safe. Please.", objectives = "Safeguard the summoning ritual.", completion = "Well done. It seems the rooks of Skywall haven't just answered the call. \n\nThey were reaching out to us, and they have chosen their own riders for this new generation. \n\nI am honored to have played a role in the ritual." }
WordHunterWoW_QuestEN[79130] = { title = "The Northrend Cup Circuit", description = "It is time once again to test your mettle.\n\nMy bronze colleagues have traveled to Northrend to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit!\n\nAre you up to the task?", objectives = "Fly through Northrend Cup courses.", progress = "Have you taken wing today?", completion = "You lead the way among your fellow dragonriders!  If you haven't already, see if you can improve your times in the Northrend Cup and earn the colors of the Riders of Azeroth." }
WordHunterWoW_QuestEN[79131] = { title = "The Northrend Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Valdrakken.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[79132] = { title = "The Northrend Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Stormwind.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[79133] = { title = "The Northrend Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "Visit Lord Andestrasz in Orgrimmar.", completion = "Thank you for visiting, dragonrider!" }
WordHunterWoW_QuestEN[79134] = { title = "A Spring Awakening", description = "The citizens of Goldshire have reported frequent interruptions to their recent festivities. Something about being overrun by angry... ducks? Perhaps you could look further into this conundrum.", objectives = "Speak with Zinnia Brooks at Goldshire in Elwynn Forest.", completion = "Yes! Yes, I think I have just the task for you..." }
WordHunterWoW_QuestEN[79135] = { title = "Quacking Down", description = "Those dratted ducks! Do you mind scaring them off again? I simply cannot leave my golden egg unattended!", objectives = "Scare off 10 ducks using the Horn of Honking.", progress = "Have you sufficiently shooed those ducks yet?", completion = "Oh thank goodness. Those ducks are driving me mad!" }
WordHunterWoW_QuestEN[79136] = { title = "A Spring Awakening", description = "The citizens of Razor Hill have reported frequent interruptions to their recent festivities due to a duck infestation, of all things. Perhaps you could look further into this conundrum.", objectives = "Talk to Sylnaria Fareflame in Razor Hill.", completion = "Yes! Yes, I think I have just the task for you..." }
WordHunterWoW_QuestEN[79137] = { title = "The Wall Between Us", description = "I know this fight was not ours, {name}. But I thank you for your assistance. It was with the Alliance's assistance that Lordaeron was cleansed and the favor has now been returned.\n\nI do not think I can hope for peace. Instead, I will hope that these efforts have led to at least an understanding of the plights of both Gilneans and the Forsaken.\n\nLet us meet with Lilian in Pyrewood Village. This celebration is not for us.", objectives = "Speak with Lilian and Calia in Pyrewood Village.", completion = "Not my idea of a normal request from a friend, but I'll never object to killing more of the Crusade." }
WordHunterWoW_QuestEN[79139] = { title = "Alone in the Dark", description = "My people do not think that this Black Blood is a threat to our world. It has sat dormant for ages, after all. Why should that change now?\n\nBut the world is changing more quickly than my people realize. The nerubians' decision to extract the Blood for their own ends is proof of that.\n\nThe nerubians hold a watchtower not far from here. The ones who survived the pit could not have gotten too far. We should give chase immediately.", objectives = "Investigate the Eye of Ansurek.", progress = "<The spider looks at you expectantly.>", completion = "<The bizarre creature's eyes remain locked upon you, unwavering. It nudges something towards you--a scroll with a thick seal of violet wax.>" }
WordHunterWoW_QuestEN[79140] = { title = "Goldbricking", description = "Is this what we are to rely on to help us defeat Xal'atath? The Unbound define themselves by their desertion. And the Oathsworn, for being made of stone, are pretty soft. City life hasn't done them any favors. \n\nWe've got a lot of work to do.\n\nGet down there and give these earthen a taste of what it's like to face a real threat. Try not to knock any \"offline,\" but a maiming here or there would send a strong message to the rest.", objectives = "Spar with undisciplined earthen trainees.", progress = "Don't go easy on them. They're made of stone after all.", completion = "You lit a fire down there, and we will continue to fan the flames. \n\nGo now, secure in knowing you have helped set these earthen on the path to glory. The nerubians won't know what hit them!" }
WordHunterWoW_QuestEN[79145] = { title = "Metal and Stone", description = "While some of these recruits struggle with discipline, most have a strong work ethic. They only need training and the equipment to make the most of it.\n\nEarthen weaponsmiths and armorers have been working around the clock to equip this fledgling army. But we could use some help getting the new armaments into the hands of these trainees.", objectives = "Equip earthen trainees for battle.", progress = "Check in with Vindicator Jaelaana. She is in charge of distributing the weapons though she can be rather stingy. Be sure she doesn't send too many off for hand-to-hand training.", completion = "Now they're starting to look like a real army. We'll continue with their training, but I believe you have more important matters to attend to." }
WordHunterWoW_QuestEN[79146] = { title = "Ground Pounders", description = "The rooks and their chosen riders will need time to bond. \n\nPerhaps you should use this time to check in on our other trainees. \n\nThe Stormriders are the traditional army of the earthen, but many Unbound and Oathsworn have expressed willingness to fight at our side due to help in restoring their machines.\n\nAdelgonn, Geya'rah, and Turalyon are busy training them. Go and see if they need any assistance.", objectives = "Meet with Adelgonn, Geya'rah, and Turalyon.", completion = "Someone save me from all this bickering. Alliance this, Horde that... \n\nI've never encountered anything like it in my thousands of years even amongst the Oathsworn and Unbound. If they committed half the energy they expend on posturing towards training, our task would be complete by now.\n\nSee what help you can offer my people. They need real mentorship if we are to be ready for the next nerubian offensive." }
WordHunterWoW_QuestEN[79147] = { title = "Flight Training 101", description = "Now that all of our recruits are present, it's high time we took to the air. See what I did there? High time? No?\n\nRight then. We'll be puttin' these rookies through their paces. Startin' with the basics of aerial maneuverin' at speed, we'll do our best to simulate the kind of precision flyin' we might expect below ground. \n\nAfter that, we'll see what these rooks can really do--an I think Thrall and Lufsela have somethin' special cookin'.", objectives = "Help Kurdran train recruits in aerial maneuvering.", progress = "Let's set a good example for these new riders. Lead them through the course as quick as ye can.", completion = "There you have it! Raw recruits made of stone, soarin' on the backs of birds made of lightnin'. Proof that ol' Kurdran can teach anythin' to fly!\n\nBut we're not done yet." }
WordHunterWoW_QuestEN[79148] = { title = "The Nibelgaz Refinery", description = "Quickly! Elementals have overrun the Nibelgaz Mine and the refinery crew are trapped down there with them. \n\nI am especially worried about my fused, Munderut. His memory is not the best these days. If you are a friend, rescue him and the refinery workers.\n\nHere, take this healing clay. It only helps a little, but it should be enough for any injured to make their way back. I wish we had a rejuvenating crystal, but that is the stuff of legends.", objectives = "Rescue 6 Refinery Workers and look for Munderut.", completion = "The workers told me that you helped them escape the refinery. Task complete! \n\nI'll take the clay back now. Gratitude." }
WordHunterWoW_QuestEN[79149] = { title = "Rampage in the Refinery", description = "Catastrophe! Oh, this is awful. Awful! Those accursed slag heap elementals are keeping my refinery workers from being able to do their jobs.\n\nDuty demands we carry on our work. These delays will not be tolerated. You look competent enough. Go on, get down there and get to work destroying elementals. Production must not be slowed!", objectives = "Kill 10 Rampaging Elementals.", progress = "Well? Did you destroy them? I need my crew back to work immediately!", completion = "What a terrible delay in production. The miners will have to work twice as hard to make up for lost time, I am afraid.\n\nIt is good you came around when you did. Those elementals are a menace. An awful menace!" }
WordHunterWoW_QuestEN[79150] = { title = "Thespians at the Proscenium", description = "When I wanted the Unbound to bring their plays to Dornogal, I didn't know what I would be up against. Or that my \"help\" would get in the way.\n\nMy old friend Brokfor keeps interrupting us with his perfectionism. We try to build a set, but he stops everyone to inspect each nail. We try to paint, he complains the colors do not exactly match... you get the idea.\n\nI think Brokfor needs his own project. Maybe... cleaning up the Proscenium? Go ask him to help and keep him occupied.", objectives = "Help Architect Brokfor clean up the Proscenium.", progress = "Have you helped Brokfor straighten up?", completion = "Excellent! Now we can perform our tasks without his perfectionism getting in the way." }
WordHunterWoW_QuestEN[79151] = { title = "An Orphan's Request", description = "Wow, you look really strong! Would you be able to help me?\n\nMy parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. \n\nCould you go get it for me?", objectives = "Retrieve Alyza's Much Loved Teddy Bear from the Hungering Pool in Hallowfall.", progress = "I will make the kobyss regret ever setting foot in these lands.", completion = "Fine, fine. I guess I don't mind if you come help.\n\nYou do actually look big, and strong." }
WordHunterWoW_QuestEN[79152] = { title = "Gutting the Pool", description = "The kobyss are... a bit larger than I expected, and I might--might, you understand?--have more trouble with them than I originally anticipated.\n\nKill any stupid fish-faces you see.", objectives = "Kill 10 kobyss in The Hungering Pool in Hallowfall.", progress = "Yes, make them bleed. Make them pay!", completion = "You've killed a lot of them.\n\nI wouldn't mind if you killed more. Just saying." }
WordHunterWoW_QuestEN[79153] = { title = "Vae Victis", description = "Ah it's time.\n\nKill their leader. Salt his bones, take his head, and laugh as his tribe crumbles!\n\nSharpscale's last moments are upon him, and he doesn't even realize it yet. \n\nStupid fish-face.", objectives = "Kill Sharpscale the Devourer and retrieve its head in the Hungering Pool in Hallowfall.", progress = "His skull would make a good cup I think? Perhaps a mantle ornament?", completion = "Oh. This head is quite a bit more icky than I was expecting. You can keep that.\n\nYou are much more useful than I thought you would have been, <name>." }
WordHunterWoW_QuestEN[79154] = { title = "A Final Goodbye", description = "Well, parents avenged, fish killed, more fish killed, biggest fish killed. \n\nPretty good day.\n\nI guess I should go burn stuff.", objectives = "Help Alyza say goodbye in the Hungering Pool in Hallowfall.", completion = "Thanks, <name>. I'll make sure to put in a good word with General Steelstrike for you. I know her well. \n\nWell, I met her once. \n\nWell, I saw her in the street.\n\nBut I did think about talking to her, so it's the same thing really." }
WordHunterWoW_QuestEN[79156] = { title = "The Edicts", description = "Merrix and Adelgonn will be expecting an update. On my way here, I heard that they're all heading to the Proscenium to commit to the war officially. You should go and brief them on the readiness of the Stormriders.\n\nI'd like a moment with Zarein here. But we'll be along soon. And we'll be bringing Baelgrim's spirit with us.", objectives = "Report to Merrix and Adelgonn.", progress = "This is a critical moment for all earthen.", completion = "Titans... what have they done?" }
WordHunterWoW_QuestEN[79157] = { title = "Titanic Failsafe", description = "So, the titans sent their ancient machines against their disobedient children.\n\nWould our creators have us protect the Coreway at the expense of all else? At the expense of Azeroth herself? Are we meant to preside over a road untraveled, leading to the world's dead heart?\n\nNo, today we are all Unbound, and we will fight for our freedom. For Azeroth!", objectives = "Defeat the colossal titan construct.", progress = "None on this isle will be safe until that titan construct is dealt with. Go!", completion = "It was a trial by fire, but you've proven that the earthen of The Isle of Dorn are ready for the war to come. Where once there was discord, there is now unity of purpose. They are no longer Oathsworn or Unbound. They are united, just as we should be, against this darkness." }
WordHunterWoW_QuestEN[79158] = { title = "Seeds of Salvation", description = "These once obedient harvestbots have run amok and are wreaking havoc in our fields.\n\nThe success of our community depends on getting our seeds in the ground, but most of the seeds are in the hands of those harvesters!\n\nWould you venture into the fields, eliminate any rogue machines, gather the seeds, and finish the planting?", objectives = "Recover Harvest Seeds and plant 8 seeds in Seed-Ready Soil.", progress = "Have you planted the seeds?", completion = "You've truly done us a great service! Planting those seeds buys us valuable time until the harvestbots are repaired." }
WordHunterWoW_QuestEN[79159] = { title = "Dereliction of Duty", description = "A moment, if you have one.\n\nOne of my lieutenants, Shinda Creedpike, did not report in at first bonfire. That may not seem like a large issue to you, but the Arathi in Hallowfall survive only because we follow orders and stand for our brethren.\n\nI am not cruel. I do not want to punish a man for his weakness in this terrible environment. Can you find him and bring him back? \n\nTake all the time you need.", objectives = "Find Shinda Creedpike at Mereldar in Hallowfall.", progress = "Dawnsurge must have sent you.\n\nIt seems like my respite is over.", completion = "You're speaking my language, <name>. Plans give me structure and a goal to achieve.\n\nLet me think about the optimal way to relax." }
WordHunterWoW_QuestEN[79160] = { title = "Fishing is Good for the Soul", description = "I used to fish with my mother at the local pond when I was a child. It wasn't the fish that made the experience--my mother was famously terrible at cooking--but the tranquility and bonding time.\n\nPerhaps I could find a portion of that peace again here. There's a spot south of Mereldar that the others use to fish. I'll meet you there!", objectives = "Meet Shinda at the fishing hole.", progress = "Maybe I can find peace in the act of fishing.", completion = "I wish we could have fished. But if today confirmed anything to me, I have relearned a valuable truth.\n\nIf I lay down my sword, these children would have to pick them up if they are to survive this place. They have known no other place than this land.\n\nThey will see our homeland. They must see our homeland." }
WordHunterWoW_QuestEN[79162] = { title = "Burnout", description = "Please return to Commander Dawnsurge and give them my sincere apologies for my absence. I will submit myself for punishment for my trespass after my shift.", objectives = "Return to Endiri Dawnsurge in Mereldar.", completion = "I will not institute any punishment for his absence. I'm simply glad you were there to support him when I could not.\n\nWe are living in times of prophecy, <name>. It is a curse I would not bestow upon anyone. We must do what we must to survive these days." }
WordHunterWoW_QuestEN[79165] = { title = "A Moment to Rest", description = "Good, you're both here. \n\nI have a favor to ask. \n\nFaerin's wandered off. I think it might help if you and your... disheveled friend here find her. \n\nShe'll be in Light's Redoubt.", objectives = "Find Faerin near Light's Redoubt.", completion = "<Anduin chews his lip, lost in thought.>" }
WordHunterWoW_QuestEN[79166] = { title = "Lost Pieces", description = "There was a time when I would have known what words to say to help her.\n\nBut now... they are as lost to me as everything else. \n\n<Anduin sighs.>\n\nThere must be something we can do. Her old Lamplighter companion, this Andari... would have had one of those tinderboxes, right? They seem important for funeral rites. \n\nI'll accompany Faerin back to Mereldar and meet you there. If you think there's hope of finding Andari's lost belongings... could you try to look?", objectives = "Collect 8 Lost Personal Effects from enemies in the Harrowing Depths.", progress = "There's no time to mourn. Not when there's fighting to be done. If you have time to mourn, you have time to train. \n\nTo make sure we don't lose anyone else.", completion = "You found their things? In all the darkness? \n\nThank you. \n\nAnd this, this is..." }
WordHunterWoW_QuestEN[79167] = { title = "Crowdsourcing", description = "Light's Gambit is an old and honored game. There's a reason so many Arathi play it! \n\nIt can teach you a lot about strategy. And it can tell you a lot about your opponents. \n\n<Faerin suddenly deflates.> \n\nBut we're still missing a few pieces that we need in order to play.\n\nSometimes, folks around Mereldar lend us pieces for a game. Could you ask around?", objectives = "Collect 4 Game Pieces from Arathi in Mereldar.", progress = "The rules are a bit lengthy but trust me... it's worth it!", completion = "We... might have gotten a bit ahead of ourselves." }
WordHunterWoW_QuestEN[79168] = { title = "Light's Gambit", description = "It's fine! We can catch you up on the rest of the rules later!\n\nResolving combat is the most fun, anyway!\n\nYou and Anduin can team up against me. Perhaps with the both of you together, you'll stand a chance!\n\n<Faerin laughs.>", objectives = "Grab the castle piece to start a game of Light's Gambit with Faerin and Anduin.", completion = "I hope you found that relaxing, too, <name>. I didn't realize how much we all needed a break." }
WordHunterWoW_QuestEN[79173] = { title = "Supply the Effort", description = "When shadow fell upon our town, many necessary supplies were taken in the cover of darkness.\n\nWith the light returning, it is time to rebuild, but first, we must retrieve what was lost. \n\nSearch the surrounding areas, recover any supplies that might be useful.", objectives = "Recover various stolen items from the surrounding area to satisfy our needs.", progress = "Have you recovered the stolen items?", completion = "You have recovered far more than we could have hoped.  I've set some of the extras aside for you to have." }
WordHunterWoW_QuestEN[79174] = { title = "Infested Infestation", description = "These spore-afflicted beasts at Pillar-nest Vosh been a thorn in our side since setting up Faerin's Advance. They be spreading thick clouds of spores. I never be seeing anything like it!\n\nThey already attacked once. Won't be long till they attack again. If we got any hope of survivin', we need to cull dere numbers. \n\nGo to Pillar-nest Vosh and take some of those spore-afflicted beasts out!", objectives = "Kill 12 spore-afflicted beasts at Pillar-nest Vosh.", completion = "With de number of those spore-afflicted beasts reduced, we bought more time ta think of a more permanent solution." }
WordHunterWoW_QuestEN[79175] = { title = "I Think I'm a Drone Now", description = "There, I have extended some goodwill. You have a little goblin friend. I know how much your kind clings to each other for warmth.\n\nAnd now you both will do things for me. First, I will provide you with my pheromone scent mark. It will keep my loyal soldiers from attacking you. It marks you as mine.", objectives = "Allow Anub'azal to mark you with his pheromones.", progress = "Don't waste my time. Are you ready to accept my mark? Step into the pheromone cloud with your <race> friend, and rub it on.", completion = "Your friend complains, but my mark will keep you relatively safe, except from Zev'kall's guards. They won't care about scent marks if they are already hostile to me.\n\nSo make the most of it, but take care." }
WordHunterWoW_QuestEN[79176] = { title = "Opals and Runes", description = "You have certainly made my disaster of a day far less stressful, {name}. \n\nFor that, you have the thanks of the entire Forgegrounds and those who keep it running.\n\n<Vokgret winks as she gives you a knowing smile.>\n\nBevrusi was right to send you to me. Do tell her not to be a stranger now. I could use more friends from the Deeps.\n\nHere is her liquid opal. Give it to her with my compliments.", objectives = "Trade the Vial of Liquid Opal for the Speakeasy Passrune from Bevrusi.", progress = "Everyone in the city is in need of something, and there is always someone with the means to acquire it.", completion = "I send you to a Machine Speaker to get us into the speakeasy, and you wind up aiding the market reeve of the Forgegrounds in some roundabout delivery and trading operation?\n\n<Merrix smirks coyly as he claps his heavy stone hands in applause. It is a much quieter sound than you would imagine.>\n\nWell done, my resourceful outlander." }
WordHunterWoW_QuestEN[79178] = { title = "Play Hearthstone!", description = "It's time to play Hearthstone! \n\nHere's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play!\n\nOr if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", objectives = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table.", progress = "Like the game so far? Give it a chance and play those cards!", completion = "How did you do? Had some good, clean fun I'm sure!" }
WordHunterWoW_QuestEN[79184] = { title = "It's Hearthstone's Anniversary!", description = "\"Hearthstone's been played for ten years, can you believe it?\n\nI'm hosting Hearthstone games in Valdrakken, way up in the Seat of the Aspects. Come join us!\n\n-Farala, Master of Ceremonies\"", objectives = "Speak with M.C. Farala in Valdrakken, in the Seat of the Aspects.", completion = "Welcome to the celebration! Now get out there and join the fun!" }
WordHunterWoW_QuestEN[79186] = { title = "It's Hearthstone's Anniversary!", description = "Hearthstone's been played for ten years, can you believe it?\n\nFarala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!", objectives = "Speak with M.C. Farala in Stormwind." }
WordHunterWoW_QuestEN[79189] = { title = "It's Hearthstone's Anniversary!", description = "\"Hearthstone's been played for ten years, can you believe it?\n\nFarala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!", objectives = "Speak with M.C. Farala in Durotar.\"Hearthstone's been played for ten years, can you believe it?\n\nFarala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[79193] = { title = "Spinning Spore Spines", description = "Orsenth sent you? And we are supposedly fused? Why... so I am wearing a medallion. But I have no memory... Well, no time for that.\n\nDid you see the spinning spores on your way here? I need the spines that they grow for... I need them for... now what was it again? Oh yes! There is no better instrument for carving out the fine detail that my work as a gem carver requires than those spines. Will you collect some?\n\nI will make my way back to the refinery. I am eager to get back and meet this Orsenth.", objectives = "Collect 150 Spore Spines for Munderut.", progress = "Why, what is this now? You're a stranger to these depths, are you not? What are you doing here?\n\n<You remind him of all you've spoken of.>\n\nWell, what are you waiting for? Go and get me those spines!", completion = "Where did you come from? Who are you?\n\nI do not know how you knew I needed these spines, but I thank you. There is no better instrument for carving out the fine detail that my work as a gem carver requires. I am a gem carver, you see!\n\nHave you met my new friend Orsenth? What- what was I saying?" }
WordHunterWoW_QuestEN[79194] = { title = "To the Source", description = "Orsenth told me you have been instrumental in dealing with the elemental problem here at the mine. I am Keldaz, supervisor for the militia. We came as soon as word of the attack reached us in Gundargaz. The miners you rescued said that the elementals poured out of the northeast mine shaft. \n\nI will leave some of my guards here to lend their support and have sent for reinforcements. If you are still willing to help, meet me outside the cave and let us see what we can do to staunch the flow of elementals.", objectives = "Meet Keldaz outside of the northeastern mine.", completion = "Ah, <name>, you made it. We did as well, but were attacked often on our way over. Unfortunately, Nanthaz took a heavy blow and needs time to recover." }
WordHunterWoW_QuestEN[79196] = { title = "Renowned with The Severed Threads", description = "The Weaver has been keeping an eye on you. She has determined you would be a better asset with more resources at your disposal.\n\nCome to the Weaver's Lair. I have a parcel waiting for you.", objectives = "Speak with Lady Vinazian in the Weaver's Lair.", completion = "For services rendered and services yet to be rendered, accept this with The Weaver's compliments." }
WordHunterWoW_QuestEN[79197] = { title = "Surface Bound", description = "{name}, the moment is upon us. We must make haste to the city of Dornogal, where our allies await. \n\nOnly together do we stand a chance against Harbinger's machinations.", objectives = "Meet with Moira Thaurissan and your allies in Dornogal in the Isle of Dorn.", completion = "I am glad to see you all back safely from your journey." }
WordHunterWoW_QuestEN[79199] = { title = "Renowned with Keg Leg's Crew", description = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer!\n\nReturn to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.You will receive:", objectives = "Speak with Cataloger Jakes at the Dragonscale Basecamp.Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer!\n\nReturn to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.You will receive:" }
WordHunterWoW_QuestEN[79200] = { title = "Who am I?", description = "It's good to see you're awake. I know you must have many questions and we are here to answer them. I am Dawn, and this is Foreman Uzjax.\n\nMany things have changed since your last slumber began, including our Awakening Protocol. We are both here to guide you through it.\n\nLike many other newly awakened, you have heard a distant yet powerful song thrumming within you. A radiant surge of change. \n\nEmbrace it.", objectives = "Complete the first stage in the Awakening Protocol.", completion = "I want to reassure you. You are not flawed.\n\nThis protocol was designed to detect 'anomalies' within the <race>. Anomalies such as that surge you felt.\n\nBut they are not anomalies. Not anymore." }
WordHunterWoW_QuestEN[79201] = { title = "The Analysis Interface", description = "This is the Analysis Interface. \n\nIn order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. \n\nAlthough Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully.\n\nProceed when ready.", objectives = "Complete the Analyzing Sequence in the Analysis Interface.", completion = "Who you were, who you are and who do you want to be? \n\nAll questions every <race> from now on will be allowed to ask.\n\nOur fate and our purpose is ours to choose." }
WordHunterWoW_QuestEN[79202] = { title = "Rock Beats Rock", description = "Welcome to the Procedural Forum.\n\nForeman Uzjax informs me that this chamber once served as our assignment testing facility. \n\nWith his guidance, we've repurposed this chamber.\n\nEarthen are not combat trained by design, so this room serves to prepare newly awakened earthen for the challenges of the unexplored world that lies ahead.", objectives = "Spar with 6 newly Awakened Earthen.", progress = "Whether they were once Storm Riders or Peacekeepers or craftsman and laborers, martial prowess takes time to hone and refine.", completion = "Combat doesn't come naturally to most <race> and yet again, you exceed expectations.\n\nYour training is exceptionally well-timed. It would seem we have an unexpected obstacle that lies ahead. \n\nSpeaker Kuldas can explain further." }
WordHunterWoW_QuestEN[79203] = { title = "Authorization: Negated", description = "The Bulwark of Authorization! That's what this chamber was once called.\n\nI had been working tirelessly to reconfigure it to its original state, when suddenly the whole blasted chamber started rumbling. \n\nA golem manifested out of nowhere and started attacking my machinists! We managed to escape, but the Golem locked down the chambers.\n\nDawn seems to think you've got what it takes to deal with it. Up to the challenge?", objectives = "Defeat the Phalanx of Authorization within the Bulwark of Authorization.", completion = "I've seen that room come to life more times than I care to admit, <name>. But that was something else entirely! \n\nI can't help but wonder where that golem came from. It certainly wasn't of <race> make.\n\nJust when I thought I knew everything about this old place, it throws another tool in the cogs.\n\nWell, back to work!" }
WordHunterWoW_QuestEN[79204] = { title = "Whoever You Want to Be", description = "After an awakening protocol like that, I can see why Dawn says you're special.\n\nThe world is not prepared for an earthen like you. \n\n<Kuldas claps you on the back with a gravely chuckle.>\n\nDawn and the Foreman are waiting for you in the Awakening Vestibule.\n\nGo on, then! \n\nComplete your Awakening Protocol and get out of here!", objectives = "Speak with Dawn to complete your Awakening Protocol.", completion = "Upon completion of their Awakening Protocol, <race> would leave these halls and venture into the Ringing Deeps and beyond to their assigned jurisdiction.\n\nTheir purpose was chosen for them. But not anymore.\n\nThe fate of our people is for us and us alone to decide.\n\nWhat you do and where you go is up to you." }
WordHunterWoW_QuestEN[79205] = { title = "Not Waste, Not Want", description = "Everything have use, friend. Even things stoneheads throw away and think worthless.\n\nKobolds know better.\n\nGo and see what you can find. Need to scavenge lots of scrap. Enough for kobold crafting of new homes!", objectives = "Collect potentially useful scrap from around the Warrens.", progress = "You will be surprised. Kobold crafting is amazing!", completion = "Not bad for |5human. We make good use of this.\n\nMost of it, anyway. Sometimes, one person's trash is really just trash." }
WordHunterWoW_QuestEN[79206] = { title = "Broken Memories", description = "Something about this particular gemstone feels important. Perhaps it would be worthwhile to bring it to Speaker Brinthe.", objectives = "Bring the Faded Memory Gem to Brinthe.\n\nProvided item:", completion = "Earthen use these gems to hold memories we would otherwise lose to the unrelenting march of time.\n\nWhen an earthen goes into stasis, we sometimes use a memory gem to witness their final moments.\n\nDuring our lives, we use them to carry our precious memories to the Archive, where they can be stored. Then we recharge our bodies and renew our minds in the Awakening Machine.\n\nThank you for returning this, <name>. Even shattered and faded, it's still precious." }
